import type { Prompt } from "../prompt-types";

export const TECHNOLOGY_PROMPTS: Prompt[] = [
  // ---- Technology (1025) ----
  { id: "technology-1", title: "Choose the right phone for you", category: "technology", text: "Help me choose a new phone within a budget of ₹[amount]. I mainly use it for [calls, WhatsApp and photos / work and videos]. Compare 3 options available in India, and list the battery, camera, storage and warranty of each in simple words." },
  { id: "technology-2", title: "Set up a new phone step by step", category: "technology", text: "Give me a simple step-by-step guide to set up a new Android phone [brand and model]. Cover inserting the SIM, connecting to Wi-Fi, signing in, moving contacts and photos from the old phone, and the first settings I should change for safety." },
  { id: "technology-3", title: "Make your phone battery last longer", category: "technology", text: "My phone battery drains too fast by evening. Explain in simple words why this happens, then give me 10 practical steps to make the battery last longer each day, without buying a new phone or a power bank for [your phone model]." },
  { id: "technology-4", title: "Free storage space on your phone", category: "technology", text: "My phone says storage is almost full. Tell me how to check what is using the most space, then give safe steps to delete junk files, old videos and unused apps without losing my photos, important chats or [other files I need]." },
  { id: "technology-5", title: "Find the best apps for daily use", category: "technology", text: "Suggest 8 useful free apps for a beginner in India for [travel, payments, news and learning]. For each app, explain in one line what it does, why it is useful, and whether it needs mobile data to work." },
  { id: "technology-6", title: "Buy your first laptop with confidence", category: "technology", text: "Help me buy a laptop for [study / office work / watching videos] within ₹[amount]. Explain in simple words what RAM, storage and processor mean, then suggest 3 good options and the questions I should ask the shopkeeper." },
  { id: "technology-7", title: "Set up Wi-Fi at home easily", category: "technology", text: "Explain how to set up Wi-Fi at home in simple steps. Cover choosing a broadband plan in [your city], placing the router, setting a strong password, connecting phones and laptops, and what to do when the signal is weak." },
  { id: "technology-8", title: "Send your first professional email", category: "technology", text: "Teach me to write a polite professional email to [a shop / a teacher / an office]. Give me a clear subject line, a short opening, the main message in 4 lines, and a proper closing with my name and phone number." },
  { id: "technology-9", title: "Organise files on your computer", category: "technology", text: "My computer files are all over the place. Give me a simple folder system for [photos, bills, school work and office files], with clear folder names, and steps to move everything into the right place in one hour." },
  { id: "technology-10", title: "Join a video call without stress", category: "technology", text: "I have my first video call tomorrow for [a job interview / a family function]. Give me a step-by-step checklist for joining, testing my camera and microphone, fixing bad light, and what to do if the call drops." },
  { id: "technology-11", title: "Use WhatsApp groups without the noise", category: "technology", text: "My WhatsApp groups, like [family group name], send too many messages every day. Explain how to mute a group, stop photos from downloading automatically, leave a group politely, and keep only the important messages easy to find later." },
  { id: "technology-12", title: "Share photos safely on WhatsApp", category: "technology", text: "Show me how to send photos on WhatsApp from [your phone] in the best quality, send a photo that can be viewed only once, and check who has seen my message. Also explain how to stop strangers from adding me to random groups." },
  { id: "technology-13", title: "Write a clear WhatsApp status update", category: "technology", text: "Help me write a short WhatsApp status to announce [my shop is closed on Sunday / my new phone number]. Keep it polite and under 3 lines, add the timings clearly, and suggest a simple photo or emoji-free design idea." },
  { id: "technology-14", title: "Grow a small shop on Instagram", category: "technology", text: "I run a small [tailor shop / food stall] in [your city] and want customers from Instagram. Give me a simple 30-day plan: what to post each week, how to write captions, and how to reply to people who message me." },
  { id: "technology-15", title: "Find useful videos on YouTube", category: "technology", text: "Teach me to use YouTube well. Show how to search for [cooking lessons / exam help], save videos to watch later, turn on subtitles, slow down a fast video, and avoid wasting time on videos I do not need." },
  { id: "technology-16", title: "Pay safely with UPI every day", category: "technology", text: "Explain UPI payments to a beginner in simple words. Cover how to send ₹[amount] by scanning a QR code, how to check the receiver's name before paying, daily limits, and what to do if money is sent to the wrong person." },
  { id: "technology-17", title: "Spot a fake payment message", category: "technology", text: "I got a message saying my [bank name] account will be blocked unless I click a link. Explain why this is likely a scam, list 5 warning signs in such messages, and tell me exactly what to do instead of clicking." },
  { id: "technology-18", title: "Create strong passwords you can remember", category: "technology", text: "Help me create strong passwords for my [bank app / email / shopping apps] that I can still remember. Explain what makes a password weak, give a simple method to build one, and how to store passwords safely." },
  { id: "technology-19", title: "Keep your OTP safe from fraud", category: "technology", text: "Explain in simple words what an OTP is and why I must never share it with anyone, even if the caller says they are from my bank. List 3 common tricks fraudsters use to get OTPs from people in [your city], and what to do if I shared one by mistake." },
  { id: "technology-20", title: "Pay a shop bill by scanning QR", category: "technology", text: "Give me a simple guide to paying ₹[amount] at a shop by scanning a QR code with my phone. Cover opening the payment app, checking the shop name and amount, entering my PIN safely, and confirming the payment went through." },
  { id: "technology-21", title: "Back up your phone photos safely", category: "technology", text: "My phone has [number] years of family photos and I am afraid of losing them. Explain how to back them up to the cloud and to a laptop, step by step, and how to check the backup really worked before deleting anything." },
  { id: "technology-22", title: "Fix a slow phone in ten minutes", category: "technology", text: "My [phone brand and model] has become very slow and apps take long to open. Give me a simple 10-minute fix: closing background apps, clearing cache, removing heavy apps, restarting the phone, and when I should visit a repair shop." },
  { id: "technology-23", title: "Recover deleted photos from your phone", category: "technology", text: "I accidentally deleted important photos of [a family function] from my phone yesterday. Explain where deleted photos go first, how to restore them within 30 days, and what to try if they are already gone from the recycle bin." },
  { id: "technology-24", title: "Understand a strange error message", category: "technology", text: "My [phone / laptop] shows an error message I do not understand: [type the message here]. Explain in simple words what it means, list the 3 most likely causes, and give safe steps I can try before asking a technician." },
  { id: "technology-25", title: "Decide when to repair or replace", category: "technology", text: "My [phone / laptop] is [3 years old] and keeps hanging. Help me decide whether to repair it or buy a new one. Compare repair cost, remaining life, and new prices in ₹, then give a clear recommendation with reasons." },
  { id: "technology-26", title: "Choose a phone under a budget", category: "technology", text: "Help me choose a new phone with a budget of [₹15,000]. I mainly use it for calls, WhatsApp, photos and YouTube. Compare three good options, list their screen size, battery, camera and storage, and say which one suits a beginner best." },
  { id: "technology-27", title: "Compare two phones before buying", category: "technology", text: "Compare these two phones for me: [phone A] and [phone B]. I want to know which has a better camera, longer battery life, faster speed and clearer screen. Explain the differences in simple words and tell me which one I should buy." },
  { id: "technology-28", title: "Pick a phone for my mother", category: "technology", text: "Suggest a simple phone for my mother, aged [65], who only makes calls, uses WhatsApp and watches devotional videos. It should have big text, loud sound and a long-lasting battery. Give three options under [₹12,000] with their main features." },
  { id: "technology-29", title: "Pick a phone for school online classes", category: "technology", text: "My child needs a phone for online classes and homework. Suggest a phone under [₹14,000] with a big clear screen, good front camera and enough storage for school apps. List three options and explain why each one is good for study." },
  { id: "technology-30", title: "Understand phone storage before buying", category: "technology", text: "Explain in simple words what 64 GB, 128 GB and 256 GB storage mean on a phone. I take many photos and use WhatsApp a lot. Tell me how much storage I need, what happens when it fills up, and which size is best for me." },
  { id: "technology-31", title: "Understand RAM on a phone", category: "technology", text: "Explain what RAM means on a phone in very simple words, like you are telling a beginner. Tell me the difference between 4 GB, 6 GB and 8 GB RAM, how it affects speed, and how much RAM I need for daily use and light games." },
  { id: "technology-32", title: "New phone or second-hand phone", category: "technology", text: "Should I buy a new phone or a second-hand phone with a budget of [₹10,000]? List the advantages and risks of each choice in simple words. Tell me what to check before buying a used phone and when a new phone is the safer choice." },
  { id: "technology-33", title: "Checklist before buying a phone", category: "technology", text: "Give me a simple checklist to use before buying a new phone from a shop. Include what to check on the bill, warranty card, box seal, screen, camera and battery. Tell me which questions to ask the shopkeeper so I do not get cheated." },
  { id: "technology-34", title: "Choose between Android and iPhone", category: "technology", text: "Explain the difference between an Android phone and an iPhone in simple words for a beginner. Compare their price, ease of use, apps, battery and repairs. Then ask me three questions and suggest which type suits my needs and budget of [₹30,000]." },
  { id: "technology-35", title: "Find a phone with a good camera", category: "technology", text: "I want a phone mainly for taking family photos and festival pictures. Suggest three phones under [₹20,000] with good cameras. For each one, explain the camera features in simple words and say what kind of photos it takes best." },
  { id: "technology-36", title: "Find a phone with long battery life", category: "technology", text: "Suggest three phones under [₹18,000] known for long battery life. I use my phone all day for calls, videos and WhatsApp. For each phone, tell me the battery size in simple terms, how long it may last, and how fast it charges." },
  { id: "technology-37", title: "Choose a phone for watching videos", category: "technology", text: "I watch YouTube and films on my phone every evening. Suggest three phones under [₹16,000] with a big bright screen and good sound. Explain the screen size, sound quality and battery of each one in simple words for a beginner." },
  { id: "technology-38", title: "Choose a phone for a small shop", category: "technology", text: "I run a small shop in [your town] and need a phone for UPI payments, customer calls and WhatsApp orders. Suggest three phones under [₹15,000] that are sturdy, have long battery life and work well all day. Explain why each one suits a shopkeeper." },
  { id: "technology-39", title: "What to do with my old phone", category: "technology", text: "I am buying a new phone and do not know what to do with my old one. Explain my options in simple words: keep it as a spare, give it to a family member, sell it, or exchange it. Tell me how to erase my photos and accounts safely before giving it away." },
  { id: "technology-40", title: "Move data to a new phone", category: "technology", text: "Explain step by step how to move my contacts, photos, WhatsApp chats and apps from my old phone to my new phone. Use very simple words and number each step. Tell me what to check at the end so I know nothing important is missing." },
  { id: "technology-41", title: "Set up a new phone safely", category: "technology", text: "Give me a simple step-by-step guide to set up my brand-new phone. Include creating an account, setting a screen lock, connecting to Wi-Fi, updating the software and installing only the apps I need. Use short clear steps a beginner can follow alone." },
  { id: "technology-42", title: "Choose a phone for an elderly father", category: "technology", text: "My father is [70] years old and finds smartphones confusing. Suggest a phone with large buttons or large text, simple menus and an SOS button if possible. Give three options under [₹10,000] and explain the best features of each one simply." },
  { id: "technology-43", title: "Buy a phone during a sale", category: "technology", text: "A big online sale is coming and I want to buy a phone for [₹20,000]. Tell me how to plan for the sale, compare the real price with the usual price, check offers and exchange deals, and avoid buying a phone I do not need just because it is cheap." },
  { id: "technology-44", title: "Check if a phone price is fair", category: "technology", text: "A shop is selling [phone model] for [₹17,999]. Help me check if this price is fair. Tell me where to compare prices, what the usual price range is, which extra charges to watch for, and what questions to ask before I pay." },
  { id: "technology-45", title: "Pick a phone for travel and maps", category: "technology", text: "I travel by train and bus often and need a phone for maps, tickets and photos. Suggest three phones under [₹18,000] with good battery, bright screens for sunlight and enough storage. Explain why each one is useful for a frequent traveller like me." },
  { id: "technology-46", title: "Understand a phone warranty", category: "technology", text: "Explain a phone warranty in simple words. What does a one-year warranty cover and what does it not cover? Tell me what to do if my phone stops working, which papers to keep, and when it is better to pay for a repair instead." },
  { id: "technology-47", title: "Choose a phone for a college student", category: "technology", text: "Suggest a phone for a college student with a budget of [₹22,000]. It will be used for classes, notes, photos, music and light games. Compare three options on battery, storage, camera and speed, and say which one gives the best value for money." },
  { id: "technology-48", title: "Phone with dual SIM explained simply", category: "technology", text: "Explain what dual SIM means on a phone in very simple words. Tell me why some people use two SIM cards, how to choose which SIM is for calls and which is for internet, and how to switch between them. Give one everyday example from Indian life." },
  { id: "technology-49", title: "Choose a sturdy phone for rough use", category: "technology", text: "I work outdoors and my phone often falls or gets dusty. Suggest three sturdy phones under [₹20,000] that can handle rough use. For each one, explain its toughness, battery life and screen protection in simple words a beginner can understand." },
  { id: "technology-50", title: "First smartphone for a teenager", category: "technology", text: "My child is [14] years old and getting a first smartphone. Suggest three safe and simple phones under [₹15,000]. Explain how to set screen-time limits, block unsuitable content and keep the phone safe, using simple steps a parent can follow." },
  { id: "technology-51", title: "Compare phone offers in two shops", category: "technology", text: "Two shops are offering the same phone at different prices with different free gifts. Help me compare them fairly. Make a simple table of price, warranty, gifts and exchange value, then tell me which deal is truly better and why." },
  { id: "technology-52", title: "What is 5G on a phone", category: "technology", text: "Explain what 5G means on a phone in very simple words. Do I need a 5G phone today if I live in [your city]? Tell me the benefits, the extra cost, and whether my current 4G phone is still good enough for calls, videos and WhatsApp." },
  { id: "technology-53", title: "Choose a phone for good sound calls", category: "technology", text: "I make long calls every day and need a phone with clear loud sound. Suggest three phones under [₹14,000] with good speakers and call quality. For each one, explain the sound features simply and say who it is best suited for." },
  { id: "technology-54", title: "Phone buying plan for my family", category: "technology", text: "My family of [4] people needs new phones with a total budget of [₹50,000]. Plan who should get which type of phone based on age and use: calls only, study, photos or work. Give a simple plan with a phone suggestion and price for each person." },
  { id: "technology-55", title: "Avoid fake phones when buying", category: "technology", text: "Tell me how to spot a fake or duplicate phone before buying it from a shop or online. List the warning signs in simple words, explain how to check the IMEI number and bill, and say what to do if I suspect the phone is not genuine." },
  { id: "technology-56", title: "Make text bigger on my phone", category: "technology", text: "The text on my phone is too small to read comfortably. Explain step by step how to make the font size bigger on an Android phone and on an iPhone. Use simple words, number each step, and tell me how to make it even bigger if needed." },
  { id: "technology-57", title: "Turn on dark mode on my phone", category: "technology", text: "Explain what dark mode is and how to turn it on for my whole phone. Give simple steps for Android and iPhone separately. Tell me the benefits of dark mode at night and how to set it to turn on automatically every evening." },
  { id: "technology-58", title: "Set a screen lock on my phone", category: "technology", text: "Explain step by step how to set a PIN, pattern or fingerprint lock on my phone so nobody else can open it. Use very simple words and number each step. Also tell me what to do if I forget my PIN and how to keep my phone safe." },
  { id: "technology-59", title: "Change my phone wallpaper easily", category: "technology", text: "Show me how to change the wallpaper on my phone in simple steps. Explain how to choose a photo from my gallery, set it as the home screen or lock screen wallpaper, and adjust it so it looks nice. Mention how to use a free plain colour wallpaper too." },
  { id: "technology-60", title: "Turn off annoying notifications", category: "technology", text: "Too many apps keep sending me notifications all day. Explain step by step how to turn off notifications for one app and for all apps. Use simple words, give separate steps for Android and iPhone, and tell me how to keep only important alerts on." },
  { id: "technology-61", title: "Set an alarm on my phone", category: "technology", text: "Explain how to set a morning alarm on my phone for [6:00 am] on weekdays only. Give simple numbered steps for the clock app, tell me how to choose a gentle alarm sound, and explain how to set a second alarm ten minutes later as a backup." },
  { id: "technology-62", title: "Increase phone ringtone volume", category: "technology", text: "I often miss calls because my phone ring is too quiet. Explain how to increase the ringtone volume and choose a loud clear ringtone. Give simple steps for Android and iPhone, and tell me how to check that vibration is also turned on." },
  { id: "technology-63", title: "Turn on do not disturb mode", category: "technology", text: "Explain what Do Not Disturb mode does and how to turn it on before I sleep at night. Give simple steps, tell me how to allow calls from my family only, and how to set it to switch off automatically in the morning at [7:00 am]." },
  { id: "technology-64", title: "Change phone language to Tamil", category: "technology", text: "Explain step by step how to change my phone language from English to [Tamil]. Give simple numbered steps for Android and iPhone. Tell me what will change on the screen, how to type in Tamil afterwards, and how to switch back to English if needed." },
  { id: "technology-65", title: "Set the correct date and time", category: "technology", text: "My phone is showing the wrong time after I travelled to another city. Explain how to set the date and time correctly, turn on automatic time, and choose the right time zone for India. Use simple steps a beginner can follow in two minutes." },
  { id: "technology-66", title: "Turn Wi-Fi on and off", category: "technology", text: "Explain in simple words what Wi-Fi is and how to turn it on and off on my phone. Give numbered steps, tell me how to connect to my home Wi-Fi with a password, and explain what the Wi-Fi symbol at the top of the screen means." },
  { id: "technology-67", title: "Turn mobile data on and off", category: "technology", text: "Explain what mobile data is and how to turn it on and off on my phone. Give simple steps, tell me when I should use mobile data instead of Wi-Fi, and explain how to check how much data I have used today so I do not finish my pack early." },
  { id: "technology-68", title: "Turn on aeroplane mode explained", category: "technology", text: "Explain what aeroplane mode does on a phone and when to use it. Give simple steps to turn it on and off, tell me whether I can still listen to music or take photos in this mode, and explain why it is needed during a flight." },
  { id: "technology-69", title: "Adjust screen brightness for my eyes", category: "technology", text: "My phone screen feels too bright at night and too dim in sunlight. Explain how to adjust the brightness by hand and how to turn on automatic brightness. Give simple steps and tell me which setting is comfortable for reading in the evening." },
  { id: "technology-70", title: "Set screen to turn off quickly", category: "technology", text: "Explain how to set my phone screen to turn off after [30 seconds] so the battery lasts longer. Give simple numbered steps for Android and iPhone, and tell me why a short screen timeout is good for both battery life and privacy." },
  { id: "technology-71", title: "Turn on battery saver mode", category: "technology", text: "Explain what battery saver mode does and how to turn it on when my battery is low. Give simple steps, tell me which features it slows down, and explain when I should use it and when I should turn it off again after charging." },
  { id: "technology-72", title: "Allow location only when needed", category: "technology", text: "Explain what location permission means and how to control it for each app on my phone. Give simple steps to allow location only while using an app, and tell me why it is safer not to give every app my location all the time." },
  { id: "technology-73", title: "Turn Bluetooth on for earphones", category: "technology", text: "Explain how to turn on Bluetooth and connect my wireless earphones to my phone for the first time. Give simple numbered steps, tell me what to do if the earphones do not appear on the list, and how to disconnect them afterwards." },
  { id: "technology-74", title: "Set up fingerprint unlock safely", category: "technology", text: "Explain step by step how to add my fingerprint to unlock my phone quickly and safely. Use simple words and number each step. Tell me what to do if my finger is wet, and remind me to also keep a PIN as a backup." },
  { id: "technology-75", title: "Change my phone ringtone simply", category: "technology", text: "Show me how to change my phone ringtone to a simple pleasant tune in easy steps. Explain where to find the sound settings, how to listen to each ringtone before choosing, and how to set a different ringtone for one special contact." },
  { id: "technology-76", title: "Turn off auto brightness problems", category: "technology", text: "My phone screen keeps going dark on its own and I cannot read it. Explain why automatic brightness does this, how to turn it off, and how to set a fixed brightness that suits me. Give simple steps for Android and iPhone." },
  { id: "technology-77", title: "Organise apps on home screen", category: "technology", text: "My home screen is full of apps in a mess. Explain how to move apps, put similar apps together in a folder, and remove apps I do not use from the home screen without deleting them. Give simple steps a beginner can follow in ten minutes." },
  { id: "technology-78", title: "Update my phone software safely", category: "technology", text: "My phone is asking me to update its software. Explain what a software update is, why it is useful, and how to do it safely on Wi-Fi with enough battery. Tell me what to check before updating and what to do if the update takes a long time." },
  { id: "technology-79", title: "Check how much data apps use", category: "technology", text: "Explain how to see which apps use the most mobile data on my phone. Give simple steps, tell me how to stop one app from using data in the background, and suggest three easy ways to save data every month without missing important messages." },
  { id: "technology-80", title: "Set a daily screen time limit", category: "technology", text: "I spend too many hours on my phone every day. Explain how to check my daily screen time and set a simple limit for one app, like YouTube. Give easy steps, tell me what happens when the limit ends, and suggest a healthy daily target for a beginner." },
  { id: "technology-81", title: "Turn on auto-rotate for videos", category: "technology", text: "Explain what auto-rotate does and how to turn it on so videos fill the whole screen when I turn my phone sideways. Give simple steps, tell me how to lock the screen upright while reading in bed, and when to switch it off again." },
  { id: "technology-82", title: "Enable one-handed mode on phone", category: "technology", text: "My phone is too big to use with one hand. Explain what one-handed mode is and how to turn it on. Give simple steps for Android and iPhone, tell me how to bring the screen down within reach, and how to turn the mode off again." },
  { id: "technology-83", title: "Set emergency contact on phone", category: "technology", text: "Explain how to add an emergency contact and medical details on my phone so helpers can reach my family if something happens. Give simple numbered steps, tell me which details to add, and explain how to make the contact visible even when the phone is locked." },
  { id: "technology-84", title: "Turn on flashlight quickly", category: "technology", text: "Explain how to turn on the torch on my phone quickly when there is a power cut at night. Give simple steps for Android and iPhone, tell me how to adjust the brightness if possible, and how to turn it off so the battery is not wasted." },
  { id: "technology-85", title: "Reset phone settings without losing photos", category: "technology", text: "My phone settings are messed up after my grandson played with it. Explain how to reset only the settings without deleting my photos, contacts or apps. Give careful simple steps and warn me what will change, like Wi-Fi passwords and wallpaper." },
  { id: "technology-86", title: "Save a new contact correctly", category: "technology", text: "Explain step by step how to save a new contact on my phone with the name, mobile number and city. Use simple words and number each step. Tell me how to add a second number for the same person and how to check that the contact was saved." },
  { id: "technology-87", title: "Find a contact quickly by name", category: "technology", text: "I have more than 300 contacts and cannot find one name quickly. Explain how to search for a contact by typing the first few letters of the name. Give simple steps, tell me how to use the search bar, and what to do if two people have the same name." },
  { id: "technology-88", title: "Edit a wrong contact number", category: "technology", text: "I saved a wrong mobile number for my friend [name]. Explain step by step how to open the contact, edit the number, and save the change. Use simple words, tell me how to check the new number by calling it, and how to avoid saving the same person twice." },
  { id: "technology-89", title: "Delete a duplicate contact safely", category: "technology", text: "I have the same person saved three times with slightly different names. Explain how to find duplicate contacts, merge them into one, and delete the extras safely. Give simple steps and tell me how to check that I kept the correct number." },
  { id: "technology-90", title: "Add a photo to a contact", category: "technology", text: "Explain how to add a photo to a contact so I can see who is calling me. Give simple numbered steps, tell me how to choose a clear photo from my gallery or take a new one, and explain how to change the photo later if I want." },
  { id: "technology-91", title: "Create a family contacts group", category: "technology", text: "Explain how to create a group of my family contacts on my phone so I can message them all together. Give simple steps, tell me how to add and remove people from the group, and name the group something clear like [My Family]." },
  { id: "technology-92", title: "Block a spam caller number", category: "technology", text: "A strange number keeps calling me with offers I do not want. Explain step by step how to block that number on my phone so it cannot call me again. Use simple words, tell me how to unblock it later, and how to report it as spam." },
  { id: "technology-93", title: "Save an emergency number quickly", category: "technology", text: "Explain how to save important numbers like my doctor, nearest hospital and a family member so I can find them in seconds. Give simple steps, suggest a clear way to name them, and tell me how to add them to my favourites for quick dialling." },
  { id: "technology-94", title: "Back up my contacts safely", category: "technology", text: "Explain why I should back up my contacts and how to do it in simple steps. Tell me how to save them to my Google account or iCloud, how to check that the backup worked, and what to do if I lose my phone and need my contacts back." },
  { id: "technology-95", title: "Share a contact with my friend", category: "technology", text: "My friend wants the number of our family doctor. Explain step by step how to share a contact from my phone by WhatsApp or message. Use simple words, tell me what details will be shared, and remind me to ask the person first before sharing their number." },
  { id: "technology-96", title: "Add a birthday reminder for contacts", category: "technology", text: "Explain how to add birthdays to my contacts so my phone reminds me on the right day. Give simple steps, tell me how to add the date for one person, and explain how to check all the birthdays coming up in the next month." },
  { id: "technology-97", title: "Use favourites for quick calling", category: "technology", text: "Explain what the favourites list is in the phone app and how to add my five most-called people to it. Give simple steps, tell me how to call someone from favourites in one tap, and how to remove a person from the list later." },
  { id: "technology-98", title: "Find who called me yesterday", category: "technology", text: "I missed a call yesterday and do not know who it was. Explain how to open my recent calls list, find the number, see the time of the call, and save it as a contact if it is important. Give simple steps a beginner can follow." },
  { id: "technology-99", title: "Add a work contact with notes", category: "technology", text: "Explain how to save a work contact with the person name, company, job and a short note like [met at the trade fair in Chennai]. Give simple steps, tell me where to type the note, and how to search for the contact later using that note." },
  { id: "technology-100", title: "Clean up old contacts yearly", category: "technology", text: "I have many old contacts I no longer call. Explain how to clean up my contacts once a year in simple steps. Tell me how to spot numbers with no name, old shop numbers and duplicates, and how to delete them safely without losing important people." },
  { id: "technology-101", title: "Set a different ringtone for family", category: "technology", text: "Explain how to set a special ringtone for my family contacts so I know it is family calling without looking at the screen. Give simple steps, tell me how to choose a clear loud tune, and how to set it back to the normal ringtone later." },
  { id: "technology-102", title: "Recover a deleted contact", category: "technology", text: "I deleted a contact by mistake and need the number back. Explain in simple words what I can try: check the recycle bin, restore from my Google account or iCloud backup, and ask a family member. Tell me which step to try first and when it may be too late." },
  { id: "technology-103", title: "Save a contact from a missed call", category: "technology", text: "A new customer called me and I want to save the number. Explain step by step how to save a number from my recent calls list as a new contact. Use simple words, tell me how to add the name and shop, and how to check it saved correctly." },
  { id: "technology-104", title: "Sort contacts by first name", category: "technology", text: "My contacts are sorted in a confusing way and I cannot find names. Explain how to change the sorting so contacts appear by first name in alphabetical order. Give simple steps for Android and iPhone, and tell me how to switch back if I prefer surname order." },
  { id: "technology-105", title: "Add an address to a contact", category: "technology", text: "Explain how to add a home or shop address to a contact on my phone. Give simple steps, tell me which fields to fill like street, area and city, and explain how tapping the address can open maps and show me the way there." },
  { id: "technology-106", title: "Transfer contacts to a new phone", category: "technology", text: "Explain step by step how to transfer all my contacts from my old phone to my new phone using my Google account. Use simple words and number each step. Tell me how to check on the new phone that every contact arrived safely." },
  { id: "technology-107", title: "Hide a contact from my list", category: "technology", text: "Explain how to hide or show contacts from a particular account on my phone, for example only showing contacts saved on the phone and not from email. Give simple steps, tell me where the display setting is, and how to bring the hidden contacts back." },
  { id: "technology-108", title: "Call a contact using voice command", category: "technology", text: "Explain how to call a contact using my voice without touching the phone. Give simple steps to turn on the voice assistant, tell me exactly what to say like call [Amma], and explain what to do if it dials the wrong person." },
  { id: "technology-109", title: "Add a contact photo from WhatsApp", category: "technology", text: "Explain how to save a clear photo from WhatsApp and set it as a contact photo on my phone. Give simple steps, tell me how to crop the photo so the face is clear, and remind me to use a photo only with that person permission." },
  { id: "technology-110", title: "Keep contacts safe when changing SIM", category: "technology", text: "I am changing my SIM card and worry about losing my contacts. Explain in simple words where contacts are stored, how to check if they are on the phone or on the SIM, and how to move them safely before I remove the old SIM card." },
  { id: "technology-111", title: "Take a clear photo with phone", category: "technology", text: "Explain how to take a clear sharp photo with my phone camera in simple steps. Tell me how to hold the phone steady, tap to focus, use good light, and avoid shaky hands. Give five easy tips a beginner can practise at home today." },
  { id: "technology-112", title: "Use phone camera for family photos", category: "technology", text: "Explain how to take good family photos with my phone during a festival at home. Tell me where to stand, how to use natural light from a window, how to fit everyone in the frame, and how to take three shots so at least one is perfect." },
  { id: "technology-113", title: "Take a selfie that looks natural", category: "technology", text: "Explain how to take a natural-looking selfie with my phone in simple steps. Tell me how to hold the phone at eye level, find soft light, smile gently, and use the timer so I do not shake the phone. Give three common mistakes to avoid." },
  { id: "technology-114", title: "Use night mode for evening photos", category: "technology", text: "Explain what night mode is on a phone camera and how to use it for photos after sunset. Give simple steps, tell me to hold the phone very still for a few seconds, and explain when night mode helps and when normal mode is better." },
  { id: "technology-115", title: "Zoom without losing photo quality", category: "technology", text: "Explain how zoom works on a phone camera in simple words. Tell me why too much zoom makes a photo blurry, how to use a small zoom safely, and when it is better to walk closer to the subject instead of zooming in." },
  { id: "technology-116", title: "Organise photos into albums", category: "technology", text: "My phone gallery has thousands of mixed photos. Explain how to organise them into simple albums like Family, Festivals, Travel and Bills. Give easy steps to create an album, move photos into it, and find any photo quickly later." },
  { id: "technology-117", title: "Delete blurry photos in bulk", category: "technology", text: "Explain how to find and delete blurry, duplicate and accidental photos from my phone gallery in simple steps. Tell me how to select many photos at once, check them before deleting, and how to recover a photo from the bin if I delete it by mistake." },
  { id: "technology-118", title: "Share photos with family on WhatsApp", category: "technology", text: "Explain how to share ten festival photos with my family group on WhatsApp without losing too much quality. Give simple steps, tell me the difference between sending as a photo and as a document, and which option keeps the photos clearer." },
  { id: "technology-119", title: "Print photos from my phone", category: "technology", text: "Explain how to print photos from my phone in simple steps. Tell me how to choose the best photos, save them in full quality, send them to a nearby photo studio in [your city], and what size prints to ask for in a family album." },
  { id: "technology-120", title: "Back up phone photos automatically", category: "technology", text: "Explain how to back up my phone photos automatically so I never lose them if my phone breaks. Give simple steps for Google Photos and iCloud, tell me how to turn backup on only on Wi-Fi, and how to check that my photos are safe." },
  { id: "technology-121", title: "Take a photo of a document clearly", category: "technology", text: "Explain how to take a clear photo of a paper document like a bill or certificate with my phone. Tell me how to place the paper flat in good light, hold the phone straight above it, avoid shadows, and check that all the words are readable before saving it." },
  { id: "technology-122", title: "Use panorama mode for a landscape", category: "technology", text: "Explain what panorama mode is and how to use it to photograph a wide view like a beach or a temple gopuram. Give simple steps, tell me to move the phone slowly and steadily, and explain what to do if the photo comes out crooked." },
  { id: "technology-123", title: "Take good food photos at home", category: "technology", text: "Explain how to take appetising photos of home-cooked food with my phone. Tell me to use daylight near a window, shoot from above, keep the plate clean, and avoid using flash. Give five simple tips a beginner can try at the next family lunch." },
  { id: "technology-124", title: "Record a short video on phone", category: "technology", text: "Explain how to record a short clear video on my phone for a birthday wish. Give simple steps to open the camera, switch to video, hold the phone steady in landscape, speak clearly, and stop and save the video. Tell me how to play it back and share it." },
  { id: "technology-125", title: "Use front camera for video calls", category: "technology", text: "Explain how to use the front camera for a video call with my family. Give simple steps to check the light on my face, hold the phone steady, speak clearly, and switch between the front and back camera to show them something in my room." },
  { id: "technology-126", title: "Edit a photo on my phone", category: "technology", text: "Explain how to do a basic photo edit on my phone without any extra app. Tell me how to crop a photo, make it brighter, straighten it, and remove a small mistake. Give simple steps and remind me to save a copy before editing the original." },
  { id: "technology-127", title: "Set a family photo as wallpaper", category: "technology", text: "Explain how to set a favourite family photo as my phone wallpaper in simple steps. Tell me how to choose a clear photo, crop it to fit the screen, set it for the home screen or lock screen, and change it again later for a festival." },
  { id: "technology-128", title: "Find an old photo quickly", category: "technology", text: "I need to find a photo from last Diwali in my phone gallery. Explain how to search by date, place or person, and how to scroll quickly to that month. Give simple steps and tell me how to save that photo in a Diwali album for next time." },
  { id: "technology-129", title: "Take photos in bright sunlight", category: "technology", text: "Explain how to take good photos outdoors in bright Indian sunlight. Tell me to avoid shooting into the sun, find shade for faces, tap the screen to adjust brightness, and take the photo in the morning or evening for softer light. Give five simple tips." },
  { id: "technology-130", title: "Use burst mode for moving kids", category: "technology", text: "Explain what burst mode is and how to use it to photograph children who keep moving. Give simple steps to hold the button down, take many photos in a second, choose the sharpest one, and delete the rest so my storage does not fill up." },
  { id: "technology-131", title: "Scan a QR code with my phone", category: "technology", text: "Explain how to scan a QR code with my phone camera in simple steps. Tell me how to open the camera, point it at the code, wait for the link to appear, and check it carefully before tapping. Give one example of a safe QR code at a shop." },
  { id: "technology-132", title: "Take a screenshot on my phone", category: "technology", text: "Explain how to take a screenshot on my phone to save something I see on the screen, like a train ticket or a message. Give simple steps for Android and iPhone, tell me where the screenshot is saved, and how to share it with a family member." },
  { id: "technology-133", title: "Hide private photos in a folder", category: "technology", text: "Explain how to hide private photos in a locked folder on my phone so others cannot see them when they borrow it. Give simple steps for Android and iPhone, tell me how to move a photo there, and how to open the folder again with my PIN or fingerprint." },
  { id: "technology-134", title: "Free space by deleting old videos", category: "technology", text: "My phone is full because of old videos. Explain how to find the biggest videos in my gallery, check which ones I have already backed up, and delete the ones I no longer need. Give simple steps and tell me how much space I can save." },
  { id: "technology-135", title: "Use phone camera timer for groups", category: "technology", text: "Explain how to use the camera timer so I can join a group photo myself. Give simple steps to set a ten-second timer, place the phone on a steady table, press the button, and walk quickly into the group. Tell me how to take two tries for a good result." },
  { id: "technology-136", title: "Photograph a temple without flash", category: "technology", text: "Explain how to take respectful photos inside a temple without using flash. Tell me to check if photography is allowed, use natural light, hold the phone steady, and avoid disturbing other devotees. Give four simple tips for clear photos in low light." },
  { id: "technology-137", title: "Make a photo collage on phone", category: "technology", text: "Explain how to make a simple photo collage of four family photos on my phone without paying for an app. Give easy steps to choose the photos, arrange them in a grid, add a short caption, and share the collage with my family on WhatsApp." },
  { id: "technology-138", title: "Check photo quality before printing", category: "technology", text: "Explain how to check if a phone photo is good enough to print in a large size. Tell me how to zoom in to check sharpness, look for blur, and choose photos taken in good light. Give simple rules for small prints and for large wall-size prints." },
  { id: "technology-139", title: "Save photos from WhatsApp safely", category: "technology", text: "Explain how to save important photos sent on WhatsApp to my phone gallery so I do not lose them. Give simple steps, tell me how to stop WhatsApp from saving every photo automatically, and how to organise the saved photos into a family album." },
  { id: "technology-140", title: "Use grid lines for better photos", category: "technology", text: "Explain what grid lines are on a phone camera and how to turn them on. Tell me in simple words how to place the main subject on a grid line or crossing point, keep the horizon straight, and take a more balanced photo. Give one easy example with a garden scene." },
  { id: "technology-141", title: "Make my phone battery last longer", category: "technology", text: "My phone battery finishes before evening every day. Give me ten simple habits to make it last longer, like lowering brightness, closing unused apps and turning off Bluetooth. Explain each habit in one short line and say which three help the most." },
  { id: "technology-142", title: "Charge my phone battery correctly", category: "technology", text: "Explain the correct way to charge my phone battery in simple words. Tell me when to start charging, when to unplug, whether overnight charging is safe, and why I should use the original charger. Give five easy rules a beginner can follow every day." },
  { id: "technology-143", title: "Find which app drains my battery", category: "technology", text: "Explain how to check which app is using the most battery on my phone. Give simple steps, tell me how to see the battery use for today, and explain what to do if one app is draining too much, like limiting it or updating it." },
  { id: "technology-144", title: "Battery drains fast after update", category: "technology", text: "After a software update my phone battery drains much faster than before. Explain in simple words why this can happen, what to check first, and give five simple fixes to try, like restarting the phone and checking background apps, before I visit a service centre." },
  { id: "technology-145", title: "Use power saving mode on a trip", category: "technology", text: "I am travelling by train for a full day and need my phone battery to last. Explain how to turn on power saving mode, lower the brightness, download maps offline, and switch off extra features. Give a simple plan I can follow before I leave home." },
  { id: "technology-146", title: "Check my phone battery health", category: "technology", text: "Explain how to check the health of my phone battery in simple steps. Tell me what battery health percentage means, when a battery is still good, and when I should think about replacing it. Use simple words and give one clear example for a two-year-old phone." },
  { id: "technology-147", title: "Phone gets hot while charging", category: "technology", text: "My phone becomes hot while charging and I am worried. Explain in simple words why a phone can feel warm, when it is normal and when it is a warning sign. Tell me what to do, like removing the cover and using the original charger, and when to stop using it." },
  { id: "technology-148", title: "Save battery while watching videos", category: "technology", text: "I watch videos for two hours every evening and my battery drains quickly. Give me simple ways to save battery while watching, like lowering brightness, using Wi-Fi, downloading videos first, and turning off vibration. Explain each tip in one short simple line." },
  { id: "technology-149", title: "Battery saver for an old phone", category: "technology", text: "My three-year-old phone battery does not last half a day now. Give me a simple daily plan to make it last longer, including which settings to change, which apps to limit, and how to charge it. Tell me honestly when it is time to replace the battery." },
  { id: "technology-150", title: "Turn off background apps to save battery", category: "technology", text: "Explain what background apps are and how they use battery even when I am not using them. Give simple steps to see which apps run in the background, stop the ones I do not need, and explain why I should keep WhatsApp and calls running." },
  { id: "technology-151", title: "Charge phone in a power cut", category: "technology", text: "There is a power cut at home and my phone battery is at 20 percent. Give me a simple plan to save the remaining battery, including what to turn off, what to keep on for emergency calls, and how to charge it later from a power bank safely." },
  { id: "technology-152", title: "Use a power bank safely", category: "technology", text: "Explain how to use a power bank to charge my phone when I am travelling. Tell me how to choose a good power bank, how to connect the cable, how long it takes to charge, and how to store the power bank safely at home." },
  { id: "technology-153", title: "Fast charging explained in simple words", category: "technology", text: "Explain what fast charging means in very simple words. Tell me why some phones charge in one hour and others take three hours, whether fast charging harms the battery, and how to check if my phone and charger support fast charging." },
  { id: "technology-154", title: "Battery percentage not showing correctly", category: "technology", text: "My phone battery jumps from 40 percent to 10 percent suddenly. Explain in simple words why this happens on an old battery, what I can try at home like restarting and updating, and when I should get the battery checked at a service centre." },
  { id: "technology-155", title: "Set a low battery warning reminder", category: "technology", text: "Explain how to set my phone to warn me when the battery falls below 20 percent. Give simple steps, tell me how to turn on battery saver automatically at that level, and explain why I should start charging soon after the warning appears." },
  { id: "technology-156", title: "Save battery at night while sleeping", category: "technology", text: "My phone loses a lot of battery overnight even though I do not use it. Give me five simple steps to save battery at night, like turning off Wi-Fi, closing apps and using aeroplane mode, and explain which step helps the most for a beginner." },
  { id: "technology-157", title: "Battery drains while using maps", category: "technology", text: "When I use maps for a long drive, my phone battery drains very fast. Explain why maps use so much battery and give simple tips to save it, like downloading the route offline, lowering brightness and charging the phone in the car." },
  { id: "technology-158", title: "Choose a replacement phone battery", category: "technology", text: "My phone battery is weak and I want to replace it. Explain how to check if my phone battery can be replaced, where to get a genuine battery in [your city], what it may cost in rupees, and what to ask the service centre before paying." },
  { id: "technology-159", title: "Stop battery draining from games", category: "technology", text: "My child plays games on my phone and the battery drains in one hour. Explain why games use so much battery and give simple ways to reduce it, like lowering brightness, closing other apps and setting a time limit. Use simple words a parent can follow." },
  { id: "technology-160", title: "Keep battery healthy for two years", category: "technology", text: "Give me a simple weekly routine to keep my new phone battery healthy for two years. Include when to charge, what to avoid like full discharge and heat, and which settings to check once a month. Use short clear steps a beginner can follow easily." },
  { id: "technology-161", title: "Phone switches off at 10 percent", category: "technology", text: "My phone switches off suddenly even when it shows 10 percent battery left. Explain in simple words why an old battery does this, what I can try at home, and when I should visit a service centre. Tell me how to back up my photos first." },
  { id: "technology-162", title: "Charge phone from a laptop safely", category: "technology", text: "Explain how to charge my phone from my laptop using a cable when there is no plug nearby. Give simple steps, tell me why it charges more slowly than a wall charger, and warn me to use a good cable and keep the laptop switched on." },
  { id: "technology-163", title: "Battery use on a festival day", category: "technology", text: "On Diwali I take hundreds of photos and my battery dies by evening. Give me a simple plan for the day: what to charge the night before, what settings to change in the morning, and what to carry so I can keep taking photos till night." },
  { id: "technology-164", title: "Turn off vibration to save battery", category: "technology", text: "Explain what vibration does on a phone and how turning it off can save battery. Give simple steps to turn off vibration for calls, messages and keyboard taps, and tell me when vibration is still useful, like when my phone is on silent in a meeting." },
  { id: "technology-165", title: "Check battery use in the last day", category: "technology", text: "Explain how to see how my phone battery was used in the last 24 hours. Give simple steps to open the battery settings, read the list of apps, and understand which app used the most power. Tell me what to do about the top app on the list." },
  { id: "technology-166", title: "Check free storage on my phone", category: "technology", text: "Explain how to check how much free storage is left on my phone in simple steps. Tell me where to find the storage settings, what the numbers mean, and how much free space I should keep so my phone keeps working smoothly every day." },
  { id: "technology-167", title: "Free storage by clearing app cache", category: "technology", text: "Explain what app cache is in very simple words and how clearing it frees storage on my phone. Give safe steps to clear the cache for one big app, tell me what will not be deleted, and warn me not to clear data by mistake." },
  { id: "technology-168", title: "Delete downloaded files I forgot", category: "technology", text: "Explain how to find and delete old downloaded files on my phone, like PDFs, videos and photos sent on WhatsApp. Give simple steps to open the downloads folder, sort files by size, and delete the large ones I no longer need safely." },
  { id: "technology-169", title: "Move photos to a memory card", category: "technology", text: "Explain how to move photos and videos from my phone to a memory card to free storage. Give simple numbered steps, tell me how to check if my phone supports a memory card, and how to make sure the photos moved correctly before deleting them from the phone." },
  { id: "technology-170", title: "Use cloud storage for my photos", category: "technology", text: "Explain what cloud storage means in simple words and how it can save space on my phone. Tell me how to turn on photo backup, how much free space I get, and how to free phone space after the photos are safely backed up online." },
  { id: "technology-171", title: "Storage full warning keeps appearing", category: "technology", text: "My phone keeps showing a storage full warning and I cannot take photos. Give me a simple step-by-step plan to free at least 2 GB today, starting with the biggest videos, then old WhatsApp media, then unused apps. Tell me what to check after each step." },
  { id: "technology-172", title: "Find the biggest apps on phone", category: "technology", text: "Explain how to find which apps take up the most storage on my phone. Give simple steps to sort apps by size, tell me how to decide which big app to keep and which to delete, and explain what happens to my data when I delete an app." },
  { id: "technology-173", title: "Delete old WhatsApp media safely", category: "technology", text: "WhatsApp photos and videos are filling my phone storage. Explain how to see how much space WhatsApp is using, delete old media from large chats, and stop WhatsApp from saving every photo automatically. Give simple steps a beginner can follow safely." },
  { id: "technology-174", title: "Save files to Google Drive", category: "technology", text: "Explain how to save an important file, like a train ticket or a school circular, to Google Drive from my phone. Give simple numbered steps, tell me how to find the file again later, and explain how to share it with a family member if needed." },
  { id: "technology-175", title: "Organise files in phone folders", category: "technology", text: "My phone files are scattered everywhere and I cannot find my bills. Explain how to organise files into simple folders like Bills, Tickets, School and Work using the Files app. Give easy steps to create a folder and move files into it." },
  { id: "technology-176", title: "Delete duplicate videos from phone", category: "technology", text: "I have the same videos saved many times on my phone from WhatsApp forwards. Explain how to find duplicate videos, check them before deleting, and delete the copies safely. Give simple steps and tell me how to stop WhatsApp from saving duplicates again." },
  { id: "technology-177", title: "Back up important files from phone", category: "technology", text: "Explain how to back up my important phone files, like ID proofs, certificates and bills, so I never lose them. Give simple steps to copy them to cloud storage and to a laptop, and tell me how to check that the backup worked." },
  { id: "technology-178", title: "Understand internal and external storage", category: "technology", text: "Explain the difference between internal storage and external storage on a phone in very simple words. Tell me where photos, apps and downloads are usually stored, and when it helps to use a memory card for extra space in an Indian home." },
  { id: "technology-179", title: "Free space before a software update", category: "technology", text: "My phone needs 3 GB free space for a software update but I only have 1 GB free. Give me a simple plan to free the space safely in fifteen minutes, starting with videos, then app cache, then old downloads. Tell me what not to delete by mistake." },
  { id: "technology-180", title: "Delete apps I never use", category: "technology", text: "Explain how to find apps on my phone that I have not used in months and delete them to free storage. Give simple steps, tell me how to check the last used date, and explain the difference between deleting an app and just removing it from the home screen." },
  { id: "technology-181", title: "Save a document as a PDF", category: "technology", text: "Explain how to save a photo of a document or a web page as a PDF file on my phone. Give simple numbered steps, tell me where the PDF is saved, and how to share it on WhatsApp or email it to my office in [your city]." },
  { id: "technology-182", title: "Find a file I downloaded yesterday", category: "technology", text: "I downloaded a train ticket yesterday but cannot find it on my phone. Explain step by step how to open the Files app, look in the Downloads folder, search by the file name, and open the ticket. Give simple steps a beginner can follow in two minutes." },
  { id: "technology-183", title: "Use a memory card correctly", category: "technology", text: "Explain how to use a memory card in my phone in simple words. Tell me how to insert it safely, format it if needed, move photos to it, and remove it without losing data. Warn me to switch the phone off before taking the card out." },
  { id: "technology-184", title: "Share a large video file", category: "technology", text: "I recorded a long family video that is too large to send on WhatsApp. Explain three simple ways to share it: as a document, through cloud storage, or with a nearby share feature. Tell me which way keeps the video quality best and is easiest for a beginner." },
  { id: "technology-185", title: "Rename a file on my phone", category: "technology", text: "Explain how to rename a file on my phone so I can find it easily later, for example changing a photo name to [Diwali 2026 family photo]. Give simple steps in the Files app or gallery, and tell me why a clear name helps when I search for it." },
  { id: "technology-186", title: "Keep phone storage tidy every month", category: "technology", text: "Give me a simple monthly routine to keep my phone storage tidy in fifteen minutes. Include deleting blurry photos, clearing WhatsApp media, removing unused apps and checking free space. Write it as a short checklist a beginner can follow on the first Sunday of every month." },
  { id: "technology-187", title: "Move files from phone to laptop", category: "technology", text: "Explain how to move photos and files from my phone to my laptop using a cable in simple steps. Tell me how to connect the phone, allow file transfer, find the photos on the laptop, and check that they copied correctly before deleting them from the phone." },
  { id: "technology-188", title: "Use the Files app for daily work", category: "technology", text: "Explain what the Files app on my phone does and how to use it for daily work. Tell me how to find recent files, search by name, sort by date, and open a PDF or photo. Give three everyday examples from an Indian office or shop." },
  { id: "technology-189", title: "Recover a file I deleted today", category: "technology", text: "I deleted an important photo this morning by mistake. Explain in simple words what to try first: check the recycle bin or trash in the gallery, restore from cloud backup, and check WhatsApp. Tell me how long deleted files usually stay recoverable." },
  { id: "technology-190", title: "Check storage before recording video", category: "technology", text: "I am going to record a long video at a wedding and worry my phone will run out of space. Explain how to check free storage first, estimate how much space one hour of video needs, and free space quickly if needed. Give a simple checklist to follow before the function starts." },
  { id: "technology-191", title: "Install a new app safely", category: "technology", text: "Explain step by step how to install a new app on my phone from the Play Store or App Store. Use simple words, tell me how to search for the app, check its ratings and size, tap install, and open it for the first time safely." },
  { id: "technology-192", title: "Update my apps every week", category: "technology", text: "Explain why I should update my apps and how to do it once a week in simple steps. Tell me how to open the app store, see which apps need updates, update them on Wi-Fi, and what to do if an app stops working after an update." },
  { id: "technology-193", title: "Use the calculator app daily", category: "technology", text: "Explain how to use the calculator app on my phone for daily shop work. Give simple examples: adding up a bill, finding a discount, splitting a bill among four friends, and checking change. Tell me where to find the calculator and how to clear a wrong entry." },
  { id: "technology-194", title: "Use the clock app for reminders", category: "technology", text: "Explain how to use the clock app on my phone to set reminders for daily tasks like taking medicine at [9:00 am] and watering plants in the evening. Give simple steps for alarms and timers, and tell me how to label each alarm clearly." },
  { id: "technology-195", title: "Use Google Maps for a new route", category: "technology", text: "Explain how to use Google Maps to find the way to a new place in [your city]. Give simple steps to type the place name, choose walking or driving, follow the voice directions, and save the place so I can find it again next time without typing." },
  { id: "technology-196", title: "Use the notes app for shopping lists", category: "technology", text: "Explain how to use the notes app on my phone to make a shopping list for the weekly market. Give simple steps to create a note, add items with tick boxes, tick them off while shopping, and share the list with a family member." },
  { id: "technology-197", title: "Use the calendar app for birthdays", category: "technology", text: "Explain how to use the calendar app on my phone to remember birthdays and festivals. Give simple steps to add an event with a date and a reminder one day before, and tell me how to see all the events coming up in the next month." },
  { id: "technology-198", title: "Listen to music on my phone", category: "technology", text: "Explain how to listen to my favourite film songs on my phone using a free music app. Give simple steps to search for a song, play it, make a small playlist for the evening, and listen with earphones. Tell me how to stop the music and save battery." },
  { id: "technology-199", title: "Watch YouTube videos for learning", category: "technology", text: "Explain how to use YouTube on my phone to learn something new, like a cooking recipe or a bhajan. Give simple steps to search, choose a trusted channel, watch in full screen, pause and replay, and save the video to watch later offline." },
  { id: "technology-200", title: "Use a weather app before travelling", category: "technology", text: "Explain how to use a weather app on my phone before travelling to [your city]. Give simple steps to check today temperature, rain chance and wind, and tell me how to decide what clothes to pack and whether to carry an umbrella or a raincoat." },
  { id: "technology-201", title: "Use a translator app while travelling", category: "technology", text: "Explain how to use a translator app on my phone to understand signs and talk to people in another state. Give simple steps to type or speak a sentence, choose the language, hear the translation, and save useful phrases like asking for directions and food." },
  { id: "technology-202", title: "Use the camera app for scanning", category: "technology", text: "Explain how to use my phone camera to scan a paper document and save it as a clear file. Give simple steps to open the scanner, place the paper flat, take the scan, crop the edges, and save it with a clear name like [Aadhaar copy]." },
  { id: "technology-203", title: "Set up a basic email app", category: "technology", text: "Explain how to set up the email app on my phone with my Gmail account in simple steps. Tell me how to open the app, add my account, check my inbox, read a new mail, and reply to it. Use short clear steps a beginner can follow alone." },
  { id: "technology-204", title: "Use a banking app safely at home", category: "technology", text: "Explain how to use my bank app on my phone safely at home in simple steps. Tell me how to check my balance, see recent transactions, and log out after use. Remind me never to share my PIN or OTP with anyone, even if they say they are from the bank." },
  { id: "technology-205", title: "Use a train ticket booking app", category: "technology", text: "Explain how to use a train ticket app on my phone to check trains from [Chennai] to [Madurai]. Give simple steps to enter the stations and date, see the train list, choose a seat, and save the ticket. Tell me to check the date and station name twice." },
  { id: "technology-206", title: "Use a food delivery app first time", category: "technology", text: "Explain how to order food for the first time using a food delivery app on my phone. Give simple steps to choose a restaurant, pick a Jain vegetarian dish, add it to the cart, enter my address, and pay by cash or UPI. Tell me how to track the order." },
  { id: "technology-207", title: "Use a news app for morning headlines", category: "technology", text: "Explain how to use a news app on my phone to read the morning headlines in [Tamil or English]. Give simple steps to open the app, choose my language, read the top five stories, and save one story to read later in the evening." },
  { id: "technology-208", title: "Use a fitness app to count steps", category: "technology", text: "Explain how to use a free fitness app on my phone to count my daily steps. Give simple steps to open the app, set a goal of [8,000] steps, check my progress in the evening, and understand what the number means for my health in simple words." },
  { id: "technology-209", title: "Use a dictionary app for English words", category: "technology", text: "Explain how to use a dictionary app on my phone to learn the meaning of a new English word. Give simple steps to type the word, read the meaning in simple English, hear how it sounds, and save the word in a list to revise every Sunday." },
  { id: "technology-210", title: "Use a photo editing app simply", category: "technology", text: "Explain how to use a free photo editing app on my phone to improve a family photo. Give simple steps to open the photo, make it brighter, crop out extra space, add a little colour, and save the edited photo without deleting the original one." },
  { id: "technology-211", title: "Use a voice recorder for notes", category: "technology", text: "Explain how to use the voice recorder app on my phone to record a quick note or a shop order. Give simple steps to start recording, speak clearly, stop and save it with a clear name, and play it back later. Tell me how to delete old recordings." },
  { id: "technology-212", title: "Use a QR scanner app at a shop", category: "technology", text: "Explain how to use a QR scanner on my phone to pay at a small shop. Give simple steps to open the scanner, point it at the shop QR code, check the shop name and amount carefully, enter my UPI PIN, and confirm that the payment went through." },
  { id: "technology-213", title: "Use a bus timing app in my city", category: "technology", text: "Explain how to use a bus timing app on my phone to plan a trip in [your city]. Give simple steps to enter my starting point and destination, see the bus numbers and timings, choose the fastest bus, and check if the bus is running late today." },
  { id: "technology-214", title: "Use a file sharing app offline", category: "technology", text: "Explain how to share photos and videos with a nearby phone without using the internet. Give simple steps to open the sharing feature, turn on Bluetooth and Wi-Fi, choose the files, and accept them on the other phone. Tell me to check the files arrived safely." },
  { id: "technology-215", title: "Use a reminder app for medicine", category: "technology", text: "Explain how to use a reminder app on my phone so I never forget my daily medicine. Give simple steps to add the medicine name, set the time to [8:00 am] and [8:00 pm], choose a loud sound, and tick it off each time I take it." },
  { id: "technology-216", title: "Use a video calling app with family", category: "technology", text: "Explain how to make a video call to my family using a simple video calling app on my phone. Give simple steps to open the app, choose the contact, start the video call, switch the camera to show my room, and end the call politely." },
  { id: "technology-217", title: "Use a shopping app for groceries", category: "technology", text: "Explain how to order monthly groceries using a shopping app on my phone. Give simple steps to search for rice, dal and oil, add them to the cart, check the total price, choose a delivery time, and pay by cash on delivery if I prefer." },
  { id: "technology-218", title: "Use a devotional app for daily prayers", category: "technology", text: "Explain how to use a devotional app on my phone for daily prayers and bhajans. Give simple steps to open the app, choose a morning prayer, listen with earphones, follow the words on the screen, and set a daily reminder at [6:00 am]." },
  { id: "technology-219", title: "Use a learning app for my child", category: "technology", text: "Explain how to use a free learning app on my phone to help my child practise maths tables. Give simple steps to choose the class, pick a topic, play a short quiz, check the score together, and set a daily limit of twenty minutes for the app." },
  { id: "technology-220", title: "Use a recharge app for my mobile", category: "technology", text: "Explain how to recharge my mobile number using a recharge app on my phone. Give simple steps to enter my number, choose a plan that suits my calls and data, check the price in rupees, pay by UPI, and confirm that the recharge was successful." },
  { id: "technology-221", title: "Use a taxi booking app safely", category: "technology", text: "Explain how to book a taxi using a taxi app on my phone for a trip to the railway station. Give simple steps to enter the pickup point and destination, check the fare, choose a car, share the trip with a family member, and pay after reaching safely." },
  { id: "technology-222", title: "Use a photo backup app for safety", category: "technology", text: "Explain how to use a photo backup app on my phone so my family photos are safe even if I lose the phone. Give simple steps to turn on backup on Wi-Fi only, check that photos are uploading, and open them again from another phone or laptop." },
  { id: "technology-223", title: "Use a keyboard app to type Tamil", category: "technology", text: "Explain how to install and use a Tamil keyboard on my phone so I can type messages in Tamil. Give simple steps to add the keyboard, switch between English and Tamil while typing, type a short message to a friend, and switch back to English afterwards." },
  { id: "technology-224", title: "Use a screen lock app for kids", category: "technology", text: "Explain how to use a simple screen lock or child lock feature so my child cannot open other apps on my phone. Give easy steps to turn it on before handing the phone over, pin one learning app on the screen, and unlock it again with my PIN." },
  { id: "technology-225", title: "Choose five essential apps for beginners", category: "technology", text: "I just bought my first smartphone and do not know which apps I need. Suggest five essential free apps for a beginner in India: calls, messages, maps, payments and photos. For each app, explain in one simple line what it does and why it is useful every day." },
  { id: "technology-226", title: "Choose a laptop for college work", category: "technology", text: "Help me choose a laptop for college work in [your city]. My budget is ₹[amount] and I need it for notes, online classes and light photo editing. Compare 3 options with processor, RAM, storage, battery life and weight, then recommend one and explain why it fits a student." },
  { id: "technology-227", title: "Best laptop for school children", category: "technology", text: "Suggest a good laptop for my [age]-year-old child for school homework, online classes and simple drawing apps. My budget is ₹[amount]. Compare 3 sturdy, light options and tell me which is easiest for a child to carry and use every day." },
  { id: "technology-228", title: "Laptop for work from home", category: "technology", text: "I work from home and need a laptop for video meetings, spreadsheets and emails. My budget is ₹[amount]. Recommend 3 laptops, compare their screen size, keyboard comfort, battery and webcam quality, and tell me which one suits long working days best." },
  { id: "technology-229", title: "Laptop versus desktop for home", category: "technology", text: "I cannot decide between a laptop and a desktop computer for my home in [your city]. We use it for study, office work and watching films. Compare cost, space, power use and ease of repair, then recommend the better choice for a family of [number] people." },
  { id: "technology-230", title: "Understand laptop specifications simply", category: "technology", text: "Explain laptop specifications in very simple words for a beginner: processor, RAM, storage, screen size and graphics. Use everyday comparisons a non-technical person can understand. Then tell me which of these matter most for [your main use]." },
  { id: "technology-231", title: "How much RAM do I need", category: "technology", text: "Tell me how much RAM I need on a laptop for [your main use: browsing, office work, video editing]. Explain in simple words what RAM does, how 8 GB differs from 16 GB, and whether paying extra for more RAM is worth it for my use." },
  { id: "technology-232", title: "SSD or hard disk laptop", category: "technology", text: "Explain the difference between an SSD and a hard disk in a laptop in simple words. I store many photos and use [your main use]. Tell me which is faster, which lasts longer, and how much storage I should buy within ₹[amount]." },
  { id: "technology-233", title: "Laptop buying checklist before paying", category: "technology", text: "Give me a checklist of things to check before buying a laptop from a shop in [your city]. Include the bill, warranty card, charger, screen, keyboard, ports and battery. Tell me what to test in the shop and which questions to ask the seller." },
  { id: "technology-234", title: "Refurbished laptop worth buying", category: "technology", text: "Is it safe to buy a refurbished laptop for ₹[amount]? Explain what refurbished means, what to check before buying, which sellers to trust, and what warranty I should get. Give me a simple checklist and warn me about common risks." },
  { id: "technology-235", title: "Laptop for video editing beginners", category: "technology", text: "Recommend a laptop for a beginner learning video editing on a budget of ₹[amount]. I edit short videos for [YouTube / family events]. Compare 3 options for processor, RAM, screen colour and storage, and tell me which one gives the best value." },
  { id: "technology-236", title: "Lightweight laptop for daily travel", category: "technology", text: "I travel by train and bus every day and need a light laptop under [weight] kg for emails and documents. My budget is ₹[amount]. Compare 3 light laptops for weight, battery life and toughness, and recommend the best one for daily travel." },
  { id: "technology-237", title: "Laptop screen size guide", category: "technology", text: "Help me pick the right laptop screen size. I use it for [study / office work / films] at home and sometimes carry it outside. Compare 13-inch, 14-inch and 15-inch screens for comfort, weight and price, and recommend one size for my needs." },
  { id: "technology-238", title: "Laptop battery life explained", category: "technology", text: "Explain laptop battery life in simple words. What does 8 hours of battery really mean, and why does it change with video calls and brightness? Give me 8 practical tips to make my laptop battery last longer during a full day." },
  { id: "technology-239", title: "Extend old laptop life", category: "technology", text: "My laptop is [number] years old and has become slow. Tell me 10 simple ways to make it faster without buying a new one, like cleaning files, removing apps and adding RAM. Also tell me when it is finally time to replace it." },
  { id: "technology-240", title: "Laptop for small business billing", category: "technology", text: "I run a small shop in [your city] and need a laptop for billing, stock records and WhatsApp orders. My budget is ₹[amount]. Recommend 3 reliable laptops, compare their price, speed and after-sales service nearby, and pick the best value option." },
  { id: "technology-241", title: "Choose laptop for online teaching", category: "technology", text: "I teach online classes for [subject] and need a laptop with a good camera, microphone and screen. My budget is ₹[amount]. Compare 3 laptops on webcam quality, sound, battery and price, and recommend the best one for teaching [number] hours a day." },
  { id: "technology-242", title: "Laptop warranty and AMC explained", category: "technology", text: "Explain laptop warranty and annual maintenance contracts in simple words. What is covered, what is not, and is extended warranty worth ₹[amount]? Tell me what to check on the warranty card before I leave the shop." },
  { id: "technology-243", title: "Buy laptop online or in shop", category: "technology", text: "Should I buy my laptop online or from a shop in [your city]? Compare price, offers, warranty, delivery and after-sales help for both options. Tell me which is safer for a first-time buyer with a budget of ₹[amount]." },
  { id: "technology-244", title: "Laptop accessories worth buying", category: "technology", text: "List the useful accessories I should buy with a new laptop: bag, mouse, keyboard, cooling pad, screen guard and more. Tell me which ones are truly needed, which are optional, and a fair price in rupees for each one." },
  { id: "technology-245", title: "Set up a new laptop step by step", category: "technology", text: "Give me a simple step-by-step guide to set up a brand-new laptop for the first time. Include creating a user account, connecting to Wi-Fi, updating the system, installing basic apps and removing unwanted trial software. Use very simple language." },
  { id: "technology-246", title: "Laptop keyboard and touchpad tips", category: "technology", text: "Teach me the useful keyboard shortcuts and touchpad gestures for a laptop. I use it for [office work / study]. List 15 shortcuts for copying, saving, switching windows and searching, and explain each one in one simple line." },
  { id: "technology-247", title: "Keep laptop safe from heat", category: "technology", text: "My laptop gets very hot in Indian summer. Explain why laptops heat up, what damage heat can cause, and give me 10 simple tips to keep it cool at home, like using a hard surface, cleaning vents and avoiding direct sunlight." },
  { id: "technology-248", title: "Laptop for elderly parents", category: "technology", text: "Suggest a simple laptop for my [age]-year-old parent who wants to watch videos, video call family and read the news. My budget is ₹[amount]. Compare 3 easy-to-use options with big text, simple menus and good speakers, and recommend one." },
  { id: "technology-249", title: "Compare two laptop models", category: "technology", text: "Compare these two laptops for me: [model A] and [model B]. I will use it mainly for [your main use]. Compare processor, RAM, storage, screen, battery, weight and price in a simple table, then tell me which one I should buy and why." },
  { id: "technology-250", title: "Laptop EMI and offers explained", category: "technology", text: "Explain laptop EMI, no-cost EMI and exchange offers in simple words. My budget is ₹[amount] for a laptop costing ₹[amount]. Tell me how EMI works, what hidden charges to watch for, and whether an exchange offer is worth it." },
  { id: "technology-251", title: "Second laptop for children study", category: "technology", text: "We already have one laptop at home and need a second one for my child's online classes and homework. My budget is ₹[amount]. Recommend 3 affordable options, compare their durability, battery and parental controls, and tell me which is best for a student." },
  { id: "technology-252", title: "Laptop for coding beginners", category: "technology", text: "I am starting to learn coding and need a laptop under ₹[amount]. Recommend 3 laptops good for learning [Python / web development]. Compare processor, RAM, storage and keyboard comfort, and tell me the minimum specifications I should not go below." },
  { id: "technology-253", title: "Clean laptop screen and keyboard", category: "technology", text: "Teach me how to clean my laptop screen, keyboard and vents safely at home. List what I need, what to avoid, and how often to clean each part. Warn me about liquids and sprays that can damage the laptop." },
  { id: "technology-254", title: "Laptop bag and carry tips", category: "technology", text: "Help me choose a good laptop bag for daily use in [your city]. I carry a [size]-inch laptop, charger and notebooks. Compare 3 bag types for padding, comfort, water protection and price under ₹[amount], and tell me what to check before buying." },
  { id: "technology-255", title: "When to repair or replace laptop", category: "technology", text: "My laptop has [describe the problem]. Help me decide whether to repair it or buy a new one. Compare repair cost, remaining life, speed and warranty, and give me a simple rule to decide. My budget for a new one is ₹[amount]." },
  { id: "technology-256", title: "Wi-Fi at home explained simply", category: "technology", text: "Explain home Wi-Fi in very simple words: what a router is, what a modem is, and how the internet reaches my phone and laptop. Then tell me what speed I need for [number] people doing video calls, study and watching films at home." },
  { id: "technology-257", title: "Choose a broadband plan", category: "technology", text: "Help me choose a broadband plan for my home in [your city]. We are [number] people who watch videos, attend online classes and work from home. Compare 3 plans for speed, monthly price, data limit and service quality, and recommend one." },
  { id: "technology-258", title: "Fix slow Wi-Fi at home", category: "technology", text: "My home Wi-Fi is very slow in the evening. Give me 12 simple steps to find the problem and fix it, like restarting the router, moving it to a better spot and checking how many devices are connected. Explain each step in simple words." },
  { id: "technology-259", title: "Wi-Fi router placement tips", category: "technology", text: "Tell me the best place to keep my Wi-Fi router in a [number]-room house so every room gets a good signal. Explain in simple words why walls, mirrors and kitchens weaken the signal, and list 8 placement mistakes to avoid." },
  { id: "technology-260", title: "Change Wi-Fi password safely", category: "technology", text: "Give me simple steps to change my home Wi-Fi password and name. Explain how to open the router settings, what makes a strong password, and how to reconnect all my phones and laptops afterwards. Use very simple language for a beginner." },
  { id: "technology-261", title: "Wi-Fi not connecting to laptop", category: "technology", text: "My laptop will not connect to Wi-Fi, but my phone connects fine. Give me a step-by-step checklist to fix it, starting with the simplest steps. Explain what to check in settings and when to restart the router or the laptop." },
  { id: "technology-262", title: "Share Wi-Fi password with guests", category: "technology", text: "Guests are visiting my home and need Wi-Fi. Explain the safest way to share my Wi-Fi password without sharing my main password, like using a guest network or a QR code. Tell me how to set it up and turn it off after they leave." },
  { id: "technology-263", title: "Mobile hotspot for laptop use", category: "technology", text: "Explain how to use my phone as a mobile hotspot for my laptop when there is no Wi-Fi. Give me simple steps to switch it on, connect the laptop, and check how much mobile data it uses. Also warn me about battery drain and data limits." },
  { id: "technology-264", title: "Wi-Fi speed test explained", category: "technology", text: "Teach me how to test my internet speed at home and understand the result. Explain download speed, upload speed and ping in simple words, what numbers are good for video calls and films, and what to do if the speed is much lower than my plan." },
  { id: "technology-265", title: "Wi-Fi extender or mesh system", category: "technology", text: "My Wi-Fi signal is weak in the far bedroom. Explain the difference between a Wi-Fi extender and a mesh system in simple words. Compare cost, setup and coverage, and recommend the better option for a [number]-room house in [your city]." },
  { id: "technology-266", title: "Public Wi-Fi safety tips", category: "technology", text: "I often use free Wi-Fi at railway stations, cafes and malls. Give me 10 simple safety rules for public Wi-Fi, like what not to do on it, when to avoid banking, and how to check if a network is genuine before connecting." },
  { id: "technology-267", title: "Wi-Fi keeps disconnecting fix", category: "technology", text: "My Wi-Fi keeps disconnecting every few minutes on my [phone / laptop]. Give me a simple checklist of causes and fixes, from moving closer to the router to updating settings. Tell me when the problem is the router and when it is the device." },
  { id: "technology-268", title: "Limit Wi-Fi data usage at home", category: "technology", text: "Our family finishes the monthly internet data too fast. Help me find which apps and devices use the most data, and give me 10 practical tips to save data, like lowering video quality and turning off auto-updates on phones and laptops." },
  { id: "technology-269", title: "Connect smart TV to Wi-Fi", category: "technology", text: "Give me simple steps to connect my smart TV to home Wi-Fi so I can watch videos and films. Explain what to do if the TV cannot find the network, the password is rejected, or videos keep stopping. Use very simple language." },
  { id: "technology-270", title: "Wi-Fi for small shop or office", category: "technology", text: "I run a small [shop / office] in [your city] and need Wi-Fi for [number] staff and customers. Recommend a suitable plan and router, explain how to set up a separate network for customers, and tell me the monthly cost to expect." },
  { id: "technology-271", title: "Restart router the right way", category: "technology", text: "Explain the right way to restart a Wi-Fi router when the internet stops working. Tell me how long to wait, what the lights mean, and what to check after restarting. Also explain when restarting will not help and I should call my internet provider." },
  { id: "technology-272", title: "Wi-Fi password forgotten recovery", category: "technology", text: "I have forgotten my home Wi-Fi password. Give me simple steps to find it on my connected laptop or phone, and explain how to reset the router if nothing works. Tell me what I will need to set up again after a reset." },
  { id: "technology-273", title: "Improve Wi-Fi for video calls", category: "technology", text: "My video calls freeze and the voice breaks. Give me 10 simple ways to improve Wi-Fi for video calls, like sitting near the router, closing other apps and asking family to pause downloads. Explain each tip in one simple line." },
  { id: "technology-274", title: "Two Wi-Fi bands explained", category: "technology", text: "My router shows two networks, 2.4 GHz and 5 GHz. Explain in simple words what these two bands mean, which one is better for video calls, which reaches far rooms, and which one my [phone / laptop / TV] should connect to." },
  { id: "technology-275", title: "Wi-Fi bill and plan comparison", category: "technology", text: "Compare Wi-Fi broadband plans from [provider A] and [provider B] in [your city]. I need [speed] speed for [number] people. Compare monthly price, installation charges, data limits and customer service, then recommend the better plan for my home." },
  { id: "technology-276", title: "Secure home Wi-Fi network", category: "technology", text: "Help me make my home Wi-Fi secure from strangers. Give me a simple checklist: change the default password, update the router, hide the network name if useful, and check connected devices. Explain each step in simple words for a beginner." },
  { id: "technology-277", title: "Check who uses my Wi-Fi", category: "technology", text: "I think someone unknown is using my Wi-Fi. Teach me how to see the list of connected devices on my router or phone app, how to spot a strange device, and how to block it and change my password afterwards." },
  { id: "technology-278", title: "Wi-Fi during power cuts", category: "technology", text: "Power cuts stop my Wi-Fi in [your city]. Explain simple backup options like a small UPS for the router, using mobile data, or a power bank. Compare their cost and how long each keeps the internet running during a cut." },
  { id: "technology-279", title: "Set Wi-Fi timings for children", category: "technology", text: "I want the Wi-Fi to switch off automatically at night so my children sleep on time. Explain how to set Wi-Fi timings or parental controls on a router, and give me simple steps for [router brand]. Keep the language very simple." },
  { id: "technology-280", title: "Wi-Fi for online classes setup", category: "technology", text: "Set up the best Wi-Fi arrangement for my child's online classes at home. Tell me the speed needed, where to place the router, how to avoid breaks during class, and what backup to keep ready if the connection fails suddenly." },
  { id: "technology-281", title: "What is a browser explained", category: "technology", text: "Explain in very simple words what a web browser is and what it does. Then compare the main browsers for a beginner: which is easiest to use, which is fastest, and which is best for an old laptop. Recommend one for my [phone / laptop]." },
  { id: "technology-282", title: "Open and use browser tabs", category: "technology", text: "Teach me how to use browser tabs: opening a new tab, switching between tabs, closing a tab, and reopening a tab I closed by mistake. Give me simple steps and useful keyboard shortcuts, explained in very simple language for a beginner." },
  { id: "technology-283", title: "Bookmark favourite websites easily", category: "technology", text: "Teach me how to save my favourite websites as bookmarks so I can open them quickly. Explain how to add a bookmark, organise bookmarks into folders, and find a bookmark later. Give simple steps for a [phone / laptop] browser." },
  { id: "technology-284", title: "Clear browser history and cache", category: "technology", text: "Explain what browser history, cookies and cache are in simple words, and why clearing them sometimes helps. Give me simple steps to clear them on my [phone / laptop], and tell me what I will lose, like saved logins, when I do it." },
  { id: "technology-285", title: "Browser keeps crashing fix", category: "technology", text: "My browser keeps closing suddenly on my [phone / laptop]. Give me a simple checklist to fix it: close extra tabs, clear cache, update the browser, check extensions and restart the device. Explain each step in simple words." },
  { id: "technology-286", title: "Search the internet effectively", category: "technology", text: "Teach me how to search the internet properly. Give me 10 simple tips, like using exact words, adding the city name, using quotes for exact phrases, and checking the date of a page. Show one example search for [topic] with a better and a worse query." },
  { id: "technology-287", title: "Download files from browser safely", category: "technology", text: "Teach me how to download files from the internet safely on my [phone / laptop]. Explain where downloads go, how to check a file before opening it, and the warning signs of a harmful download. Use very simple language." },
  { id: "technology-288", title: "Browser extensions explained simply", category: "technology", text: "Explain what browser extensions are in simple words, what they can do, and which ones are useful for a beginner, like an ad blocker or a translator. Warn me about risky extensions and how to remove one I do not want." },
  { id: "technology-289", title: "Private browsing mode explained", category: "technology", text: "Explain private browsing mode in simple words: what it hides, what it does not hide, and when to use it. Tell me how to open a private window on my [phone / laptop] and whether my internet provider or office can still see my activity." },
  { id: "technology-290", title: "Save passwords in browser safely", category: "technology", text: "Explain how saving passwords in a browser works, and whether it is safe. Give me simple steps to save a password, view a saved password, and remove one. Also tell me when I should not let the browser save a password." },
  { id: "technology-291", title: "Browser homepage and new tab setup", category: "technology", text: "Teach me how to set my favourite website as the browser homepage and change what shows on a new tab. Give me simple steps for my [phone / laptop] browser and tell me how to undo the change if I do not like it." },
  { id: "technology-292", title: "Translate a webpage to English", category: "technology", text: "I often open pages in [Hindi / Tamil / another language] that I cannot read. Teach me how to translate a whole webpage into English or [your language] on my [phone / laptop] browser, step by step, with simple instructions." },
  { id: "technology-293", title: "Zoom text on webpages easily", category: "technology", text: "The text on websites is too small for me to read. Teach me how to make text bigger in the browser on my [phone / laptop], both for one page and for all pages. Also explain how to zoom in and out quickly with keyboard shortcuts." },
  { id: "technology-294", title: "Find text on a long webpage", category: "technology", text: "Teach me how to find a particular word on a long webpage quickly, instead of reading the whole page. Give me the keyboard shortcut, explain how to jump between matches, and show an example using a page about [topic]." },
  { id: "technology-295", title: "Print a webpage without waste", category: "technology", text: "Teach me how to print only the useful part of a webpage without printing adverts and menus. Explain how to use print preview, choose pages, save as PDF instead of printing, and reduce ink use. Give simple steps for my [phone / laptop]." },
  { id: "technology-296", title: "Browser shows pop-up warnings", category: "technology", text: "My browser keeps showing pop-up warnings and strange messages. Explain what pop-ups are, which ones are dangerous, and how to block them. Give me simple steps to stop pop-ups on my [phone / laptop] browser." },
  { id: "technology-297", title: "Update browser to latest version", category: "technology", text: "Explain why updating my browser matters and give me simple steps to check my browser version and update it on my [phone / laptop]. Tell me what to do if the update fails or my old device cannot run the newest version." },
  { id: "technology-298", title: "Two browsers on one device", category: "technology", text: "Explain whether I can use two different browsers on the same [phone / laptop], and why someone might want to, like keeping work and personal browsing separate. Give me simple steps to install a second browser and set a default one." },
  { id: "technology-299", title: "Recover closed browser tabs", category: "technology", text: "I closed my browser by mistake and lost all my open tabs. Teach me how to restore the last session and reopen closed tabs on my [phone / laptop] browser. Also explain how to set the browser to restore tabs automatically next time." },
  { id: "technology-300", title: "Browser autofill for forms", category: "technology", text: "Explain browser autofill in simple words: how it fills my name, address and phone number in online forms. Teach me how to turn it on, edit the saved details, and delete them. Warn me when autofill is not safe to use." },
  { id: "technology-301", title: "Open links without losing page", category: "technology", text: "Teach me how to open a link in a new tab so I do not lose the page I am reading. Explain right-click, long-press on a phone, and keyboard shortcuts. Also explain how to go back to the previous page quickly if I open the wrong link." },
  { id: "technology-302", title: "Browser running slow fix", category: "technology", text: "My browser has become very slow on my [phone / laptop]. Give me 10 simple fixes, like closing unused tabs, clearing cache, removing extensions and restarting. Explain each fix in one line and tell me which one to try first." },
  { id: "technology-303", title: "Download videos for offline viewing", category: "technology", text: "Explain the safe and legal ways to save videos for offline viewing on my [phone / laptop], like using the download button inside video apps. Warn me about unsafe download sites and explain why they can harm my device." },
  { id: "technology-304", title: "Browser notifications control", category: "technology", text: "Websites keep asking me to allow notifications and now my [phone / laptop] shows too many. Teach me how to stop website notifications, block new requests, and allow notifications only from [website name]. Use simple steps." },
  { id: "technology-305", title: "Check if website is safe", category: "technology", text: "Teach me how to check whether a website is safe before I enter my details. Explain the padlock symbol, how to spot a fake website address, and 5 warning signs of a scam site. Give me an example with a shopping site." },
  { id: "technology-306", title: "Create a Gmail account", category: "technology", text: "Give me simple step-by-step instructions to create a new email account for [purpose]. Explain how to choose a good email address, make a strong password, add a recovery phone number, and what to do after the account is ready." },
  { id: "technology-307", title: "Write a formal email", category: "technology", text: "Teach me how to write a formal email to [person / office] about [topic]. Show me the subject line, greeting, body and closing, and give me a ready-to-use draft in polite, simple English. Keep it short and clear, under [number] lines." },
  { id: "technology-308", title: "Email to school teacher draft", category: "technology", text: "Draft a polite email to my child's teacher about [topic: leave, homework, meeting]. Keep it short, respectful and clear. Include a good subject line and a proper closing. Use simple English that a parent can copy and send." },
  { id: "technology-309", title: "Attach files to an email", category: "technology", text: "Teach me how to attach a photo, a PDF or a document to an email on my [phone / laptop]. Explain the size limits, what to do if the file is too big, and how to check that the attachment was added before I press send." },
  { id: "technology-310", title: "Find old emails quickly", category: "technology", text: "I cannot find an old email about [topic] from [person]. Teach me how to search my inbox properly using the sender's name, words from the email, or the date. Give me 5 search examples I can try right away." },
  { id: "technology-311", title: "Organise inbox with folders", category: "technology", text: "My inbox is full of unread emails. Teach me how to organise emails into folders or labels for [work / school / bills / family]. Explain how to move emails, create a folder, and find things later without searching the whole inbox." },
  { id: "technology-312", title: "Delete and archive emails", category: "technology", text: "Explain the difference between deleting and archiving an email in simple words. Tell me when to use each one, how to recover a deleted email, and how to clean up [number] old emails quickly without losing anything important." },
  { id: "technology-313", title: "Email signature setup guide", category: "technology", text: "Teach me how to add an email signature with my name, phone number and [business name] at the end of every email. Give me simple steps for my [phone / laptop], and show me a clean example signature for a small business owner." },
  { id: "technology-314", title: "Reply all versus reply", category: "technology", text: "Explain the difference between Reply and Reply All in an email in simple words, with an example. Tell me when Reply All causes problems, like sending a private message to everyone, and how to avoid that mistake at work." },
  { id: "technology-315", title: "Spot a fake phishing email", category: "technology", text: "Teach me how to spot a fake email pretending to be from a bank or a delivery company. List 8 warning signs, like strange sender addresses, urgent threats and odd links. Explain what to do if I already clicked a link by mistake." },
  { id: "technology-316", title: "Email for job application", category: "technology", text: "Draft a professional email to apply for a [job title] job at [company name]. Include a clear subject line, a short introduction, my experience in [field], and a polite closing. Attach my CV and keep the email under [number] lines." },
  { id: "technology-317", title: "Set up email on new phone", category: "technology", text: "Give me simple steps to set up my email account on a new phone. Explain how to add the account, enter the password, choose how often emails arrive, and what to do if the phone says the password is wrong." },
  { id: "technology-318", title: "Unsubscribe from unwanted emails", category: "technology", text: "I get too many promotional emails every day. Teach me how to unsubscribe safely, block a sender, and report spam. Explain the difference between unsubscribe and spam, and when to use each one on my [phone / laptop]." },
  { id: "technology-319", title: "Send email to many people", category: "technology", text: "I need to send the same email to [number] people about [event / notice]. Explain how to add many addresses, use CC and BCC correctly, and protect everyone's privacy with BCC. Give me a simple checklist before pressing send." },
  { id: "technology-320", title: "Email out of office reply", category: "technology", text: "I am going on leave for [number] days. Help me write a short out-of-office email reply saying I am away until [date], when I will reply, and who to contact for urgent work. Give me simple steps to switch it on and off." },
  { id: "technology-321", title: "Recover a hacked email account", category: "technology", text: "I think someone else has opened my email account. Give me urgent steps to take right now: change the password, check recovery details, sign out other devices, and warn my contacts. Explain each step in simple words and what to do next." },
  { id: "technology-322", title: "Email etiquette for beginners", category: "technology", text: "Teach me good email manners for work and official messages: clear subject lines, polite greetings, short paragraphs, and how to end an email. List 10 simple rules with one example for each, so I never send a rude or confusing email." },
  { id: "technology-323", title: "Schedule an email to send later", category: "technology", text: "Teach me how to write an email now and schedule it to send later at [time] on [date]. Explain where to find the schedule option on my [phone / laptop], how to change or cancel a scheduled email, and when scheduling is useful." },
  { id: "technology-324", title: "Email storage full solution", category: "technology", text: "My email says storage is full and I cannot receive new emails. Explain why this happens and give me simple steps to free space: delete old emails with big attachments, empty the bin, and save important files elsewhere. Tell me how to check what uses the most space." },
  { id: "technology-325", title: "Forward email with attachment", category: "technology", text: "Teach me how to forward an email, including its attachments, to another person. Explain how to add a short note at the top, check that the attachment is included, and remove private details from the original email before forwarding it." },
  { id: "technology-326", title: "Create email folders for bills", category: "technology", text: "Help me organise my bill and payment emails into folders so I can find them at tax time. Suggest folder names for electricity, phone, school fees and rent, and give me simple steps to move emails into folders automatically on my [phone / laptop]." },
  { id: "technology-327", title: "Email draft for leave request", category: "technology", text: "Draft a polite leave request email to my manager for [number] days of leave from [start date] to [end date] because of [reason]. Include a clear subject line, who will handle my work, and a respectful closing in simple English." },
  { id: "technology-328", title: "Check email on shared computer", category: "technology", text: "I need to check my email on a shared computer at [place]. Give me safety steps: use a private window, never save the password, and sign out properly afterwards. Explain how to check that I am fully signed out before leaving." },
  { id: "technology-329", title: "Email address for small business", category: "technology", text: "I run a small business called [business name] in [your city]. Help me choose a professional email address for it, explain the difference between a free address and a business address, and list what I need to set one up." },
  { id: "technology-330", title: "Reply to customer email politely", category: "technology", text: "Draft a polite reply to a customer who wrote about [complaint / question] regarding my [shop / service]. Thank them, answer their question clearly, offer a solution, and close warmly. Keep the tone friendly and professional in simple English." },
  { id: "technology-331", title: "Organise computer files and folders", category: "technology", text: "Teach me how to organise files on my laptop into clear folders for [work / study / photos / bills]. Suggest folder names, explain how to move files, rename them clearly, and find a file quickly later without searching everywhere." },
  { id: "technology-332", title: "Rename many files quickly", category: "technology", text: "I have [number] photos and documents with confusing names like IMG_001. Teach me simple ways to rename them clearly in batches on my [phone / laptop], and suggest a naming system with dates so I can find any file in seconds." },
  { id: "technology-333", title: "Find lost files on laptop", category: "technology", text: "I saved a file yesterday but cannot find it now. Give me a simple step-by-step method to search for it by name, type or date on my laptop. Explain where downloads and documents usually go and how to check the recycle bin." },
  { id: "technology-334", title: "PDF files explained for beginners", category: "technology", text: "Explain what a PDF file is in very simple words, why offices and schools use PDFs, and how to open one on my [phone / laptop]. Also explain how to save a document or a webpage as a PDF for sharing." },
  { id: "technology-335", title: "Compress large files for sharing", category: "technology", text: "My file is too big to send by email or WhatsApp. Explain in simple words what file compression is, and teach me how to make a photo, video or document smaller on my [phone / laptop] without losing too much quality." },
  { id: "technology-336", title: "Create folders on phone storage", category: "technology", text: "Teach me how to create folders on my phone to organise photos, documents and downloads. Give me simple steps, suggest useful folder names for a family, and explain how to move files into folders and find them again later." },
  { id: "technology-337", title: "Transfer files phone to laptop", category: "technology", text: "Teach me 4 simple ways to move photos and documents from my phone to my laptop: cable, email, cloud storage and a messaging app. Compare speed and ease for each method, and recommend the best one for [number] photos." },
  { id: "technology-338", title: "Delete duplicate photos and files", category: "technology", text: "My phone storage is full of duplicate photos. Teach me how to find and delete duplicate photos and files safely on my [phone / laptop], and how to check a file before deleting it so I never lose the only copy of something important." },
  { id: "technology-339", title: "Open files without right app", category: "technology", text: "I received a file I cannot open on my [phone / laptop]. Explain why this happens, how to find which app opens it, and how to convert it to a common format like PDF. Give me simple steps and free options that work offline too." },
  { id: "technology-340", title: "Save files to pen drive", category: "technology", text: "Teach me how to copy important files from my laptop to a pen drive safely. Explain how to plug it in, copy files, check they copied correctly, and remove the drive safely without losing data. Use very simple steps for a beginner." },
  { id: "technology-341", title: "File types explained simply", category: "technology", text: "Explain common file types in simple words: JPG and PNG for photos, PDF for documents, MP3 for audio and MP4 for video. Tell me which type to use when sharing photos, sending a CV, or saving a school project." },
  { id: "technology-342", title: "Scan documents with phone camera", category: "technology", text: "Teach me how to scan a paper document, like an Aadhaar card copy or a school form, using my phone camera. Explain how to get a clear scan, save it as a PDF, and share it by email or WhatsApp. Keep the steps very simple." },
  { id: "technology-343", title: "Free space on laptop storage", category: "technology", text: "My laptop says the storage is almost full. Give me 10 simple ways to free space safely: delete old downloads, empty the recycle bin, remove unused apps and move photos elsewhere. Explain each step and what never to delete." },
  { id: "technology-344", title: "Share large files with family", category: "technology", text: "I need to share a [number] GB video of a family function with relatives in [city]. Explain the easiest ways to share large files: cloud links, pen drives and messaging apps. Compare each method and recommend the simplest one for elderly relatives." },
  { id: "technology-345", title: "Recover deleted files simply", category: "technology", text: "I deleted an important file by mistake on my [phone / laptop]. Give me simple steps to recover it from the recycle bin or trash, explain how long deleted files stay there, and what to do if it is already gone for good." },
  { id: "technology-346", title: "Zip and unzip files explained", category: "technology", text: "Explain what a ZIP file is in simple words and why people use it to send many files together. Teach me how to create a ZIP file and how to open one I receive, on my [phone / laptop], with simple steps a beginner can follow." },
  { id: "technology-347", title: "Keep important documents safe digitally", category: "technology", text: "Help me keep digital copies of important documents like Aadhaar, PAN, certificates and bills safe. Tell me where to store them, how to name them clearly, and how to back them up so I never lose them if my phone is lost." },
  { id: "technology-348", title: "Sort photos by date and event", category: "technology", text: "I have thousands of photos mixed together on my phone. Teach me how to sort them by date and event, create albums for [Diwali / wedding / school function], and find any photo quickly later. Give me a simple weekly routine to keep them organised." },
  { id: "technology-349", title: "Edit a PDF form on laptop", category: "technology", text: "I need to fill in a PDF form for [purpose] on my laptop. Teach me simple ways to type into a PDF, tick boxes, add my signature, and save the filled form. Recommend free options that a beginner can use without installing anything complicated." },
  { id: "technology-350", title: "Convert Word file to PDF", category: "technology", text: "Teach me how to convert a Word document into a PDF on my [phone / laptop]. Explain why PDF is better for sharing, give me simple steps for the free built-in option, and tell me how to check the PDF looks right before sending it." },
  { id: "technology-351", title: "Create a simple spreadsheet", category: "technology", text: "Teach me how to make a simple spreadsheet to track my monthly household expenses. Explain rows, columns and simple totals in very simple words, and give me a ready column plan for rent, food, school fees, transport and savings." },
  { id: "technology-352", title: "Make a presentation for school", category: "technology", text: "Help me plan a simple 8-slide presentation for my child's school project on [topic]. Suggest what goes on each slide, how much text to use, where to add pictures, and give me tips to make it neat and easy for a child to present." },
  { id: "technology-353", title: "Type in Hindi or Tamil on laptop", category: "technology", text: "Teach me how to type in [Hindi / Tamil] on my laptop. Explain how to add the language keyboard, switch between English and [Hindi / Tamil], and type common words. Give me simple steps and a short practice list of everyday sentences." },
  { id: "technology-354", title: "Save webpages for offline reading", category: "technology", text: "Teach me how to save a webpage or an article to read later without internet on my [phone / laptop]. Explain bookmarks, reading lists and saving as PDF, and tell me which method works best when I travel by train." },
  { id: "technology-355", title: "File backup basics for home", category: "technology", text: "Explain file backup in simple words: why I need a copy of my photos and documents, and what happens if my phone is lost. Compare pen drives, external hard disks and cloud storage, and help me pick a simple backup plan for my family." },
  { id: "technology-356", title: "Set up printer at home", category: "technology", text: "Give me simple steps to set up a new printer at home and connect it to my [phone / laptop] using Wi-Fi or a cable. Explain how to install ink, load paper, print a test page, and what to do if the printer is not found." },
  { id: "technology-357", title: "Print documents from phone", category: "technology", text: "Teach me how to print a document or photo directly from my phone without using a laptop. Explain how to connect the phone to the printer, choose the paper size, and fix it if the printer does not appear in the list." },
  { id: "technology-358", title: "Printer not printing fix", category: "technology", text: "My printer is switched on but nothing prints. Give me a simple checklist to fix it: check paper, ink, cables, Wi-Fi and the print queue. Explain each step in simple words and tell me when to restart the printer or the laptop." },
  { id: "technology-359", title: "Save ink when printing", category: "technology", text: "Printing is using too much ink at home. Give me 10 practical tips to save ink, like printing in black and white, using draft mode, printing two pages on one sheet, and checking the preview before printing. Explain each tip simply." },
  { id: "technology-360", title: "Choose a printer for home use", category: "technology", text: "Help me choose a printer for home use in [your city]. I print school homework, office documents and occasional photos, about [number] pages a month. Compare inkjet and laser printers for cost, ink and quality, and recommend one within ₹[amount]." },
  { id: "technology-361", title: "Print photos at home well", category: "technology", text: "Teach me how to print good-quality photos at home for a family album. Explain which paper to use, how to choose the photo size, and the printer settings for bright colours. Give me simple steps from phone photo to finished print." },
  { id: "technology-362", title: "Scan and print old documents", category: "technology", text: "I have old paper documents I want to scan and print copies of. Teach me how to use the printer's scanner, save the scan as a PDF on my [phone / laptop], and print a clean copy. Keep the steps very simple for a beginner." },
  { id: "technology-363", title: "Printer paper jam fix", category: "technology", text: "Paper is stuck inside my printer. Give me safe, simple steps to remove the jammed paper without tearing it or damaging the printer. Tell me what never to do, and how to prevent paper jams in future." },
  { id: "technology-364", title: "Print both sides of paper", category: "technology", text: "Teach me how to print on both sides of the paper to save paper at home and in the office. Explain automatic and manual double-sided printing, how to flip the pages correctly, and what to do if the printer does not support it." },
  { id: "technology-365", title: "Replace printer ink cartridges", category: "technology", text: "Teach me how to replace the ink cartridge in my [printer model] safely. Explain how to open the printer, remove the old cartridge, fit the new one, and run a test print. Warn me about ink stains and what to do with the old cartridge." },
  { id: "technology-366", title: "Print school admission forms", category: "technology", text: "I need to print my child's school admission form from a website. Give me simple steps to download the form, check it is the right one, fill it in, and print it clearly. Also tell me how to save a copy on my phone." },
  { id: "technology-367", title: "Printer Wi-Fi connection problems", category: "technology", text: "My printer keeps losing its Wi-Fi connection. Give me a simple checklist to fix it: move the printer closer to the router, restart both devices, check the password and update the printer software. Explain each step in simple words." },
  { id: "technology-368", title: "Print tickets and boarding passes", category: "technology", text: "I need to print train tickets and a flight boarding pass for a trip from [city A] to [city B]. Teach me how to download them from email or the booking site, check the details, and print them clearly. Tell me what to carry as a backup." },
  { id: "technology-369", title: "Colour or black white printing", category: "technology", text: "Explain when to print in colour and when black and white is enough, for school work, office documents and photos. Compare the cost per page, and give me a simple rule to decide before every print job at home." },
  { id: "technology-370", title: "Keep printer working in monsoon", category: "technology", text: "During the monsoon my printer and paper get damp in [your city]. Give me simple tips to protect the printer from moisture, store paper properly, and keep prints clean. Explain what to do if the printer stops working after damp weather." },
  { id: "technology-371", title: "Video call setup for beginners", category: "technology", text: "Teach me how to make my first video call to family in [city] on my [phone / laptop]. Explain how to open the app, find the contact, start the call, switch the camera, and end the call. Use very simple steps for a complete beginner." },
  { id: "technology-372", title: "Video call for online interview", category: "technology", text: "I have an online job interview by video call tomorrow for a [job title] role. Give me a checklist: lighting, background, camera angle, sound, internet and dress. Also give me 5 tips to look confident and speak clearly on camera." },
  { id: "technology-373", title: "Fix video call sound problems", category: "technology", text: "During video calls people cannot hear me, or I cannot hear them. Give me a simple checklist to fix sound problems on my [phone / laptop]: check the microphone, speaker, volume, permissions and headphones. Explain each step in simple words." },
  { id: "technology-374", title: "Video call with many people", category: "technology", text: "I need to host a video call with [number] family members in different cities for [occasion]. Teach me how to start a group call, add people, mute and unmute, share my screen, and end the call politely. Give me simple steps." },
  { id: "technology-375", title: "Look good on video calls", category: "technology", text: "Give me 10 simple tips to look good on video calls for work and family: lighting, camera height, background, clothes and colours. Explain each tip in one line and tell me the cheapest way to improve lighting at home." },
  { id: "technology-376", title: "Video call etiquette for work", category: "technology", text: "Teach me good manners for work video calls: joining on time, muting when not speaking, looking at the camera, and dressing properly. List 10 simple rules with a short example for each, so I never embarrass myself in a team meeting." },
  { id: "technology-377", title: "Share screen on video call", category: "technology", text: "Teach me how to share my screen during a video call to show a document or photos to family or colleagues. Give me simple steps for my [phone / laptop], explain how to stop sharing, and warn me to close private windows first." },
  { id: "technology-378", title: "Video call freezes and lags", category: "technology", text: "My video calls freeze and the picture breaks. Give me 10 simple fixes: move closer to Wi-Fi, close other apps, turn off video briefly, and lower the video quality. Explain each fix in one line and tell me which to try first." },
  { id: "technology-379", title: "Record a video call easily", category: "technology", text: "I want to record an online class and a family video call to watch later. Explain how to record a video call on my [phone / laptop], where the recording is saved, and why I should always ask everyone for permission before recording." },
  { id: "technology-380", title: "Video call for doctor consultation", category: "technology", text: "I have an online doctor consultation tomorrow. Give me a checklist to prepare: good light, quiet room, list of medicines, recent reports, and questions to ask. Explain how to join the call and show a report on camera clearly." },
  { id: "technology-381", title: "Video call background blur tips", category: "technology", text: "My room looks messy behind me on video calls. Teach me how to blur my background or use a simple virtual background on my [phone / laptop]. Explain the steps, what works best, and how to turn it off after the call." },
  { id: "technology-382", title: "Video call for school parents meeting", category: "technology", text: "I have a video call with my child's teacher about progress in [subject]. Help me prepare: questions to ask, points about homework and behaviour, and how to join the call on time. Give me a short checklist to keep beside me." },
  { id: "technology-383", title: "Use headphones for video calls", category: "technology", text: "Explain why headphones help on video calls and how to choose a simple pair for work and study under ₹[amount]. Teach me how to connect wired and wireless headphones to my [phone / laptop] and fix it if the sound still comes from the speaker." },
  { id: "technology-384", title: "Video call for birthday celebration", category: "technology", text: "Help me plan a video call birthday celebration for [name] with family in [number] cities. Suggest games, a cake-cutting moment on camera, music, and how to take a group screenshot. Give me a simple plan for a [number]-minute call." },
  { id: "technology-385", title: "Switch camera during video call", category: "technology", text: "Teach me how to switch between the front and back camera during a video call on my phone, so I can show my family the room, the garden or a dish I cooked. Give me simple steps and explain what the button looks like." },
  { id: "technology-386", title: "Video call data usage control", category: "technology", text: "Video calls use up my mobile data quickly. Explain how much data a one-hour video call uses, how to lower video quality to save data, and when to switch to audio only. Give me simple settings to change on my phone." },
  { id: "technology-387", title: "Video call for tuition classes", category: "technology", text: "I teach tuition classes by video call for [subject] to [number] students. Give me tips to run a smooth class: sharing notes on screen, keeping students engaged, muting noise, and giving homework. Suggest a simple routine for a one-hour class." },
  { id: "technology-388", title: "Video call safety for children", category: "technology", text: "My child attends video classes and calls relatives online. Give me 10 simple safety rules: only accept calls from known people, never share personal details, keep the camera in a common room, and tell a parent about anything strange." },
  { id: "technology-389", title: "Schedule a video meeting link", category: "technology", text: "Teach me how to create a video meeting link and share it with [number] people for a meeting on [date] at [time]. Explain how to send the link by email or message, how people join, and what to do if someone cannot join." },
  { id: "technology-390", title: "Video call on slow internet", category: "technology", text: "My internet is slow and video calls keep breaking. Give me 10 practical tips to manage: turn off your camera, use audio only, close other apps, and sit near the router. Explain each tip simply and tell me the best backup plan." },
  { id: "technology-391", title: "Take notes during video meetings", category: "technology", text: "Teach me how to take quick, useful notes during a video meeting at work. Give me a simple note format with date, people, decisions and tasks, and show me a filled example for a meeting about [topic]. Keep the method easy for a beginner." },
  { id: "technology-392", title: "Video call with elderly relatives", category: "technology", text: "Help me set up easy video calls with my elderly parents who find technology confusing. Explain how to make calling one tap, use big buttons, speak loudly and clearly, and fix the common problems they face during a call." },
  { id: "technology-393", title: "Present slides on video call", category: "technology", text: "I need to present slides on a video call for [work / school]. Teach me how to share my slides, move to the next slide, see my notes, and handle questions. Give me a short checklist to practise before the real call." },
  { id: "technology-394", title: "Video call lighting on budget", category: "technology", text: "My face looks dark on video calls. Give me simple, cheap ways to improve lighting at home: sit facing a window, use a table lamp, avoid light behind you, and use a white wall. Explain each tip and the cost, if any, in rupees." },
  { id: "technology-395", title: "End video call politely", category: "technology", text: "Teach me polite ways to end a video call at work and with family: a clear closing line, thanking everyone, and confirming next steps. Give me 5 example closing lines for different situations, and explain how to leave without seeming rude." },
  { id: "technology-396", title: "Laptop for railway exam preparation", category: "technology", text: "I am preparing for a railway exam and need a laptop for online mock tests, videos and notes. My budget is ₹[amount]. Recommend 3 affordable laptops, compare screen comfort, battery and storage, and tell me which is best for long study hours." },
  { id: "technology-397", title: "Laptop cooling pad worth it", category: "technology", text: "My laptop heats up during long video calls and study sessions. Explain what a cooling pad does, whether it really helps, how to choose one under ₹[amount], and 5 free ways to keep the laptop cool without buying anything." },
  { id: "technology-398", title: "Laptop for music and films", category: "technology", text: "I mainly use a laptop to watch films, listen to music and browse the internet. My budget is ₹[amount]. Recommend 3 laptops with good screens and speakers, compare their sound and display quality, and tell me which gives the best experience at home." },
  { id: "technology-399", title: "Laptop insurance and protection plan", category: "technology", text: "The shop offered me an accidental damage protection plan for ₹[amount] with my new laptop. Explain what it covers, what it does not, and whether it is worth buying. Tell me the questions to ask before paying for it." },
  { id: "technology-400", title: "Use laptop as second screen", category: "technology", text: "Explain how to use an old laptop as a second screen or how to connect my laptop to a TV for a bigger display. Give me simple steps, the cables I need, and how to change the display settings so the picture looks right." },
  { id: "technology-401", title: "Laptop for digital payments shop", category: "technology", text: "I run a small shop and use my laptop for UPI records, billing and online orders. My budget is ₹[amount]. Recommend 3 reliable laptops with good battery and security, compare their prices, and tell me which suits a busy shop counter best." },
  { id: "technology-402", title: "Laptop webcam cover and privacy", category: "technology", text: "Explain why people cover their laptop webcam and whether I should do it too. Teach me simple privacy steps: cover the camera when not in use, check which apps can use it, and keep the laptop software updated. Use very simple language." },
  { id: "technology-403", title: "Laptop for competitive exam study", category: "technology", text: "I am preparing for a competitive exam and need a laptop for online tests, PDFs and video lectures. My budget is ₹[amount]. Compare 3 laptops for battery life, screen comfort during long reading, and storage for study material, then recommend one." },
  { id: "technology-404", title: "Check laptop is genuine new", category: "technology", text: "Teach me how to check that a laptop I bought is brand new and genuine, not used or refurbished. Explain how to check the seal, serial number, warranty status online, and battery health. List the warning signs that the laptop was used before." },
  { id: "technology-405", title: "Laptop for home tuition business", category: "technology", text: "I run home tuition classes and need a laptop for teaching, attendance and fee records. My budget is ₹[amount]. Recommend 3 laptops with a good camera, clear sound and long battery, compare them, and pick the best one for daily teaching." },
  { id: "technology-406", title: "Wi-Fi router buying guide", category: "technology", text: "Help me buy a good Wi-Fi router for a [number]-room house in [your city]. My budget is ₹[amount]. Compare 3 routers for range, speed, number of devices and ease of setup, and recommend the best one for a family of [number] people." },
  { id: "technology-407", title: "Wi-Fi for rented house setup", category: "technology", text: "I have moved to a rented house in [your city] and need internet. Explain my options: a new broadband connection, sharing with the landlord, or using mobile data. Compare cost, speed and setup time, and recommend the simplest option for [number] months." },
  { id: "technology-408", title: "Wi-Fi signal in every room", category: "technology", text: "Some rooms in my house get no Wi-Fi signal. Give me a step-by-step plan to fix dead zones: move the router, change its angle, remove obstacles, and add an extender if needed. Explain each step simply and tell me the cheapest fix to try first." },
  { id: "technology-409", title: "Wi-Fi for festival live streaming", category: "technology", text: "We want to live stream a family function from home for relatives abroad. Tell me the internet speed needed, how to test it, where to place the router, and what backup to keep ready if the connection drops during the function." },
  { id: "technology-410", title: "Change broadband provider easily", category: "technology", text: "I want to change my broadband provider in [your city] because of slow speed and poor service. Explain the steps: compare plans, check installation, keep my old connection until the new one works, and what to do with the old router." },
  { id: "technology-411", title: "Browser for old slow laptop", category: "technology", text: "My old laptop is slow and the browser takes forever to open. Recommend a light browser that runs well on old laptops, explain how to install it, and give me 8 tips to make browsing faster, like closing tabs and blocking heavy adverts." },
  { id: "technology-412", title: "Open two websites side by side", category: "technology", text: "Teach me how to open two websites side by side on my laptop screen, so I can compare prices or copy details from one to the other. Give me simple steps and keyboard shortcuts, and explain how to return to a single full window." },
  { id: "technology-413", title: "Email for college admission enquiry", category: "technology", text: "Draft a polite email to a college in [city] asking about admission to a [course name] course. Ask about fees, last date, documents needed and hostel facilities. Keep it short, respectful and clear, with a proper subject line and closing." },
  { id: "technology-414", title: "Email to bank for statement", category: "technology", text: "Draft a polite email to my bank asking for my account statement for [month] and information about [service]. Include my account details safely, a clear subject line, and a respectful closing. Keep the email short and professional in simple English." },
  { id: "technology-415", title: "Print labels for home business", category: "technology", text: "I run a small home business selling [product] and need to print address labels and price tags. Teach me how to design simple labels on my laptop, choose the right paper, and print them neatly at home without wasting sheets." },
  { id: "technology-416", title: "Scan and email school certificates", category: "technology", text: "I need to scan my child's certificates and email them to the school. Teach me how to scan clearly with my phone, save the scans as PDFs, name them properly, and attach them to an email. Give me a checklist before pressing send." },
  { id: "technology-417", title: "File naming system for office", category: "technology", text: "Help me create a simple file naming system for my office documents on the laptop. Suggest a format with date, client name and document type, give 10 examples, and explain how the system makes finding any file fast and easy." },
  { id: "technology-418", title: "Print wedding invitation cards", category: "technology", text: "We are printing wedding invitation cards at home for [number] guests. Teach me how to design a simple card on the laptop, choose good paper, set the print size, and print a test card first. Give me tips to keep the cost low." },
  { id: "technology-419", title: "Wi-Fi hotspot for school project", category: "technology", text: "My child needs internet for a school project at a place with no Wi-Fi. Explain how to use a phone hotspot safely, how much data a [number]-hour research session uses, and how to stop the hotspot so mobile data is not wasted." },
  { id: "technology-420", title: "Browser reading mode for articles", category: "technology", text: "Long articles are hard to read with adverts everywhere. Teach me how to use reading mode in the browser on my [phone / laptop] to see clean text, change the font size, and save the article to read later without internet." },
  { id: "technology-421", title: "Email reminder for bill payment", category: "technology", text: "Help me write a polite email reminder to a customer about a pending payment of ₹[amount] for [product / service]. Keep the tone friendly, mention the due date, offer easy payment options, and close with thanks. Keep it under [number] lines." },
  { id: "technology-422", title: "Create a family photo folder", category: "technology", text: "Help me organise family photos into folders by year and event on my laptop, like Diwali 2025 and [event name]. Explain how to create folders, move photos, rename the best ones, and back up the whole collection so nothing is lost." },
  { id: "technology-423", title: "Print railway ticket from phone", category: "technology", text: "I booked a train ticket on my phone and need a printed copy for my journey from [city A] to [city B] on [date]. Teach me how to find the ticket, download it, and print it from my phone or a nearby shop. Tell me what to check on the print." },
  { id: "technology-424", title: "Video call for family puja", category: "technology", text: "Help me organise a video call so family members in [number] cities can join our home puja together. Explain how to set up the phone for a clear view, test the sound, invite everyone, and keep the call running smoothly for [number] minutes." },
  { id: "technology-425", title: "Laptop care during travel", category: "technology", text: "I travel by train often with my laptop. Give me 10 practical tips to protect it during travel: a padded bag, keeping it dry, avoiding heat, charging safely at stations, and what to do if it gets wet or dropped. Explain each tip simply." },
  { id: "technology-426", title: "Set up WhatsApp for the first time", category: "technology", text: "Explain how to set up WhatsApp on a new phone for a complete beginner. Cover downloading the app, verifying the mobile number, adding a profile photo and name, and sending the first message. Use simple steps and mention [your phone model]." },
  { id: "technology-427", title: "Send photos and videos on WhatsApp", category: "technology", text: "Show me how to send photos and videos on WhatsApp without losing quality. Explain the camera button, choosing from the gallery, sending as a document, and sending several photos at once. Include tips for [a family function] photos." },
  { id: "technology-428", title: "Make voice and video calls on WhatsApp", category: "technology", text: "Explain how to make a voice call and a video call on WhatsApp. Cover calling one person, adding more people, switching between voice and video during a call, and what to do when the call keeps breaking. Use an example with [a family member]." },
  { id: "technology-429", title: "Use WhatsApp voice messages easily", category: "technology", text: "Teach me to send and listen to voice messages on WhatsApp. Explain holding the microphone button, locking it for long messages, playing a message at faster speed, and deleting a voice message before sending it. Keep the steps simple for [an elderly parent]." },
  { id: "technology-430", title: "Share your live location on WhatsApp", category: "technology", text: "Explain how to share a live location on WhatsApp for one hour or eight hours. Cover choosing a contact or group, stopping the sharing early, and when sharing location is useful and safe. Give an example for [a train journey]." },
  { id: "technology-431", title: "Send documents and PDFs on WhatsApp", category: "technology", text: "Show me how to send a PDF, a photo of a document, or a Word file on WhatsApp. Explain the attach button, choosing a document, checking the file size, and confirming the other person received it. Use an example of [an admission form]." },
  { id: "technology-432", title: "Star important WhatsApp messages", category: "technology", text: "Explain how to star an important message on WhatsApp so I can find it later. Cover starring a message, viewing all starred messages, unstarring one, and using this for addresses, account numbers and [an important date]." },
  { id: "technology-433", title: "Search old messages on WhatsApp", category: "technology", text: "Teach me to search for old messages, photos and links inside a WhatsApp chat. Explain the search bar, searching by a word, filtering photos and documents, and searching across all chats. Use an example of finding [a shop address]." },
  { id: "technology-434", title: "Mute WhatsApp chats and notifications", category: "technology", text: "Explain how to mute a noisy WhatsApp chat for eight hours, one week or always. Cover muting one chat, muting a group, turning off notification sounds, and unmuting later. Give an example with [a busy school group]." },
  { id: "technology-435", title: "Archive chats on WhatsApp", category: "technology", text: "Show me how to archive WhatsApp chats I do not need every day. Explain archiving one chat, viewing archived chats, unarchiving a chat, and whether archived chats still receive new messages. Use an example of [an old work group]." },
  { id: "technology-436", title: "Block and report spam on WhatsApp", category: "technology", text: "Explain how to block a stranger and report spam on WhatsApp. Cover blocking a number, reporting a suspicious message, what happens after blocking, and how to unblock someone by mistake. Give an example of [a fake prize message]." },
  { id: "technology-437", title: "Use WhatsApp disappearing messages", category: "technology", text: "Teach me how to switch on disappearing messages on WhatsApp. Explain the 24-hour, 7-day and 90-day choices, which chats it works in, what happens to photos, and when not to use it. Use an example of [a one-time password]." },
  { id: "technology-438", title: "Change WhatsApp privacy settings", category: "technology", text: "Explain the main WhatsApp privacy settings in simple words. Cover last seen, profile photo, about, read receipts and who can add me to groups. Tell me what each choice means and suggest safe settings for [a school student]." },
  { id: "technology-439", title: "Set a WhatsApp profile photo and about", category: "technology", text: "Show me how to set a good profile photo and write a short about line on WhatsApp. Explain choosing a clear photo, cropping it, writing a simple about line, and who can see it. Suggest ideas suitable for [a small shop owner]." },
  { id: "technology-440", title: "Back up WhatsApp chats safely", category: "technology", text: "Explain how to back up WhatsApp chats so I never lose them when changing phones. Cover automatic daily backup, manual backup, checking the backup date, and restoring chats on a new phone. Mention [Google Drive] in simple words." },
  { id: "technology-441", title: "Use WhatsApp on a computer", category: "technology", text: "Teach me to use WhatsApp on a computer through the web version or the desktop app. Explain linking the phone, scanning the code, sending messages from the computer, and logging out safely. Give an example for [office work]." },
  { id: "technology-442", title: "Send a broadcast message on WhatsApp", category: "technology", text: "Explain the difference between a WhatsApp group and a broadcast list. Show me how to create a broadcast list, send one message to many people, and who can reply. Give an example for [a festival greeting]." },
  { id: "technology-443", title: "React to messages with emojis", category: "technology", text: "Show me how to react to a WhatsApp message with an emoji instead of typing a reply. Explain long-pressing a message, choosing an emoji, changing a reaction, and removing it. Give examples for [a birthday wish] and [a good news message]." },
  { id: "technology-444", title: "Edit and delete WhatsApp messages", category: "technology", text: "Explain how to edit a WhatsApp message after sending it and how to delete a message for everyone. Cover the time limits, what the other person sees, and when editing is better than deleting. Use an example of [a wrong price]." },
  { id: "technology-445", title: "Pin important chats on WhatsApp", category: "technology", text: "Teach me to pin my most important chats to the top of WhatsApp. Explain pinning up to three chats, unpinning a chat, and which chats are worth pinning. Give an example with [family], [school] and [office] chats." },
  { id: "technology-446", title: "Use WhatsApp polls in a chat", category: "technology", text: "Explain how to create a poll on WhatsApp to ask a group a quick question. Cover writing the question, adding options, allowing several answers, and seeing the results. Give an example for choosing [a picnic date]." },
  { id: "technology-447", title: "Share a contact on WhatsApp", category: "technology", text: "Show me how to share a contact number through WhatsApp. Explain opening the attach menu, choosing a contact, sending one number or several, and checking the receiver got the right number. Use an example of sharing [a plumber] number." },
  { id: "technology-448", title: "Use WhatsApp stickers and GIFs", category: "technology", text: "Explain how to send stickers and GIFs on WhatsApp. Cover opening the sticker panel, downloading a sticker pack, searching for a GIF, and saving a favourite sticker. Keep it fun and simple for [a grandmother]." },
  { id: "technology-449", title: "Record a video message on WhatsApp", category: "technology", text: "Teach me to record a short video message on WhatsApp. Explain switching from voice to video message, recording up to one minute, previewing it, and sending it. Give an example for wishing [a friend] on a birthday." },
  { id: "technology-450", title: "Check WhatsApp storage and free space", category: "technology", text: "Explain how to check how much phone storage WhatsApp is using. Cover finding large videos and chats, deleting old media safely, and stopping automatic downloads. Give steps that help a phone with [low storage] run faster." },
  { id: "technology-451", title: "Stop WhatsApp downloading media automatically", category: "technology", text: "Show me how to stop WhatsApp from downloading every photo and video automatically. Explain the media auto-download settings for mobile data and Wi-Fi, and how to download one photo manually. Use an example for [a limited data plan]." },
  { id: "technology-452", title: "Use two WhatsApp accounts on one phone", category: "technology", text: "Explain whether I can use two WhatsApp accounts on one phone and how it works. Cover the official second-account option, needing two numbers, switching accounts, and keeping work and personal chats separate. Mention [a shop number] as an example." },
  { id: "technology-453", title: "Change WhatsApp chat wallpaper", category: "technology", text: "Teach me to change the chat wallpaper on WhatsApp. Explain choosing a colour or a photo, setting one wallpaper for all chats, setting a different one for a special chat, and going back to the default. Use [a favourite colour] as an example." },
  { id: "technology-454", title: "Use WhatsApp channels for updates", category: "technology", text: "Explain what WhatsApp Channels are and how to follow one. Cover finding a channel, following it, reading updates, reacting to a post, and unfollowing it. Give examples of useful channels for [local news] and [a cricket team]." },
  { id: "technology-455", title: "Make a WhatsApp group video call", category: "technology", text: "Show me how to start a group video call on WhatsApp with up to eight people on screen. Explain starting from a group, adding people during a call, muting yourself, and fixing a frozen video. Use an example of [a family video call]." },
  { id: "technology-456", title: "Send a WhatsApp message to yourself", category: "technology", text: "Explain how to message yourself on WhatsApp to save notes, links and reminders. Cover opening the message-yourself chat, saving a shopping list, forwarding a useful message there, and finding it later. Give an example with [a train ticket]." },
  { id: "technology-457", title: "Use WhatsApp Communities for a society", category: "technology", text: "Explain WhatsApp Communities in simple words for a housing society or school. Cover creating a community, adding groups under it, sending an announcement to everyone, and who can see member numbers. Use [an apartment society] as an example." },
  { id: "technology-458", title: "Fix WhatsApp not sending messages", category: "technology", text: "Help me fix WhatsApp when my messages show only one tick and do not send. List the checks in order: internet, aeroplane mode, date and time, storage, and reinstalling the app. Explain each step simply for [a slow connection]." },
  { id: "technology-459", title: "Understand WhatsApp ticks and online status", category: "technology", text: "Explain what one grey tick, two grey ticks, two blue ticks and online mean on WhatsApp. Cover when a message is sent, delivered and read, why ticks sometimes stay grey, and how read receipts work. Use simple examples for [a parent]." },
  { id: "technology-460", title: "Use WhatsApp for a small business", category: "technology", text: "Explain how a small shop can use WhatsApp Business. Cover the business profile, catalogue, greeting message, away message, labels for customers, and quick replies. Give an example for [a tailoring shop] in a small town." },
  { id: "technology-461", title: "Set up WhatsApp Business catalogue", category: "technology", text: "Show me how to add products to a WhatsApp Business catalogue. Explain adding a photo, name, price in rupees, description and link, and how a customer sees the catalogue. Use an example of [a bakery] with five items." },
  { id: "technology-462", title: "Use quick replies on WhatsApp Business", category: "technology", text: "Explain quick replies on WhatsApp Business for answering the same questions fast. Cover creating a shortcut, writing the reply, using it in a chat, and editing it later. Give examples for [price], [timings] and [delivery] questions." },
  { id: "technology-463", title: "Share a WhatsApp Business payment link", category: "technology", text: "Explain how a small business can share a payment link or UPI ID on WhatsApp after a customer confirms an order. Cover writing a clear message with the amount, checking payment, and sending a receipt. Use an example order of [₹500]." },
  { id: "technology-464", title: "Create a WhatsApp group for family", category: "technology", text: "Show me how to create a WhatsApp family group from scratch. Explain adding members, choosing a group name and photo, writing a short group description, and setting who can send messages. Use an example of [a joint family] with 20 members." },
  { id: "technology-465", title: "Add and remove group members on WhatsApp", category: "technology", text: "Explain how to add new members to a WhatsApp group and remove members politely. Cover adding by contact, using an invite link, removing a member, and what happens when someone leaves. Give an example for [a class group]." },
  { id: "technology-466", title: "Set group admin controls on WhatsApp", category: "technology", text: "Explain group admin controls on WhatsApp. Cover making someone an admin, removing admin rights, choosing who can change group details, and choosing who can send messages. Give an example for [a residents welfare group]." },
  { id: "technology-467", title: "Share a WhatsApp group invite link", category: "technology", text: "Show me how to create and share a WhatsApp group invite link. Explain copying the link, sharing it on another app, resetting the link when it spreads too far, and who should receive it. Use an example of [a wedding group]." },
  { id: "technology-468", title: "Leave a WhatsApp group quietly", category: "technology", text: "Explain how to leave a WhatsApp group without making a fuss. Cover exiting a group, what other members see, deleting the group chat afterwards, and muting it instead of leaving. Give an example of [an old school group]." },
  { id: "technology-469", title: "Post a WhatsApp Status update", category: "technology", text: "Teach me to post a photo or video as my WhatsApp Status. Explain taking a photo, adding text or a sticker, choosing who can see it, and how long it stays visible. Give an example for [a festival morning]." },
  { id: "technology-470", title: "Choose who sees my WhatsApp Status", category: "technology", text: "Explain how to control who can see my WhatsApp Status. Cover sharing with all contacts, sharing with selected contacts only, hiding it from some people, and changing the setting later. Use an example for [a family photo]." },
  { id: "technology-471", title: "View and reply to WhatsApp Status", category: "technology", text: "Show me how to view friends WhatsApp Status updates and reply to one. Explain opening the Status tab, watching a photo or video, replying privately, and reacting with an emoji. Give an example for [a birthday Status]." },
  { id: "technology-472", title: "Delete a WhatsApp Status update", category: "technology", text: "Explain how to delete a WhatsApp Status I posted by mistake. Cover opening my Status, finding the update, deleting it, and checking it is gone. Also explain what happens if someone already saw it, using [a wrong photo] as an example." },
  { id: "technology-473", title: "Share a video Status on WhatsApp", category: "technology", text: "Teach me to share a short video as WhatsApp Status. Explain recording a video, trimming it, adding a caption, and posting it. Mention the time limit and how to post a longer video in parts, using [a school function] as an example." },
  { id: "technology-474", title: "Mute Status updates from one person", category: "technology", text: "Explain how to mute Status updates from one contact without blocking them. Cover long-pressing their Status, choosing mute, finding muted updates later, and unmuting them. Give an example of [a contact who posts too often]." },
  { id: "technology-475", title: "Use text Status on WhatsApp", category: "technology", text: "Show me how to post a text-only Status on WhatsApp with a coloured background. Explain writing a short message, choosing a colour and font, adding an emoji, and posting it. Suggest ideas for [a good morning message]." },
  { id: "technology-476", title: "Share a link in a WhatsApp group", category: "technology", text: "Explain how to share a useful link in a WhatsApp group without spamming members. Cover pasting the link, adding one line explaining it, checking the link first, and when not to share. Use an example of [a school holiday notice]." },
  { id: "technology-477", title: "Manage a busy school WhatsApp group", category: "technology", text: "Give me simple rules for managing a busy school parents WhatsApp group. Cover pinning important notices, limiting messages to school topics, setting quiet hours, and handling repeated forwards. Write it for [a class teacher]." },
  { id: "technology-478", title: "Stop unwanted forwards in a group", category: "technology", text: "Explain how to reduce unwanted forwards and good morning images in a WhatsApp group. Cover asking members politely, using admin-only messages, and muting the group. Give a polite message I can copy for [a family group]." },
  { id: "technology-479", title: "Find a message in a WhatsApp group", category: "technology", text: "Teach me to find one important message inside a busy WhatsApp group. Explain searching inside the group, using starred messages, and scrolling to a date. Use an example of finding [a meeting time] in a group with 100 messages a day." },
  { id: "technology-480", title: "Tag one person in a WhatsApp group", category: "technology", text: "Explain how to tag one person in a WhatsApp group so they notice a message. Cover typing the at symbol, choosing the person, replying to their message, and when tagging is polite. Give an example for asking [the class monitor] a question." },
  { id: "technology-481", title: "Set a group description on WhatsApp", category: "technology", text: "Show me how to write a clear group description on WhatsApp. Explain what to include: purpose, rules, timings and important contacts. Give a sample description for [a building maintenance group] with about 30 members." },
  { id: "technology-482", title: "Use WhatsApp Status for a shop", category: "technology", text: "Explain how a small shop can use WhatsApp Status to show new stock. Cover posting one clear photo a day, writing the price, adding timings, and replying to customers who ask. Give an example for [a vegetable shop] in Chennai." },
  { id: "technology-483", title: "Share festival wishes on WhatsApp Status", category: "technology", text: "Help me plan five different WhatsApp Status ideas for Diwali. Include a family photo, a rangoli video, a short greeting, a sweets photo and a lights video. Write a one-line caption for each, suitable for [a joint family]." },
  { id: "technology-484", title: "Keep WhatsApp group chats organised", category: "technology", text: "Give me a simple system to keep many WhatsApp groups organised. Cover pinning three important groups, archiving old ones, muting noisy ones, and checking starred messages weekly. Write it for someone in [ten groups]." },
  { id: "technology-485", title: "Report a fake message in a group", category: "technology", text: "Explain what to do when someone shares a fake news message in a WhatsApp group. Cover checking the claim, replying politely with the correct fact, not forwarding it further, and reporting it if needed. Use [a fake health tip] as an example." },
  { id: "technology-486", title: "Create a simple email address", category: "technology", text: "Explain how to create a free email address for the first time. Cover choosing a simple name, picking a strong password, adding a recovery phone number, and writing down the details safely. Use an example name for [a student] in India." },
  { id: "technology-487", title: "Write a polite email to a teacher", category: "technology", text: "Draft a polite email from a parent to a teacher asking about a childs homework. Include a clear subject line, a respectful greeting, the question in two short lines, and a thank-you closing. Use placeholders for [child name] and [class]." },
  { id: "technology-488", title: "Write a leave application email", category: "technology", text: "Draft a short leave application email to a manager for two days of sick leave. Include the subject line, dates, reason in one line, who will handle urgent work, and a polite closing. Use placeholders for [your name] and [dates]." },
  { id: "technology-489", title: "Write a job application email", category: "technology", text: "Draft a simple job application email for a shop assistant post. Include a clear subject line, a short introduction, two lines about experience, mention of the attached CV, and a polite closing. Use placeholders for [your name] and [shop name]." },
  { id: "technology-490", title: "Write an email to a bank", category: "technology", text: "Draft a polite email to a bank asking about a failed transaction. Include the subject line, account details to mention safely, the date and amount, what happened, and what help I need. Use placeholders for [amount] and [date]." },
  { id: "technology-491", title: "Write a complaint email to a shop", category: "technology", text: "Draft a calm complaint email to an online shop about a damaged item received. Include the order number, what arrived, what was wrong, a photo mention, and the refund or replacement I want. Use placeholders for [order number] and [item]." },
  { id: "technology-492", title: "Write a thank-you email after an interview", category: "technology", text: "Draft a short thank-you email to send after a job interview. Include a clear subject line, thanks for their time, one line about why I fit the role, and a polite closing. Use placeholders for [interviewer name] and [job title]." },
  { id: "technology-493", title: "Write a formal invitation email", category: "technology", text: "Draft a formal invitation email for a housewarming function. Include the subject line, date, time, address, a warm welcome line, and a request to confirm attendance. Use placeholders for [date], [time] and [address]." },
  { id: "technology-494", title: "Write an email asking for a quotation", category: "technology", text: "Draft an email asking a caterer for a quotation for a birthday party. Include the date, number of guests, vegetarian menu needs, venue, and a request for the total price. Use placeholders for [date] and [number of guests]." },
  { id: "technology-495", title: "Write a follow-up email politely", category: "technology", text: "Draft a polite follow-up email to someone who has not replied in five days. Include a friendly opening, a reminder of my earlier email, the one thing I still need, and a thank-you. Use placeholders for [their name] and [topic]." },
  { id: "technology-496", title: "Understand CC and BCC in email", category: "technology", text: "Explain CC and BCC in email in simple words with examples. Cover when to use CC, when to use BCC, who can see each list, and a common mistake to avoid. Give an example of emailing [three teachers] about a school event." },
  { id: "technology-497", title: "Attach a file to an email", category: "technology", text: "Explain how to attach a photo, PDF or document to an email. Cover the attach button, choosing the file, checking the file size, and writing one line about the attachment. Use an example of sending [a CV] to an employer." },
  { id: "technology-498", title: "Write a clear email subject line", category: "technology", text: "Teach me to write clear email subject lines that get opened. Give ten examples for common needs like leave, fees, orders and meetings, and explain why short and specific works best. Use examples for [a school] and [an office]." },
  { id: "technology-499", title: "Reply to an email professionally", category: "technology", text: "Explain how to reply to a work email professionally. Cover replying to the sender only, replying to all, keeping the subject, answering each point, and signing off politely. Give an example reply about [a meeting time]." },
  { id: "technology-500", title: "Organise emails with folders and labels", category: "technology", text: "Show me a simple way to organise my inbox with folders or labels. Cover creating folders for bills, school, work and family, moving emails, and finding them later. Write the steps for someone who receives [50 emails] a week." },
  { id: "technology-501", title: "Organise my inbox with folders and filters", category: "technology", text: "My inbox is full of mixed emails from work, family, and shops. Teach me to organise it with folders and filters on [my phone / laptop]. Show how to make a filter that moves [shop offers] to one folder automatically, and give a simple weekly habit to keep the inbox tidy." },
  { id: "technology-502", title: "Check a suspicious link without clicking it", category: "technology", text: "I got an email with a link I am not sure about. Teach me how to check if the link is safe without clicking it. Explain how to look at the real address, why short links hide the truth, and what to do if I already tapped it on [my phone]." },
  { id: "technology-503", title: "Write an email to a school principal", category: "technology", text: "Draft a respectful email to a school principal requesting a transfer certificate. Include the subject line, student details, reason, date needed by, and a polite closing. Use placeholders for [student name] and [class]." },
  { id: "technology-504", title: "Write an email for a fee refund", category: "technology", text: "Draft a polite email asking a coaching centre for a fee refund after cancelling admission. Include the student name, course, amount paid, date, reason, and bank details to mention safely. Use placeholders for [amount] and [course]." },
  { id: "technology-505", title: "Write a condolence email with care", category: "technology", text: "Draft a short, warm condolence email to a colleague who lost a family member. Keep it simple, kind and respectful, with no advice and no questions. Use placeholders for [their name] and [the family member]." },
  { id: "technology-506", title: "Write an email to book a hall", category: "technology", text: "Draft an email to book a marriage hall for a function. Include the date, timings, number of guests, food needs, and a request for the price and availability. Use placeholders for [date] and [number of guests]." },
  { id: "technology-507", title: "Write an email asking for a holiday", category: "technology", text: "Draft an email to a manager asking for five days of annual leave. Include the dates, reason, who will cover my work, and my phone number for urgent calls. Use placeholders for [dates] and [your name]." },
  { id: "technology-508", title: "Write an apology email to a customer", category: "technology", text: "Draft a sincere apology email from a small shop to a customer whose order arrived late. Include an apology, the reason in one line, what will be done, and a small goodwill offer. Use placeholders for [customer name] and [order number]." },
  { id: "technology-509", title: "Write an email to change a delivery address", category: "technology", text: "Draft an email asking an online shop to change my delivery address before dispatch. Include the order number, the old address, the new address, and a request for confirmation. Use placeholders for [order number] and [new address]." },
  { id: "technology-510", title: "Write an email to a landlord", category: "technology", text: "Draft a polite email to a landlord reporting a leaking tap in the kitchen. Include the flat number, when it started, a photo mention, and a request for a plumber visit. Use placeholders for [flat number] and [your name]." },
  { id: "technology-511", title: "Write an email to a newspaper editor", category: "technology", text: "Draft a short letter-style email to a newspaper editor about a broken street light in my area. Include the area name, how long it has been broken, the problem it causes, and a request for action. Use placeholders for [area name] and [your name]." },
  { id: "technology-512", title: "Write a welcome email to new members", category: "technology", text: "Draft a warm welcome email for new members joining a residents association. Include a greeting, what the group does, meeting timings, the WhatsApp group link mention, and a contact person. Use placeholders for [society name] and [contact name]." },
  { id: "technology-513", title: "Write an email to cancel a subscription", category: "technology", text: "Draft a clear email to cancel a monthly magazine subscription. Include my name, subscription number, the date from which to stop it, and a request for written confirmation. Use placeholders for [subscription number] and [your name]." },
  { id: "technology-514", title: "Write an email to a travel agent", category: "technology", text: "Draft an email to a travel agent asking for a family holiday package to Kerala. Include travel dates, number of people, budget in rupees, hotel needs, and vegetarian food. Use placeholders for [dates] and [budget]." },
  { id: "technology-515", title: "Write an email to order cakes", category: "technology", text: "Draft an email to a bakery ordering a birthday cake. Include the flavour, weight, eggless requirement, message on the cake, pickup date and time, and my phone number. Use placeholders for [date] and [flavour]." },
  { id: "technology-516", title: "Set up an email signature", category: "technology", text: "Explain how to create a simple email signature with my name, job, phone number and shop address. Cover where to find the signature setting, what to include, what to leave out, and testing it. Use an example for [a tuition teacher]." },
  { id: "technology-517", title: "Search old emails quickly", category: "technology", text: "Teach me to search old emails quickly using the search bar. Cover searching by sender, by subject words, by date, and by attachment. Give examples for finding [a flight ticket] and [a school fee receipt]." },
  { id: "technology-518", title: "Forward an email to someone else", category: "technology", text: "Explain how to forward an email to another person safely. Cover the forward button, adding a short note on top, removing private details if needed, and checking the recipient. Use an example of forwarding [a bill] to a family member." },
  { id: "technology-519", title: "Create an email filter for bills", category: "technology", text: "Show me how to create a simple email filter that moves all electricity and phone bills into one folder. Explain choosing the sender, creating the filter, and checking it works. Use an example with [an electricity board] sender." },
  { id: "technology-520", title: "Write a short business introduction email", category: "technology", text: "Draft a short introduction email for a new tailoring shop in a neighbourhood. Include the shop name, services, opening offer, address, timings and WhatsApp number. Use placeholders for [shop name] and [address]." },
  { id: "technology-521", title: "Set up Facebook for the first time", category: "technology", text: "Explain how to create a Facebook account safely for the first time. Cover choosing a name, adding a mobile number, setting a strong password, adding a profile photo, and finding friends. Mention privacy choices for [a new user]." },
  { id: "technology-522", title: "Post a photo on Facebook", category: "technology", text: "Show me how to post a photo on Facebook with a short caption. Explain choosing the photo, writing a caption, tagging people, choosing who can see it, and posting it. Give an example for [a family function] photo." },
  { id: "technology-523", title: "Change Facebook privacy settings", category: "technology", text: "Explain the main Facebook privacy settings in simple words. Cover who can see posts, who can send friend requests, who can see the friends list, and profile visibility. Suggest safe settings for [a school student]." },
  { id: "technology-524", title: "Find old school friends on Facebook", category: "technology", text: "Teach me to find old school friends on Facebook. Cover searching by name, by school, by city, using mutual friends, and sending a polite friend request. Give an example for finding friends from [a school in Madurai]." },
  { id: "technology-525", title: "Create a Facebook group for a community", category: "technology", text: "Explain how to create a Facebook group for a neighbourhood or hobby club. Cover choosing a name, setting it public or private, inviting members, writing group rules, and posting the first welcome message. Use [a gardening club] as an example." },
  { id: "technology-526", title: "Join a Facebook group safely", category: "technology", text: "Show me how to join a useful Facebook group and stay safe in it. Cover searching for a group, reading its rules, answering joining questions, and leaving if it feels unsafe. Give an example of [a cooking group]." },
  { id: "technology-527", title: "Share a post on Facebook", category: "technology", text: "Explain how to share someone elses useful post on Facebook. Cover the share button, adding your own line, choosing your audience, and checking the original source first. Use an example of sharing [a blood donation request]." },
  { id: "technology-528", title: "Use Facebook Marketplace to buy", category: "technology", text: "Teach me to buy a second-hand item safely on Facebook Marketplace. Cover searching, checking photos and price, messaging the seller, meeting in a public place, and paying only after checking the item. Use [a study table] as an example." },
  { id: "technology-529", title: "Sell an old item on Facebook Marketplace", category: "technology", text: "Show me how to sell an old cycle on Facebook Marketplace. Explain taking clear photos, writing an honest description, setting a fair price in rupees, replying to buyers, and meeting safely. Use [a bicycle] in good condition as an example." },
  { id: "technology-530", title: "Use Facebook Messenger for chats", category: "technology", text: "Explain how to chat on Facebook Messenger. Cover opening a chat, sending text, photos and voice messages, making a call, and muting a noisy chat. Give an example of chatting with [a cousin] living abroad." },
  { id: "technology-531", title: "Create a Facebook Page for a shop", category: "technology", text: "Explain how to create a Facebook Page for a small shop. Cover choosing the page name and category, adding a photo and address, writing a short description, and posting the first update. Use [a flower shop] as an example." },
  { id: "technology-532", title: "Post a shop offer on Facebook", category: "technology", text: "Help me write a Facebook post for a small shop offering a festival discount. Include a clear headline, the offer, dates, address and contact number, in simple words. Use placeholders for [shop name] and [discount]." },
  { id: "technology-533", title: "Block someone on Facebook", category: "technology", text: "Explain how to block someone on Facebook and what happens after blocking. Cover blocking from their profile, unfriending first, reporting a fake profile, and unblocking later. Give an example of blocking [a stranger] sending unwanted messages." },
  { id: "technology-534", title: "Report a fake profile on Facebook", category: "technology", text: "Teach me to report a fake profile pretending to be a friend on Facebook. Cover opening the profile, choosing report, picking the right reason, and warning friends. Use an example of [a duplicate profile] asking for money." },
  { id: "technology-535", title: "Use Facebook Events for a function", category: "technology", text: "Explain how to create a Facebook Event for a family function. Cover adding the date, time, venue, photo and description, inviting guests, and seeing who is coming. Use an example of [a housewarming] in Coimbatore." },
  { id: "technology-536", title: "Save posts to read later on Facebook", category: "technology", text: "Show me how to save a Facebook post, video or link to read later. Explain the save button, finding saved items, organising them into collections, and removing old ones. Give an example of saving [a recipe video]." },
  { id: "technology-537", title: "Watch Facebook videos without data waste", category: "technology", text: "Explain how to reduce data use while watching Facebook videos. Cover turning off autoplay, choosing lower video quality, downloading on Wi-Fi only, and checking data use. Write it for someone on [a 1.5 GB daily plan]." },
  { id: "technology-538", title: "Use Facebook Memories and On This Day", category: "technology", text: "Explain Facebook Memories and how to see posts from past years. Cover opening Memories, sharing an old photo again, and turning off Memories notifications. Give an example for [a birthday photo] from three years ago." },
  { id: "technology-539", title: "Tag friends in a Facebook photo", category: "technology", text: "Show me how to tag friends in a Facebook photo after uploading it. Explain tapping a face, choosing the friend, removing a wrong tag, and who can see tagged photos. Use an example of [a group photo] from a wedding." },
  { id: "technology-540", title: "Check Facebook notifications settings", category: "technology", text: "Explain how to control Facebook notifications so the phone does not buzz all day. Cover turning off likes, comments and group alerts, keeping only important ones, and checking settings. Write it for [a busy parent]." },
  { id: "technology-541", title: "Use Facebook for local news updates", category: "technology", text: "Explain how to follow local news pages on Facebook for my city. Cover searching for trusted pages, following them, checking the source before sharing, and unfollowing pages that spread rumours. Use [your city] as an example." },
  { id: "technology-542", title: "Create a Facebook birthday fundraiser", category: "technology", text: "Explain how to start a simple birthday fundraiser on Facebook for a charity. Cover choosing a charity, setting a small target in rupees, writing why it matters, and sharing it with friends. Use [a local school] as an example." },
  { id: "technology-543", title: "Use Facebook Live for a small event", category: "technology", text: "Show me how to go live on Facebook for a small family event. Explain checking internet and light, starting the live video, reading comments, and ending and saving it. Give an example for [a temple function]." },
  { id: "technology-544", title: "Find a job on Facebook groups", category: "technology", text: "Teach me to look for a part-time job in Facebook groups safely. Cover searching for job groups in my city, reading posts carefully, checking the employer, and never paying for a job. Use [a delivery job] as an example." },
  { id: "technology-545", title: "Delete an old Facebook post", category: "technology", text: "Explain how to delete an old Facebook post I no longer want. Cover finding the post on my timeline, opening its menu, deleting it, and checking it is gone. Also explain hiding a post instead, using [an old photo] as an example." },
  { id: "technology-546", title: "Set up Instagram for the first time", category: "technology", text: "Explain how to create an Instagram account for the first time. Cover choosing a username, adding a phone number or email, setting a password, adding a profile photo, and writing a short bio. Mention privacy choices for [a teenager]." },
  { id: "technology-547", title: "Post a photo on Instagram", category: "technology", text: "Show me how to post a photo on Instagram with a caption and hashtags. Explain choosing the photo, cropping it, adding a filter, writing a caption, and choosing who can see it. Give an example for [a garden photo]." },
  { id: "technology-548", title: "Post a Reel on Instagram", category: "technology", text: "Teach me to make a simple 30-second Reel on Instagram. Cover recording clips, adding music, adding text on screen, choosing a cover photo, and writing a caption. Give an idea for [a cooking Reel]." },
  { id: "technology-549", title: "Use Instagram Stories every day", category: "technology", text: "Explain how to post an Instagram Story that disappears after 24 hours. Cover taking a photo, adding text, stickers and music, choosing close friends only, and seeing who viewed it. Use [a morning walk] as an example." },
  { id: "technology-550", title: "Follow useful accounts on Instagram", category: "technology", text: "Show me how to find and follow useful Instagram accounts for learning and hobbies. Cover searching by topic, checking if an account is genuine, following it, and unfollowing later. Give examples for [cooking] and [gardening]." },
  { id: "technology-551", title: "Send a direct message on Instagram", category: "technology", text: "Explain how to send a direct message on Instagram. Cover opening a chat, sending text, photos and voice notes, replying to a Story, and blocking unwanted messages. Give an example of messaging [a shop] about a price." },
  { id: "technology-552", title: "Use Instagram hashtags wisely", category: "technology", text: "Teach me what hashtags are and how to use them on Instagram. Cover choosing five relevant hashtags, avoiding spammy ones, adding them in the caption or comment, and searching a hashtag. Use [a handmade craft] post as an example." },
  { id: "technology-553", title: "Make an Instagram account private", category: "technology", text: "Explain how to make an Instagram account private and what changes. Cover switching the setting, approving followers, what strangers can still see, and switching back. Suggest it for [a school student] and their parents." },
  { id: "technology-554", title: "Save Instagram posts into collections", category: "technology", text: "Show me how to save Instagram posts into collections for later. Explain saving a post, creating a collection named for a topic, finding saved posts, and removing one. Give examples for [recipes] and [travel places]." },
  { id: "technology-555", title: "Use Instagram for a small business", category: "technology", text: "Explain how a small shop can use Instagram to show products. Cover a business profile, posting clear photos, writing prices, using Stories daily, and replying to messages politely. Give an example for [a jewellery shop]." },
  { id: "technology-556", title: "Write a good Instagram bio", category: "technology", text: "Help me write a short Instagram bio for a home baker. Include what she sells, the city, how to order, and one friendly line, all in under 150 characters. Use placeholders for [city] and [speciality]." },
  { id: "technology-557", title: "Use Instagram Highlights for a shop", category: "technology", text: "Explain Instagram Highlights and how a shop can use them. Cover saving Stories as Highlights, naming them for menu, prices and reviews, adding a cover, and updating them. Give an example for [a cake shop]." },
  { id: "technology-558", title: "Go live on Instagram simply", category: "technology", text: "Show me how to go live on Instagram for the first time. Explain checking light and internet, starting the live video, greeting viewers, answering comments, and ending it. Give an example for [a shop opening]." },
  { id: "technology-559", title: "Block and restrict on Instagram", category: "technology", text: "Explain the difference between blocking and restricting someone on Instagram. Cover what each one does, when to use each, how to undo it, and staying safe from unwanted comments. Use an example of [a rude commenter]." },
  { id: "technology-560", title: "Report a fake Instagram account", category: "technology", text: "Teach me to report a fake Instagram account pretending to be a shop or a friend. Cover opening the profile, choosing report, picking the reason, and warning others. Use an example of [a fake sale account]." },
  { id: "technology-561", title: "Use Instagram Explore to learn", category: "technology", text: "Explain how to use the Instagram Explore page to find learning videos. Cover searching a topic, saving useful Reels, following creators, and avoiding endless scrolling. Give examples for [English learning] and [yoga]." },
  { id: "technology-562", title: "Share an Instagram post to WhatsApp", category: "technology", text: "Show me how to share an Instagram post or Reel to WhatsApp. Explain the share button, copying the link, sending it to a chat, and sharing to Status. Give an example of sharing [a useful recipe Reel] with family." },
  { id: "technology-563", title: "Use Instagram polls and questions", category: "technology", text: "Explain how to add a poll or question sticker to an Instagram Story. Cover writing the question, adding two options, seeing answers, and sharing the results. Give an example for asking followers to choose [a cake flavour]." },
  { id: "technology-564", title: "Reduce screen time on Instagram", category: "technology", text: "Help me set a daily time limit for Instagram and stick to it. Explain the built-in reminder, setting 30 minutes, what happens when time is up, and three simple habits to reduce scrolling. Write it for [a student]." },
  { id: "technology-565", title: "Edit a photo before posting on Instagram", category: "technology", text: "Teach me simple photo edits before posting on Instagram. Cover cropping, brightening, straightening, removing a blurry photo, and using one filter lightly. Give steps for editing [a food photo] on a phone." },
  { id: "technology-566", title: "Use Instagram Close Friends list", category: "technology", text: "Explain the Instagram Close Friends list for sharing personal Stories. Cover adding people, removing someone, posting a Story only to them, and what they see. Give an example for sharing [a family photo] privately." },
  { id: "technology-567", title: "Find local shops on Instagram", category: "technology", text: "Show me how to find local shops and services on Instagram in my city. Cover searching by place and hashtag, checking reviews in comments, messaging for prices, and visiting the shop. Use [a tailor in Salem] as an example." },
  { id: "technology-568", title: "Plan a week of Instagram posts", category: "technology", text: "Help me plan seven Instagram posts for one week for a small vegetable shop. Include one photo, one Reel, one Story idea and one offer post, with a one-line caption idea each. Use placeholders for [shop name] and [vegetables]." },
  { id: "technology-569", title: "Use Instagram captions in Tamil", category: "technology", text: "Explain how to write Instagram captions in Tamil or Tanglish for local followers. Cover typing in Tamil, mixing Tamil and English, adding two hashtags, and keeping it simple. Give three sample captions for [a saree shop]." },
  { id: "technology-570", title: "Understand Instagram likes and comments", category: "technology", text: "Explain likes, comments, shares and saves on Instagram in simple words. Cover what each one means, how to like and comment kindly, and hiding like counts. Write it for [a parent] learning Instagram with their child." },
  { id: "technology-571", title: "Create a YouTube account and channel", category: "technology", text: "Explain how to create a YouTube account and start a simple channel. Cover signing in, choosing a channel name, adding a photo and description, and uploading the first video. Use an example channel about [cooking]." },
  { id: "technology-572", title: "Search YouTube for learning videos", category: "technology", text: "Teach me to search YouTube for good learning videos. Cover typing clear search words, using filters, checking the channel, reading comments carefully, and saving videos to watch later. Give an example for learning [basic English]." },
  { id: "technology-573", title: "Subscribe to a YouTube channel", category: "technology", text: "Explain what subscribing to a YouTube channel means. Cover tapping subscribe, turning on the bell for new videos, managing subscriptions, and unsubscribing. Give examples of channels for [cooking] and [school lessons]." },
  { id: "technology-574", title: "Save YouTube videos to watch later", category: "technology", text: "Show me how to save YouTube videos to Watch Later and make playlists. Explain saving one video, creating a playlist, adding videos to it, and finding it later. Give an example playlist for [exam revision]." },
  { id: "technology-575", title: "Use YouTube Shorts wisely", category: "technology", text: "Explain what YouTube Shorts are and how to watch them without wasting time. Cover swiping through Shorts, liking and saving useful ones, and setting a time limit. Give examples of useful Shorts about [quick recipes]." },
  { id: "technology-576", title: "Upload a video to YouTube", category: "technology", text: "Teach me to upload my first video to YouTube from a phone. Cover choosing the video, writing a title and description, adding a thumbnail, choosing who can watch it, and publishing. Use [a garden tour] video as an example." },
  { id: "technology-577", title: "Write a YouTube video title", category: "technology", text: "Help me write ten clear YouTube video titles for a channel about Indian home cooking. Keep each title short, honest and easy to understand, with no clickbait. Use examples with [dosa], [sambar] and [festival sweets]." },
  { id: "technology-578", title: "Use YouTube for school revision", category: "technology", text: "Explain how a school student can use YouTube for revision. Cover finding lessons by chapter, watching at normal speed, taking notes, solving one question after each video, and avoiding distractions. Use [Class 10 maths] as an example." },
  { id: "technology-579", title: "Control YouTube for children safely", category: "technology", text: "Show me how to make YouTube safer for a young child. Cover the kids app, turning on restricted mode, setting screen time, watching together, and blocking a channel. Write it for a parent of [a 7-year-old]." },
  { id: "technology-580", title: "Download YouTube videos for offline viewing", category: "technology", text: "Explain how to download a YouTube video legally inside the app for offline viewing. Cover the download button, choosing quality, finding downloads later, and deleting old ones. Give an example for watching [a lesson] on a train." },
  { id: "technology-581", title: "Use YouTube history and search history", category: "technology", text: "Teach me to check and clear my YouTube watch history and search history. Cover finding history, deleting one video, pausing history, and clearing all history. Explain why someone might want to do this, using [a shared phone] as an example." },
  { id: "technology-582", title: "Comment on a YouTube video politely", category: "technology", text: "Explain how to write a polite comment on a YouTube video. Cover thanking the creator, asking one clear question, avoiding rude words, and replying to answers. Give an example comment for [a recipe video]." },
  { id: "technology-583", title: "Share a YouTube video on WhatsApp", category: "technology", text: "Show me how to share a YouTube video link on WhatsApp. Explain the share button, choosing WhatsApp, picking a chat, adding one line about the video, and checking the link works. Use [a bhajan video] as an example." },
  { id: "technology-584", title: "Use YouTube captions and subtitles", category: "technology", text: "Explain how to switch on captions and subtitles on YouTube. Cover turning captions on, choosing a language, changing the size, and using captions to learn English. Give an example for watching [a Hindi film song] with English captions." },
  { id: "technology-585", title: "Find trustworthy health videos on YouTube", category: "technology", text: "Teach me to judge whether a health video on YouTube is trustworthy. Cover checking the channel, looking for a doctor or hospital, avoiding miracle cures, and asking a real doctor. Use [a diabetes video] as an example, with general information only." },
  { id: "technology-586", title: "Make a simple YouTube Short", category: "technology", text: "Teach me to record a simple 30-second YouTube Short on my phone. Cover choosing a topic, recording in good light, adding a caption, choosing music, and publishing it. Give an idea for [a one-minute rangoli] Short." },
  { id: "technology-587", title: "Use YouTube Music for bhajans", category: "technology", text: "Explain how to use YouTube Music to listen to bhajans and film songs. Cover searching for a song, making a playlist, downloading for offline listening, and playing in the background. Give an example playlist for [a morning puja]." },
  { id: "technology-588", title: "Reduce data use on YouTube", category: "technology", text: "Show me how to reduce mobile data use while watching YouTube. Cover choosing lower video quality, downloading on Wi-Fi, turning off autoplay, and checking data use in settings. Write it for someone on [a 2 GB daily plan]." },
  { id: "technology-589", title: "Use YouTube for learning a language", category: "technology", text: "Explain how to use YouTube to learn spoken English step by step. Cover finding beginner lessons, repeating sentences aloud, watching with subtitles, and practising ten minutes daily. Give a simple one-week plan for [a beginner]." },
  { id: "technology-590", title: "Report a misleading YouTube video", category: "technology", text: "Teach me to report a misleading or harmful video on YouTube. Cover opening the video menu, choosing report, picking the right reason, and not sharing the video further. Use an example of [a fake money-making video]." },
  { id: "technology-591", title: "Create a YouTube playlist for festivals", category: "technology", text: "Help me create a YouTube playlist of devotional songs for Diwali. Include how to search, add ten songs, order them, name the playlist, and share it with family. Use placeholders for [favourite singer] and [language]." },
  { id: "technology-592", title: "Use YouTube on a smart TV", category: "technology", text: "Explain how to watch YouTube on a smart TV. Cover opening the app, signing in, searching with the remote or phone, playing a video, and signing out. Give an example for watching [a family film song] together." },
  { id: "technology-593", title: "Change YouTube playback speed", category: "technology", text: "Show me how to change the playback speed on a YouTube video. Cover slowing a lesson to 0.75 speed, speeding a long talk to 1.25, and going back to normal. Give an example for learning [a new recipe] slowly." },
  { id: "technology-594", title: "Use YouTube for job interview preparation", category: "technology", text: "Explain how to use YouTube to prepare for a job interview. Cover finding common questions, watching mock interviews, noting good answers, and practising aloud. Give an example for [a bank clerk] interview." },
  { id: "technology-595", title: "Watch YouTube together with family", category: "technology", text: "Help me plan a family YouTube evening with videos everyone enjoys. Include one comedy clip, one song, one learning video and one travel video, with timings. Use placeholders for [family members] and [one hour]." },
  { id: "technology-596", title: "Understand YouTube ads and Premium", category: "technology", text: "Explain YouTube ads and what the paid Premium option offers in simple words. Cover why ads appear, skipping ads, offline downloads, background play, and the monthly cost in rupees. Help me decide if it suits [a daily viewer]." },
  { id: "technology-597", title: "Use YouTube search filters well", category: "technology", text: "Teach me to use YouTube search filters to find the right video fast. Cover filtering by upload date, duration, and relevance, and sorting results. Give examples for finding [a recent news explainer] and [a short yoga video]." },
  { id: "technology-598", title: "Make a channel trailer on YouTube", category: "technology", text: "Help me plan a 30-second trailer for a new YouTube channel about Tamil cooking. Include a warm greeting, what viewers will learn, three video examples, and a subscribe request. Use placeholders for [channel name] and [city]." },
  { id: "technology-599", title: "Use YouTube for cricket match highlights", category: "technology", text: "Explain how to watch cricket match highlights on YouTube. Cover searching for the match, finding the official channel, checking the upload date, and avoiding fake score videos. Give an example for [an India match]." },
  { id: "technology-600", title: "Set a reminder for a YouTube premiere", category: "technology", text: "Show me how to set a reminder for a YouTube live premiere. Cover finding the premiere, tapping notify me, checking the time in Indian time, and joining when it starts. Give an example for [a film trailer] premiere." },
  { id: "technology-601", title: "Use email and WhatsApp together for work", category: "technology", text: "Explain when to use email and when to use WhatsApp at work. Cover formal requests by email, quick updates on WhatsApp, keeping records, and confirming important decisions by email. Give an example for [a shop order]." },
  { id: "technology-602", title: "Share a Facebook post to WhatsApp", category: "technology", text: "Show me how to share a useful Facebook post to WhatsApp. Explain copying the link, pasting it in a chat, adding one line about why it matters, and checking the link opens. Use an example of sharing [a job vacancy] post." },
  { id: "technology-603", title: "Share an Instagram Reel to Facebook", category: "technology", text: "Explain how to share an Instagram Reel to Facebook. Cover the share option, choosing Facebook, writing a short caption, and checking it posted. Give an example for sharing [a shop offer] Reel with more people." },
  { id: "technology-604", title: "Cross-post a festival greeting everywhere", category: "technology", text: "Help me write one festival greeting I can post on WhatsApp Status, Facebook and Instagram. Keep it warm, short and suitable for all three, with a photo idea. Use placeholders for [festival name] and [family name]." },
  { id: "technology-605", title: "Keep one password list for social apps", category: "technology", text: "Explain a safe way to keep track of passwords for WhatsApp, email, Facebook, Instagram and YouTube. Cover using different passwords, writing hints in a notebook kept at home, and never sharing them. Write it for [a beginner]." },
  { id: "technology-606", title: "Check which apps use most data", category: "technology", text: "Show me how to check which social apps use the most mobile data. Cover opening data settings, seeing WhatsApp, Facebook, Instagram and YouTube use, and limiting background data. Write it for someone on [a limited plan]." },
  { id: "technology-607", title: "Use social apps in Tamil language", category: "technology", text: "Explain how to change the language to Tamil in WhatsApp, Facebook, Instagram and YouTube. Cover finding language settings in each app, choosing Tamil, and switching back to English. Write it for [a Tamil-speaking parent]." },
  { id: "technology-608", title: "Take a break from social apps", category: "technology", text: "Help me plan a simple one-week break from Facebook, Instagram and YouTube. Include keeping WhatsApp for family only, muting notifications, filling evenings with reading and walking, and a kind message to friends. Use [one week] as the plan." },
  { id: "technology-609", title: "Spot fake offers on social media", category: "technology", text: "Teach me to spot fake offers and giveaways on Facebook, Instagram and WhatsApp. Cover too-good prices, asking for OTPs, new accounts, and checking the real shop first. Give an example of [a free phone offer]." },
  { id: "technology-610", title: "Share a YouTube video on Facebook", category: "technology", text: "Show me how to share a YouTube video on Facebook. Explain copying the video link, pasting it in a post, writing one line about it, and choosing who can see it. Use an example of sharing [a devotional song] video." },
  { id: "technology-611", title: "Email a photo from WhatsApp", category: "technology", text: "Explain how to email a photo I received on WhatsApp. Cover saving the photo to the phone, opening email, attaching it, writing a short message, and sending it. Give an example of emailing [a certificate photo] to an office." },
  { id: "technology-612", title: "Use WhatsApp Status to announce a shop holiday", category: "technology", text: "Help me write a WhatsApp Status announcing a shop holiday. Include the closed dates, reopening date, a polite line, and an emoji. Keep it short and clear for customers of [a grocery shop]." },
  { id: "technology-613", title: "Write a Facebook post for a lost item", category: "technology", text: "Help me write a Facebook post about a lost wallet in my area. Include what was lost, where, when, a contact number, and a polite request to share. Use placeholders for [area] and [phone number]." },
  { id: "technology-614", title: "Write an Instagram caption for a festival", category: "technology", text: "Help me write three Instagram captions for Pongal photos. Keep each caption warm, short and in simple English, with two hashtags each. Use placeholders for [family name] and [village or city]." },
  { id: "technology-615", title: "Email a YouTube video link to a teacher", category: "technology", text: "Draft a short email to a teacher sharing a YouTube video link for a lesson. Include a subject line, why the video helps, the link, and a thank-you. Use placeholders for [teacher name] and [topic]." },
  { id: "technology-616", title: "Use WhatsApp to collect school fees reminders", category: "technology", text: "Help a small tuition teacher write a polite WhatsApp message reminding parents about monthly fees. Include the amount, due date, payment method, and a thank-you. Use placeholders for [amount] and [due date]." },
  { id: "technology-617", title: "Share a shop location on WhatsApp", category: "technology", text: "Show me how to share my shop location on WhatsApp so customers can find it. Cover sending the live location, sharing a map link, adding landmarks in the message, and checking it opens. Use [a shop in Vellore] as an example." },
  { id: "technology-618", title: "Use Facebook to promote a tuition class", category: "technology", text: "Help me write a Facebook post promoting a maths tuition class for Class 8 students. Include subjects, timings, fees in rupees, location, and a contact number. Use placeholders for [area] and [fees]." },
  { id: "technology-619", title: "Use Instagram to find a recipe video", category: "technology", text: "Explain how to find a good recipe video on Instagram. Cover searching by dish name, checking the creator, saving the Reel, and following the steps carefully. Give an example for finding [a paneer butter masala] Reel." },
  { id: "technology-620", title: "Use YouTube to learn WhatsApp features", category: "technology", text: "Explain how to learn new WhatsApp features from YouTube videos. Cover searching clearly, watching a recent video, following steps slowly, and checking the date. Give an example for learning [how to use Channels]." },
  { id: "technology-621", title: "Send a birthday video on WhatsApp", category: "technology", text: "Help me plan a birthday surprise on WhatsApp for my mother. Include recording a short video wish, adding family photos, choosing a morning time to send it, and adding a voice message. Use placeholders for [her name] and [age]." },
  { id: "technology-622", title: "Write a thank-you post on Facebook", category: "technology", text: "Help me write a thank-you post on Facebook after a successful blood donation camp. Include thanks to donors and volunteers, the number of donors, and a photo idea. Use placeholders for [place] and [number of donors]." },
  { id: "technology-623", title: "Use email to apply for a school admission", category: "technology", text: "Draft an email to a school asking about admission for a child in Class 6. Include the childs name and age, current school, documents available, and a request for the admission process. Use placeholders for [child name] and [school name]." },
  { id: "technology-624", title: "Share a train ticket on WhatsApp", category: "technology", text: "Explain how to share a train ticket PDF received by email on WhatsApp. Cover finding the ticket in email, downloading it, forwarding it to a family chat, and checking everyone can open it. Use [a Chennai to Madurai] ticket as an example." },
  { id: "technology-625", title: "Plan a social media detox Sunday", category: "technology", text: "Help me plan a calm Sunday with no Facebook, Instagram or YouTube. Include a morning walk, cooking with family, reading a book, an evening prayer, and keeping WhatsApp only for urgent calls. Write it for [a family] in a small town." },
  { id: "technology-626", title: "Set up UPI on your phone safely", category: "technology", text: "Explain how to set up UPI on a phone for the first time. Cover choosing a bank account, creating a UPI PIN, and checking the name before the first payment. Use simple steps for a beginner in [your city] who has never paid online before." },
  { id: "technology-627", title: "Send money to a friend by UPI", category: "technology", text: "Show me how to send ₹[amount] to a friend using UPI. Explain how to pick the right contact, check the name on the screen, enter the PIN, and confirm the payment worked. Include what to do if the money is deducted but the payment fails." },
  { id: "technology-628", title: "Receive money through UPI safely", category: "technology", text: "Explain how to receive money through UPI without sharing anything risky. Tell me what details I can safely share, why I never need to enter a PIN to receive money, and how to check that the money has actually reached my bank account." },
  { id: "technology-629", title: "Choose a strong UPI PIN", category: "technology", text: "Help me choose a strong UPI PIN that is easy for me to remember but hard for others to guess. Explain why I should avoid birthdays and simple numbers, how often to change it, and what to do if I forget my PIN." },
  { id: "technology-630", title: "Pay at a shop with a QR code", category: "technology", text: "Explain how to pay at a small shop using a QR code. Cover opening the payment app, scanning the code, checking the shop name and amount, entering the PIN, and showing the success screen to the shopkeeper. Keep it simple for a first-time user in [your city]." },
  { id: "technology-631", title: "Check a QR code before paying", category: "technology", text: "Tell me how to check a QR code carefully before I pay. Explain why the name on the screen must match the shop or person, what to do if the name looks wrong, and why I should never scan a QR code sent by a stranger on WhatsApp." },
  { id: "technology-632", title: "Pay your electricity bill through UPI", category: "technology", text: "Show me how to pay my electricity bill of ₹[amount] using UPI. Explain where to find the bill number, how to check the bill details before paying, and how to save the receipt. Mention what to do if the payment shows as pending." },
  { id: "technology-633", title: "Recharge your mobile with UPI", category: "technology", text: "Explain how to recharge a mobile number with a ₹[amount] plan using UPI. Cover choosing the right plan, checking the number twice, paying safely, and confirming the recharge worked. Add a tip for helping an elderly parent recharge their own phone." },
  { id: "technology-634", title: "Set a daily limit for UPI payments", category: "technology", text: "Help me set a safe daily limit for my UPI payments. Explain where to find the limit setting in a bank app, what limit suits small daily spending, and how a limit protects me if my phone is lost or stolen. Use [amount] as an example." },
  { id: "technology-635", title: "What is an OTP and why it matters", category: "technology", text: "Explain in simple words what an OTP is and why banks send one before a payment. Tell me why I must never share an OTP with anyone, even if the caller says they are from my bank, and what to do if someone asks for it." },
  { id: "technology-636", title: "Act fast after sharing bank details", category: "technology", text: "I shared my bank details with a caller by mistake. Tell me what to do in the next ten minutes: call the bank, block the card, and change passwords. Explain what never to share again and how to report the fraud from [my phone]." },
  { id: "technology-637", title: "Create a strong password for your bank app", category: "technology", text: "Help me create a strong password for my bank app. Explain how to mix letters, numbers and symbols, why I should not reuse my UPI PIN, and how to remember it safely without writing it on my phone cover or in a notebook." },
  { id: "technology-638", title: "Change your bank app password step by step", category: "technology", text: "Show me how to change my bank app password safely. Explain the steps inside the app, how to pick a new password, and when I should change it, such as after using a shared phone or a public computer. Keep the steps simple for a beginner." },
  { id: "technology-639", title: "Lock your phone with a PIN or fingerprint", category: "technology", text: "Explain why locking my phone with a PIN, pattern or fingerprint keeps my money safe. Compare the options in simple words, show how to set one up, and explain why a payment app should also ask for a lock before opening." },
  { id: "technology-640", title: "Check your bank balance on your phone", category: "technology", text: "Show me three safe ways to check my bank balance on my phone: through the bank app, through UPI, and by a missed call to the bank. Explain which one is quickest and warn me never to check my balance on a stranger's phone." },
  { id: "technology-641", title: "Read your bank statement simply", category: "technology", text: "Explain how to read a bank statement in simple words. Tell me what each column means, how to spot a payment I do not recognise, and what to do if I find a wrong entry of ₹[amount] on a [date]. Use an example from a savings account." },
  { id: "technology-642", title: "Add a new payee in your bank app", category: "technology", text: "Show me how to add a new payee in my bank app before sending money. Explain what details I need, such as account number and IFSC, why the bank takes time to activate a payee, and why I should send a small test amount of ₹[amount] first." },
  { id: "technology-643", title: "Send money by NEFT or IMPS safely", category: "technology", text: "Explain the difference between NEFT and IMPS in simple words. Tell me when to use each one, how long each takes, and how to double-check the account number before sending ₹[amount] to [person]. Include what to do if I type a wrong digit." },
  { id: "technology-644", title: "What to do after a failed UPI payment", category: "technology", text: "Explain what to do when a UPI payment fails but money leaves my account. Tell me how long a refund usually takes, where to check the refund status, and when to raise a complaint with the bank. Use a payment of ₹[amount] on [date] as an example." },
  { id: "technology-645", title: "Stop a wrong UPI payment quickly", category: "technology", text: "Tell me what to do if I send money to the wrong person by UPI. Explain why I should contact my bank at once, what details to share, and why getting the money back depends on the other person agreeing. Add tips to avoid this mistake next time." },
  { id: "technology-646", title: "Avoid KYC update fraud calls", category: "technology", text: "Explain the KYC update fraud in simple words. Tell me why real banks never ask for KYC details over a call or a link, how to check if my KYC is really due, and what to do if I get a message saying my account will be blocked today." },
  { id: "technology-647", title: "Recognise a fake refund offer message", category: "technology", text: "Teach me to recognise fake refund messages that promise money back on a cancelled order or a wrong payment. List the warning signs, explain why a refund never needs my UPI PIN, and tell me how to check a real refund in my bank app." },
  { id: "technology-648", title: "Stay safe from lottery and prize scams", category: "technology", text: "Explain how lottery and prize scams work on WhatsApp and SMS. Tell me why a message saying I won ₹[amount] is almost always fake, why winners never pay a fee to claim a prize, and what to do if I already replied to such a message." },
  { id: "technology-649", title: "Avoid job offer payment scams", category: "technology", text: "Help me spot fake job offers that ask for a registration fee or a training deposit. Explain why a real employer never asks for money before joining, list the warning signs in a job message, and tell me how to check if a company is genuine before paying anything." },
  { id: "technology-650", title: "Do not install apps from unknown links", category: "technology", text: "Explain why I should never install an app from a link sent on WhatsApp, SMS or email. Tell me how such apps can steal OTPs and passwords, why I should use only the official app store, and what to do if I already installed one by mistake." },
  { id: "technology-651", title: "Beware of screen sharing app scams", category: "technology", text: "Explain why a stranger asking me to install a screen sharing app is a scam. Tell me how they can see my OTPs and PINs through my screen, what excuse they usually give, and what to do at once if I already shared my screen with someone." },
  { id: "technology-652", title: "Check if a payment link is genuine", category: "technology", text: "Show me how to check a payment link before I tap it. Explain how to look at the web address carefully, why short links hide the real site, and why I should open my bank app myself instead of using a link from an SMS or email." },
  { id: "technology-653", title: "Use two-factor authentication for accounts", category: "technology", text: "Explain two-factor authentication in simple words. Tell me why a password alone is not enough, how a second step like an OTP or fingerprint protects my account, and how to switch it on for my email and bank app. Use [app name] as an example." },
  { id: "technology-654", title: "Keep one password for each important account", category: "technology", text: "Explain why using the same password for email, banking and shopping is risky. Tell me what happens if one site leaks my password, and give me a simple way to create different passwords I can still remember for my [number] main accounts." },
  { id: "technology-655", title: "What to do if your phone is lost", category: "technology", text: "Give me a clear action list for the first hour after losing my phone. Cover blocking the SIM, locking payment apps, informing the bank, and changing passwords from another device. Explain the order to do these steps in and why speed matters." },
  { id: "technology-656", title: "Block your SIM card after theft", category: "technology", text: "Explain how to block a stolen SIM card quickly. Tell me the number to call, what details the telecom company will ask for, and why blocking the SIM stops thieves from receiving my OTPs. Mention how to get a new SIM with the same number." },
  { id: "technology-657", title: "Avoid paying on public Wi-Fi", category: "technology", text: "Explain why I should avoid making payments on free public Wi-Fi at a railway station or mall. Tell me what can go wrong, why mobile data is safer, and what to do if I already made a payment on a public network in [your city]." },
  { id: "technology-658", title: "Update your payment apps regularly", category: "technology", text: "Explain why updating my payment and bank apps matters for safety. Tell me what updates usually fix, how to turn on automatic updates, and why an old app version can be risky. Add a reminder to update my phone software too." },
  { id: "technology-659", title: "Review app permissions on your phone", category: "technology", text: "Show me how to check what permissions my apps have. Explain why a torch app does not need my contacts, how to remove risky permissions, and which permissions a payment app genuinely needs. Use simple steps for an Android phone and an iPhone." },
  { id: "technology-660", title: "Set transaction alerts on your bank account", category: "technology", text: "Explain how to switch on SMS and email alerts for every transaction on my bank account. Tell me why instant alerts help me catch fraud early, what a normal alert looks like, and what to do within minutes if I get an alert for a payment I did not make." },
  { id: "technology-661", title: "Check your UPI transaction history weekly", category: "technology", text: "Help me build a simple weekly habit of checking my UPI transaction history. Tell me what to look for, such as small unknown payments, how to match each entry with a real purchase, and what to do if I find a payment I cannot explain." },
  { id: "technology-662", title: "Pay school fees online without risk", category: "technology", text: "Show me how to pay my child's school fees of ₹[amount] online safely. Explain how to confirm the school's real payment link or UPI ID, why I should avoid links shared in random parent groups, and how to save the receipt for the school office." },
  { id: "technology-663", title: "Book train tickets and pay safely", category: "technology", text: "Explain how to book a train ticket from [station] to [station] and pay safely online. Cover using the official booking app, checking the fare before paying, and keeping the ticket and payment receipt. Warn me about fake booking sites in search results." },
  { id: "technology-664", title: "Pay your shop supplier by UPI", category: "technology", text: "Help a small shop owner in [your city] pay a supplier ₹[amount] by UPI. Explain how to save the supplier as a contact, verify the UPI ID on a call before the first payment, and keep a record of every payment for monthly accounts." },
  { id: "technology-665", title: "Collect payments from customers by QR code", category: "technology", text: "Explain how a small shop owner can print a QR code and collect payments from customers. Cover getting the code from the bank app, placing it at the counter, checking each payment, and what to do if a customer claims they paid but no money arrived." },
  { id: "technology-666", title: "Find a company real helpline number", category: "technology", text: "I need the helpline number for [a bank / a delivery company]. Teach me to find the real number on the official app or website, why numbers from random videos and comments are risky, and how to save the correct number safely on my phone." },
  { id: "technology-667", title: "Report a fraud payment to your bank", category: "technology", text: "Explain how to report a fraud payment to my bank step by step. Tell me the helpline number to call, what details to keep ready, and why reporting within a few hours gives the best chance of getting money back. Use a fraud of ₹[amount] as an example." },
  { id: "technology-668", title: "Report online fraud on the cybercrime portal", category: "technology", text: "Show me how to report an online fraud on the national cybercrime portal in simple steps. Explain what details I need, such as screenshots and transaction numbers, and why I should also inform my bank on the same day." },
  { id: "technology-669", title: "Freeze your bank account in an emergency", category: "technology", text: "Explain when and how to freeze my bank account in an emergency. Tell me the quickest way to do it by phone, app or branch, what happens to my money while it is frozen, and how to unfreeze it later with ID proof." },
  { id: "technology-670", title: "Keep your debit card details private", category: "technology", text: "Explain why I must never share my debit card number, expiry date and CVV with anyone. Tell me what each detail is used for, why a photo of my card is risky, and what to do if I shared my card details with a stranger by mistake." },
  { id: "technology-671", title: "Use your debit card at an ATM safely", category: "technology", text: "Give me safety tips for using an ATM in [your city]. Cover checking for hidden devices on the machine, covering the keypad while entering my PIN, taking my card and receipt, and what to do if the machine keeps my card." },
  { id: "technology-672", title: "Shop online and pay without fear", category: "technology", text: "Explain how to shop online safely on a big shopping site. Cover checking the seller, choosing cash on delivery or UPI, never paying outside the app, and what to do if the product never arrives after I paid ₹[amount]." },
  { id: "technology-673", title: "Avoid fake shopping deals and offers", category: "technology", text: "Help me spot fake shopping deals that look too good to be true. Explain why a branded phone at half price is usually a trap, how to check the real price, and why I should never pay in advance to a seller I found on social media." },
  { id: "technology-674", title: "Pay with cash on delivery wisely", category: "technology", text: "Explain when cash on delivery is a safer choice than paying in advance. Tell me how to check the parcel before paying, what to do if the box looks opened or wrong, and why I should keep the bill for returns." },
  { id: "technology-675", title: "Understand UPI collect requests", category: "technology", text: "Explain what a UPI collect request is in simple words. Tell me why I should never approve a collect request from a stranger, how scammers use it to take money, and what to do if I get a collect request for ₹[amount] from an unknown number." },
  { id: "technology-676", title: "Teach your parents to pay by UPI", category: "technology", text: "Help me teach my parents to pay by UPI safely. Give me a simple lesson plan with five small steps, the most important safety rule to repeat, and a practice idea using a small amount of ₹[amount] at a nearby shop." },
  { id: "technology-677", title: "Help elders avoid payment scams", category: "technology", text: "Give me simple safety rules to teach my elderly parents about phone payments. Cover never sharing OTPs, not trusting urgent calls, and calling me before any big payment. Write it as a short guide I can read aloud to them in [language]." },
  { id: "technology-678", title: "Set up UPI for a family member safely", category: "technology", text: "Explain how to help a family member set up UPI on their own phone and bank account. Tell me why each person must use their own PIN, why I should not keep their PIN, and how to set a low daily limit for a beginner." },
  { id: "technology-679", title: "Link your bank account to UPI correctly", category: "technology", text: "Show me how to link the correct bank account to UPI. Explain what to do if I have two accounts in the same bank, how to pick the default account, and how to check which account a payment will come from before I confirm it." },
  { id: "technology-680", title: "Remove a bank account from UPI", category: "technology", text: "Explain how to remove a bank account from a UPI app when I close the account or change phones. Tell me the steps inside the app and why removing an old account keeps my money safer if someone else uses the phone later." },
  { id: "technology-681", title: "Change your UPI PIN safely", category: "technology", text: "Show me how to change my UPI PIN using my debit card details. Explain each step, why the bank asks for the last digits of my card, and what to do if the PIN change fails twice. Remind me never to share the new PIN with anyone." },
  { id: "technology-682", title: "Reset a forgotten UPI PIN", category: "technology", text: "Explain how to reset a forgotten UPI PIN step by step. Cover what details I need, such as debit card number and expiry date, how the OTP step works, and why I should do this only in my own payment app, never through a link." },
  { id: "technology-683", title: "Check UPI daily limits before a big payment", category: "technology", text: "Explain the daily limit on UPI payments in simple words. Tell me how to check my remaining limit before paying ₹[amount] for [purpose], and what to do if the payment is bigger than the limit, such as splitting it or using another method." },
  { id: "technology-684", title: "Pay house rent through UPI every month", category: "technology", text: "Help me set up a safe monthly routine for paying house rent of ₹[amount] by UPI. Explain how to verify the landlord's UPI ID once, keep a screenshot of each payment, and what to do if a payment fails on the due date." },
  { id: "technology-685", title: "Split a bill with friends using UPI", category: "technology", text: "Show me how to split a restaurant bill of ₹[amount] among [number] friends using UPI. Explain how to calculate each share, collect the money, and keep a simple record so nobody pays twice. Add a tip for splitting regular monthly expenses." },
  { id: "technology-686", title: "Save payment receipts on your phone", category: "technology", text: "Explain how to save UPI and bank payment receipts on my phone in an organised way. Tell me why receipts matter for refunds and disputes, how to take a clear screenshot, and how to store them in a folder by month." },
  { id: "technology-687", title: "Check who sent you money on UPI", category: "technology", text: "Show me how to check the sender's name and details for money I received on UPI. Explain why I should not spend money sent by mistake, and what to do if a stranger sends me ₹[amount] and then asks me to return it." },
  { id: "technology-688", title: "Return money sent to you by mistake", category: "technology", text: "Explain the safe way to return money that someone sent to my account by mistake. Tell me why I should return it only to the same UPI ID, never to a different number the person gives, and how to keep proof of the return payment." },
  { id: "technology-689", title: "Confirm a payment reached my account", category: "technology", text: "A buyer says [he/she] paid me by UPI and sent a screenshot. Explain how to confirm the money reached my own bank account, which SMS or app message proves it, and what to say politely if the money has not arrived yet." },
  { id: "technology-690", title: "Verify a payment before giving goods", category: "technology", text: "Help a small shop owner verify a UPI payment before handing over goods worth ₹[amount]. Explain how to check the bank SMS, the app balance, and the payer's name, and why waiting a few seconds for confirmation is worth it." },
  { id: "technology-691", title: "Use autopay for bills without worry", category: "technology", text: "Explain how autopay works for monthly bills such as mobile, electricity or a loan EMI of ₹[amount]. Tell me how to set it up, how to set a maximum amount, and how to cancel it any time from the bank app." },
  { id: "technology-692", title: "Cancel an autopay or subscription safely", category: "technology", text: "Show me how to cancel an autopay or a monthly subscription I no longer want. Explain where to find active mandates in my bank app, how to stop the next debit, and what to check after cancelling to make sure no money leaves my account." },
  { id: "technology-693", title: "Understand bank charges on your account", category: "technology", text: "Explain common bank charges in simple words, such as SMS charges, ATM charges and minimum balance fees. Tell me how to check them in my statement, how to reduce them, and when to ask the bank about a charge of ₹[amount] I do not understand." },
  { id: "technology-694", title: "Keep your Aadhaar linked details safe", category: "technology", text: "Explain why I should be careful with my Aadhaar number and linked mobile number. Tell me where I should share them, why I must not post them online, and how to lock my Aadhaar biometrics from the official app if I want extra safety." },
  { id: "technology-695", title: "Avoid SIM swap fraud", category: "technology", text: "Explain SIM swap fraud in simple words. Tell me how a thief can get a duplicate SIM, why a sudden loss of network is a warning sign, and what to do at once if my phone shows no signal and I get no OTPs." },
  { id: "technology-696", title: "Check your credit score for free", category: "technology", text: "Explain what a credit score is in simple words and how to check it free from an official source. Tell me why paying EMIs on time improves it, why I should never pay a stranger to fix it, and what to do if the score shows a loan I never took." },
  { id: "technology-697", title: "Protect your email account from hackers", category: "technology", text: "Explain why my email account is the key to my bank accounts. Tell me how to protect it with a strong password and two-factor authentication, and what to do if I get a login alert from a new device or city I do not recognise." },
  { id: "technology-698", title: "Log out of banking apps on shared phones", category: "technology", text: "Explain why I must log out of banking and payment apps after using a shared or borrowed phone. Tell me the steps to log out fully, how to remove a saved login, and what to do if I forgot to log out on someone else's phone." },
  { id: "technology-699", title: "Do not save card details on shopping sites", category: "technology", text: "Explain why I should avoid saving my card details on shopping sites and browsers. Tell me the risks if my account is hacked, how to remove a saved card, and why entering details each time is safer even if it takes a few extra seconds." },
  { id: "technology-700", title: "Use a virtual card for online shopping", category: "technology", text: "Explain what a virtual card is and how it makes online shopping safer. Tell me how to create one in my bank app, why a limit of ₹[amount] is wise, and when to delete it after a purchase from a new website." },
  { id: "technology-701", title: "Check a website is secure before paying", category: "technology", text: "Show me how to check if a website is secure before I pay. Explain the padlock sign, why the address should start with https, and why I should never enter card details on a site that looks copied or has many spelling mistakes." },
  { id: "technology-702", title: "Beware of investment doubling schemes", category: "technology", text: "Explain how investment schemes that promise to double money in a few weeks cheat people. Tell me the warning signs, why no real investment guarantees such returns, and what to do if a friend invites me to join one with ₹[amount]." },
  { id: "technology-703", title: "Avoid part-time job task scams", category: "technology", text: "Help me spot part-time job scams that ask me to like videos or pay a deposit for tasks. Explain how they start with small payments to build trust, then ask for bigger deposits, and what to do if I already paid ₹[amount] to such a group." },
  { id: "technology-704", title: "Spot fake delivery payment messages", category: "technology", text: "Teach me to spot fake messages about a parcel stuck at customs or a delivery needing a small fee. Explain why real delivery companies never ask for payment through a link, and how to check a real parcel status on the official site." },
  { id: "technology-705", title: "Stay safe from fake electricity bill messages", category: "technology", text: "Explain the fake electricity bill scam in simple words. Tell me why a message saying my power will be cut tonight is a trick, how to check my real bill, and what to do if I already called the number in the message." },
  { id: "technology-706", title: "Check your FASTag balance and recharge", category: "technology", text: "Explain how to check a FASTag balance and recharge it by ₹[amount] using UPI. Cover opening the bank app, finding the FASTag section, and confirming the recharge before a road trip from [city] to [city]. Add a tip for low-balance alerts." },
  { id: "technology-707", title: "Pay toll and parking charges by UPI", category: "technology", text: "Show me how to pay toll and parking charges with UPI at a plaza in [your city]. Explain how to scan the code, check the amount before paying, and keep the receipt. Mention what to do if the payment fails but the barrier does not open." },
  { id: "technology-708", title: "Pay for metro and bus travel digitally", category: "technology", text: "Explain how to pay for metro and bus travel in [your city] using UPI or a travel card. Compare buying a single ticket, a travel card and a monthly pass, and tell me which option saves the most money for a daily commuter." },
  { id: "technology-709", title: "Use a bank app to open a fixed deposit", category: "technology", text: "Explain how to open a fixed deposit of ₹[amount] from my bank app. Cover choosing the tenure, checking the interest rate, and understanding when the money matures. Remind me this is general information and I should compare rates before deciding." },
  { id: "technology-710", title: "Check interest on your savings account", category: "technology", text: "Explain in simple words how interest on a savings account works. Tell me how to check the rate in my bank app, when interest is credited, and how a balance of ₹[amount] earns interest over a year. Keep the maths easy to follow." },
  { id: "technology-711", title: "Set up a standing instruction for EMI", category: "technology", text: "Explain how to set up a standing instruction so my loan EMI of ₹[amount] is paid on time every month. Tell me how to check the debit date, keep enough balance, and what happens if the EMI bounces once." },
  { id: "technology-712", title: "Track your monthly spending in a bank app", category: "technology", text: "Show me how to track my monthly spending using my bank app. Explain how to view spending by category, such as food, travel and shopping, and how to spot one habit I can cut to save ₹[amount] next month." },
  { id: "technology-713", title: "Download a mini statement from your bank app", category: "technology", text: "Explain how to download a mini statement from my bank app. Tell me the steps to find it, how to choose the last [number] transactions, and how to share the statement safely without sending it to a stranger." },
  { id: "technology-714", title: "Update your mobile number in the bank", category: "technology", text: "Explain how to update my mobile number linked to my bank account. Tell me why the bank asks me to visit a branch or ATM for this, what ID proof to carry, and why my OTPs will go to the old number until the change is done." },
  { id: "technology-715", title: "Update your address in the bank app", category: "technology", text: "Show me how to update my home address in the bank app after shifting to a new house in [your city]. Explain which proof the bank accepts, how long the change takes, and why my account statements will go to the new address afterwards." },
  { id: "technology-716", title: "Add a nominee to your bank account", category: "technology", text: "Explain what a nominee is and how to add one to my bank account. Tell me why naming a family member helps them access the account later, what details I need, and how to change the nominee if my family situation changes." },
  { id: "technology-717", title: "Understand your bank passbook entries", category: "technology", text: "Explain how to read a bank passbook in simple words. Tell me what common short forms mean, how to match passbook entries with UPI payments, and why updating the passbook once a month helps me catch mistakes early." },
  { id: "technology-718", title: "Use missed call banking safely", category: "technology", text: "Explain how missed call banking works and how to use it safely. Tell me the official number to save, what reply I should expect, and why I must never call back a different number that sends me a balance message." },
  { id: "technology-719", title: "Register for SMS alerts from your bank", category: "technology", text: "Show me how to register for SMS alerts from my bank. Explain what alerts I should switch on, such as debits, credits and login alerts, and why a real bank alert never asks me to click a link or share an OTP." },
  { id: "technology-720", title: "Recognise a real bank SMS from a fake one", category: "technology", text: "Teach me to tell a real bank SMS from a fake one. Explain how real bank messages use a short sender name, never include a link asking for details, and never threaten to block my account. Give two examples, one real and one fake." },
  { id: "technology-721", title: "Avoid clicking links in bank messages", category: "technology", text: "Explain why I should never tap a link in an SMS or email that claims to be from my bank. Tell me what can happen if I do, and show me the safe habit of opening the bank app myself or typing the bank website address by hand." },
  { id: "technology-722", title: "Keep your phone software updated for safety", category: "technology", text: "Explain why keeping my phone software updated protects my money. Tell me how to check for updates, how to install them on Wi-Fi, and why skipping updates for months leaves my payment apps open to new tricks used by fraudsters." },
  { id: "technology-723", title: "Turn on fingerprint lock for payment apps", category: "technology", text: "Show me how to switch on fingerprint or face lock inside my payment app. Explain why this extra lock helps if someone borrows my phone, and what to do if my fingerprint stops working after a cut or a screen guard change." },
  { id: "technology-724", title: "Use a separate PIN for each payment app", category: "technology", text: "Explain why using the same PIN for my phone lock, UPI and bank app is risky. Give me a simple way to create three different PINs I can remember, and explain what to do if I forget one of them." },
  { id: "technology-725", title: "Change passwords after a data leak news", category: "technology", text: "Explain what to do when news says a big website leaked passwords. Tell me how to check if my account was affected, which passwords to change first, and why my bank and email passwords matter more than a shopping site password." },
  { id: "technology-726", title: "Make strong passwords I can remember", category: "technology", text: "Teach me to make strong passwords I can remember without writing them down. Explain a simple method using three random words and a number, why [my birthday] is a bad password, and how to use a different password for banking and email." },
  { id: "technology-727", title: "Log out of accounts on a public computer", category: "technology", text: "Explain why I must log out of email and banking after using a public computer at a cyber cafe or library. Tell me how to log out fully, clear saved passwords, and what to do if I left an account open on a shared computer." },
  { id: "technology-728", title: "Avoid free Wi-Fi for banking", category: "technology", text: "Explain the risks of using free Wi-Fi at a cafe or airport for banking. Tell me how strangers on the same network can try to steal details, why mobile data is safer, and what to check if I already logged in on free Wi-Fi." },
  { id: "technology-729", title: "Check if your UPI ID is being misused", category: "technology", text: "Explain how to check if someone is misusing my UPI ID. Tell me where to see all linked apps and devices, how to remove an unknown device, and what to do if I see a transaction I never made for ₹[amount]." },
  { id: "technology-730", title: "Remove an old phone from your bank app", category: "technology", text: "Show me how to remove an old phone from my bank app after buying a new one. Explain why the old phone can still receive alerts, how to deregister it, and what to do before selling or giving away an old phone." },
  { id: "technology-731", title: "Sell your old phone without leaking data", category: "technology", text: "Give me a checklist for selling my old phone safely. Cover logging out of payment apps, removing the SIM and memory card, doing a factory reset, and checking that no bank app or photo is left on the phone before handing it over." },
  { id: "technology-732", title: "Spot a fake loan app on your phone", category: "technology", text: "Help me spot fake loan apps that promise instant money. Explain the warning signs, such as asking for my contacts and photos, charging a fee before giving a loan, and why I should check if the lender is registered before sharing any document." },
  { id: "technology-733", title: "Avoid sharing documents on WhatsApp", category: "technology", text: "Explain why sharing photos of my PAN card, Aadhaar or bank passbook on WhatsApp is risky. Tell me when it is safe to share a document, how to share it only with a trusted person, and what to do if I sent it to the wrong chat." },
  { id: "technology-734", title: "Verify a seller before paying in advance", category: "technology", text: "Show me how to verify a seller before paying ₹[amount] in advance for [product]. Explain how to check reviews, ask for a shop address, and why paying a small advance is safer than paying the full amount to a stranger." },
  { id: "technology-735", title: "Pay a home tutor or maid digitally", category: "technology", text: "Help me pay my child's tutor or our maid ₹[amount] every month by UPI. Explain how to save their UPI ID, set a monthly reminder, and keep a simple record so both sides can check the payment history any time." },
  { id: "technology-736", title: "Collect society maintenance by UPI", category: "technology", text: "Explain how a housing society secretary can collect monthly maintenance of ₹[amount] from [number] flats using UPI. Cover sharing one QR code, tracking who paid, and sending a gentle reminder to flats that missed the due date." },
  { id: "technology-737", title: "Pay for a temple donation online safely", category: "technology", text: "Show me how to make a temple donation of ₹[amount] online safely. Explain how to use the temple's official website or counter, why I should avoid donation links shared in groups, and how to keep the receipt for my records." },
  { id: "technology-738", title: "Donate to a charity without getting cheated", category: "technology", text: "Help me check a charity before donating ₹[amount] online. Explain how to verify its registration, why I should pay through its official site, and what warning signs show that a donation appeal on social media may be fake." },
  { id: "technology-739", title: "Understand charges for instant money transfer", category: "technology", text: "Explain the charges for instant money transfers in simple words. Tell me which transfers are free, when a bank charges a small fee, and how to check the fee of ₹[amount] before confirming a transfer to [person]." },
  { id: "technology-740", title: "Transfer money to family abroad safely", category: "technology", text: "Explain how to send money to a family member studying abroad. Cover using the bank app or a trusted transfer service, checking the exchange rate and fees, and why I should never use an unknown agent who offers a better rate." },
  { id: "technology-741", title: "Receive money from abroad in your account", category: "technology", text: "Explain how to receive money from a relative abroad in my Indian bank account. Tell me what details I need to share, such as SWIFT code and account number, how long it takes, and what to check if the money is delayed by [number] days." },
  { id: "technology-742", title: "Check foreign exchange rates before paying", category: "technology", text: "Show me how to check the exchange rate before paying for something in dollars or dirhams. Explain why the rate in my bank app may differ from the Google rate, and how a small rate difference changes a payment of ₹[amount]." },
  { id: "technology-743", title: "Use a forex card for a trip abroad", category: "technology", text: "Explain what a forex card is and how to use it on a trip to [country]. Cover loading it with ₹[amount], paying at shops, withdrawing cash, and what to do if the card is lost during the trip. Keep the explanation simple for a first-time traveller." },
  { id: "technology-744", title: "Pay for a flight ticket online safely", category: "technology", text: "Show me how to book a flight from [city] to [city] and pay online safely. Explain how to use the airline site or a known booking app, check the total fare including taxes, and keep the booking reference and payment receipt together." },
  { id: "technology-745", title: "Book a hotel and pay in advance safely", category: "technology", text: "Explain how to book a hotel in [city] and pay in advance without risk. Cover checking the hotel on a known booking site, reading the cancellation rules, and why I should never pay a hotel directly through a link sent on WhatsApp." },
  { id: "technology-746", title: "Cancel a wrong online order payment", category: "technology", text: "Explain how to cancel an online order and get a refund of ₹[amount]. Tell me where to find the cancel button, how long a refund takes, and what to do if the money does not come back within [number] days." },
  { id: "technology-747", title: "Return a product and track your refund", category: "technology", text: "Show me how to return a product I bought online and track the refund. Explain the steps to raise a return, how to pack the item, and how to check the refund status in my bank app after the pickup." },
  { id: "technology-748", title: "Complain about a failed refund", category: "technology", text: "Help me write a short complaint to a shopping site about a refund of ₹[amount] that never arrived. Include the order number, payment date and bank reference, and explain where to send it and how long to wait for a reply." },
  { id: "technology-749", title: "Use UPI Lite for small daily payments", category: "technology", text: "Explain what UPI Lite is and how it helps with small payments like tea or bus fare. Tell me how to add ₹[amount] to the wallet, why it needs no PIN for tiny payments, and what the daily limit is." },
  { id: "technology-750", title: "Pay without internet using UPI", category: "technology", text: "Explain how to pay using UPI when there is no internet, such as with a missed-call or USSD option. Tell me the steps in simple words, the limits of this method, and why it is useful in a village with weak network." },
  { id: "technology-751", title: "Set a reminder for your credit card bill", category: "technology", text: "Help me set up a reminder so I never miss my credit card bill of ₹[amount]. Explain how to check the due date in the bank app, set a phone reminder two days early, and why paying the full amount on time avoids extra charges." },
  { id: "technology-752", title: "Pay your credit card bill through UPI", category: "technology", text: "Show me how to pay my credit card bill of ₹[amount] using UPI. Explain how to find the bill, check the minimum due versus the full amount, and confirm the payment so I do not pay twice by mistake." },
  { id: "technology-753", title: "Understand minimum due on a credit card", category: "technology", text: "Explain what minimum due means on a credit card bill in simple words. Tell me why paying only the minimum still adds interest, how interest grows over months, and why paying the full bill of ₹[amount] is the safer habit." },
  { id: "technology-754", title: "Block a lost credit card at once", category: "technology", text: "Explain how to block a lost credit card immediately from the bank app or helpline. Tell me what details I need, how to check for any payment made after losing it, and how to ask for a replacement card." },
  { id: "technology-755", title: "Check your credit card statement simply", category: "technology", text: "Explain how to read a credit card statement in simple words. Tell me what each section means, how to spot a charge I do not recognise, and what to do if I find a wrong charge of ₹[amount] on [date]." },
  { id: "technology-756", title: "Avoid sharing OTP for card activation", category: "technology", text: "Explain why nobody from a bank will ever ask for an OTP to activate a credit card. Tell me the safe way to activate a new card myself, and what to do if a caller offers to activate it for me over the phone." },
  { id: "technology-757", title: "Spot a fake reward points message", category: "technology", text: "Teach me to spot fake messages about expiring reward points or cashback. Explain why real banks never ask me to click a link to claim points, and how to check my real reward balance inside the bank app." },
  { id: "technology-758", title: "Redeem reward points safely", category: "technology", text: "Show me how to redeem my credit card reward points safely. Explain where to find them in the bank app, what they can buy, and why I should never share an OTP with anyone who offers to redeem them for me." },
  { id: "technology-759", title: "Keep your PAN card details private", category: "technology", text: "Explain why my PAN card number is valuable to fraudsters. Tell me where I genuinely need to share it, such as a bank or tax filing, and why I must never send a photo of it to a stranger who promises a loan or a refund." },
  { id: "technology-760", title: "Link PAN with Aadhaar correctly", category: "technology", text: "Explain how to link my PAN with Aadhaar using the official income tax website. Tell me the steps in simple words, what to check after linking, and why I should never pay a stranger who offers to do it for me." },
  { id: "technology-761", title: "Check your bank account for unknown loans", category: "technology", text: "Explain how to check if a loan was taken in my name without my knowledge. Tell me where to look in my credit report, what to do if I find an unknown loan of ₹[amount], and why I should inform the bank and police at once." },
  { id: "technology-762", title: "Report a stolen identity to the police", category: "technology", text: "Give me a simple guide to reporting identity theft to the police. Explain what details to carry, such as transaction proof and messages, how to file the complaint, and why I should also inform my bank on the same day." },
  { id: "technology-763", title: "Use voice alerts for every payment", category: "technology", text: "Explain how to switch on voice alerts for payments in my UPI app. Tell me why hearing the amount spoken aloud helps a shop owner confirm each payment, and how to set it up in the app settings." },
  { id: "technology-764", title: "Help a shop worker accept digital payments", category: "technology", text: "Help a small shop owner train a worker to accept digital payments. Explain how to check the success screen, match the amount, and what to do if a customer shows a payment screen that looks edited or unclear." },
  { id: "technology-765", title: "Keep a daily record of shop payments", category: "technology", text: "Show a small shop owner in [your city] how to keep a simple daily record of UPI and cash payments. Explain how to note each sale, total the day at closing time, and match the total with the bank balance every evening." },
  { id: "technology-766", title: "Reconcile your shop sales every evening", category: "technology", text: "Explain how a shop owner can match the day's sales with money received. Tell me how to compare the UPI history, cash in the drawer and the sales notebook, and what to do if the totals differ by ₹[amount] at closing time." },
  { id: "technology-767", title: "Pay GST for your small business online", category: "technology", text: "Explain in simple words how a small business owner pays GST online. Tell me where to find the challan, how to pay it through the bank app, and why keeping the payment receipt matters for monthly accounts. This is general information only." },
  { id: "technology-768", title: "Understand a payment gateway charge", category: "technology", text: "Explain what a payment gateway charge is when customers pay my shop online. Tell me how the fee is calculated on a sale of ₹[amount], where to see it in the settlement report, and why the fee differs between UPI and cards." },
  { id: "technology-769", title: "Accept payments on a festival stall", category: "technology", text: "Help a seller at a Diwali fair in [your city] accept digital payments. Explain how to print a QR code, keep the phone charged, check each payment aloud, and handle a failed payment when the network is crowded." },
  { id: "technology-770", title: "Pay your milk and newspaper vendor digitally", category: "technology", text: "Show me how to pay my milk vendor and newspaper vendor ₹[amount] each month by UPI. Explain how to save their UPI IDs, pay on the first of the month, and keep a simple note so I can check the yearly total." },
  { id: "technology-771", title: "Split household expenses with your spouse", category: "technology", text: "Help me split monthly household expenses with my spouse using UPI. Explain how to list shared costs such as groceries, school fees and bills, divide them fairly, and keep one simple record both of us can check." },
  { id: "technology-772", title: "Teach children about digital money", category: "technology", text: "Give me simple ways to teach my [age]-year-old child about digital money. Explain how UPI works in words a child understands, why money on a phone is still real money, and a safe way to practise with a small amount of ₹[amount]." },
  { id: "technology-773", title: "Give pocket money through UPI safely", category: "technology", text: "Explain how to give weekly pocket money of ₹[amount] to my teenager through UPI. Tell me how to set a small limit, check what they spend on, and teach them to keep their PIN secret even from friends." },
  { id: "technology-774", title: "Set spending limits for a teenager", category: "technology", text: "Show me how to set a spending limit on my teenager's payment app. Explain where to find the limit setting, what limit suits a school student, and how to review their spending together every Sunday evening." },
  { id: "technology-775", title: "Talk to children about online scams", category: "technology", text: "Help me explain online scams to my child in simple words. Cover fake game offers, free gift links and strangers asking for money, and give me three short examples I can discuss with a [age]-year-old at home." },
  { id: "technology-776", title: "Check game purchases on your child's phone", category: "technology", text: "Explain how to check if my child bought anything inside a game. Tell me where to see the purchase history, how to switch on purchase approval, and what to do if I find a charge of ₹[amount] I did not approve." },
  { id: "technology-777", title: "Switch on purchase approval for kids", category: "technology", text: "Show me how to switch on purchase approval so my child cannot buy apps or game items without my permission. Explain the steps for an Android phone and an iPhone, and why this one setting can save a surprise bill of ₹[amount]." },
  { id: "technology-778", title: "Avoid fake free recharge offers", category: "technology", text: "Explain how fake free recharge offers work on social media. Tell me why a post promising a free recharge of ₹[amount] is a trap, what details it tries to steal, and what to do if I already clicked such a link." },
  { id: "technology-779", title: "Spot a fake bank app in the store", category: "technology", text: "Teach me how to spot a fake bank app in the app store. Explain how to check the developer name, the number of downloads and reviews, and why I should download the app only from the link on the bank's official website." },
  { id: "technology-780", title: "Download your bank app from the official link", category: "technology", text: "Show me the safe way to download my bank app. Explain how to find the official download link on the bank website, why searching the app store can show fake copies, and how to check the app is genuine after installing it." },
  { id: "technology-781", title: "Check your phone for suspicious apps", category: "technology", text: "Explain how to check my phone for apps I did not install. Tell me where to see the full app list, which apps look suspicious, and how to remove an unknown app safely without losing my photos or contacts." },
  { id: "technology-782", title: "Remove a risky app from your phone", category: "technology", text: "Show me how to remove a risky app from my phone step by step. Explain how to uninstall it, clear its data, and change my passwords afterwards if the app had access to my messages or payment details." },
  { id: "technology-783", title: "Keep your contacts safe from scam calls", category: "technology", text: "Explain why scam apps ask for access to my contacts. Tell me how a fraudster uses my contact list to trick my family, and how to remove contact access from an app that does not need it." },
  { id: "technology-784", title: "Block a fraud number on your phone", category: "technology", text: "Show me how to block a fraud number on my phone and report it as spam. Explain the steps for an Android phone and an iPhone, and why reporting the number helps protect other people from the same scam." },
  { id: "technology-785", title: "Report a scam message to your telecom company", category: "technology", text: "Explain how to report a scam SMS to my telecom company. Tell me how to forward the message to 1909, what details to include, and why reporting helps the company block the sender for everyone." },
  { id: "technology-786", title: "Verify a caller before sharing details", category: "technology", text: "Teach me how to verify a caller who says they are from my bank or a delivery company. Explain why I should hang up and call the official number myself, what questions to ask, and why a real officer will never mind being checked." },
  { id: "technology-787", title: "Never share your PIN over a phone call", category: "technology", text: "Explain in simple words why I must never tell my PIN to anyone over a phone call. Tell me who might ask for it, what excuse they give, and the exact words I can use to refuse politely and end the call safely." },
  { id: "technology-788", title: "What to do if you shared your OTP", category: "technology", text: "Give me an urgent action list for the minutes after sharing my OTP by mistake. Cover calling the bank, freezing the account, and changing passwords. Explain the order of these steps and why every minute matters after an OTP is shared." },
  { id: "technology-789", title: "Change all passwords after a scam", category: "technology", text: "Explain which passwords to change first after falling for a scam. Tell me the order: email, bank app, then shopping apps, and why changing the email password first matters most. Add a tip for choosing new passwords." },
  { id: "technology-790", title: "Check your email for login alerts", category: "technology", text: "Show me how to check my email for login alerts from my bank and other accounts. Explain what a real alert looks like, what to do if I see a login from a city I never visited, and how to sign out of all devices at once." },
  { id: "technology-791", title: "Sign out of all devices from your bank app", category: "technology", text: "Explain how to sign out of all devices from my bank app in one step. Tell me where to find the option, when to use it, such as after losing a phone, and what happens to my saved login on each device afterwards." },
  { id: "technology-792", title: "Use biometric login for your bank app", category: "technology", text: "Explain how biometric login with a fingerprint or face works for a bank app. Tell me its benefits, its limits, and how to switch it on safely. Mention what to do if the phone is shared with family members." },
  { id: "technology-793", title: "Keep your phone locked at all times", category: "technology", text: "Explain why keeping my phone locked even at home protects my money. Tell me how to set a short auto-lock time, why a lock matters if a guest or a child picks up my phone, and how to choose a PIN that is easy to remember." },
  { id: "technology-794", title: "Hide payment app notifications on lock screen", category: "technology", text: "Show me how to hide payment notifications on my lock screen. Explain why an OTP or balance shown on a locked screen is risky, and how to change the setting so only I can see my messages after unlocking the phone." },
  { id: "technology-795", title: "Turn off lock screen message previews", category: "technology", text: "Explain how to turn off message previews on the lock screen. Tell me why hiding the content of bank SMS messages keeps my OTPs private, and give simple steps for an Android phone and an iPhone." },
  { id: "technology-796", title: "Use a second SIM only for banking", category: "technology", text: "Explain the idea of using one SIM only for banking and OTPs. Tell me how keeping banking messages on a separate number reduces scam risks, and what to do if I want to move my bank number to a new SIM." },
  { id: "technology-797", title: "Check your UPI PIN attempts and lockouts", category: "technology", text: "Explain what happens after entering a wrong UPI PIN three times. Tell me why the app locks for safety, how long the lock lasts, and how to unlock it using my debit card details without visiting a branch." },
  { id: "technology-798", title: "Pay your water bill through the bank app", category: "technology", text: "Show me how to pay my water bill of ₹[amount] through the bank app. Explain how to add the water board as a biller, check the bill amount, and save the receipt. Mention what to do if the bill shows a wrong reading." },
  { id: "technology-799", title: "Pay your gas cylinder booking online", category: "technology", text: "Explain how to book a gas cylinder and pay online safely. Cover using the official gas company app, checking the refill price, paying by UPI, and keeping the booking number for the delivery person." },
  { id: "technology-800", title: "Pay broadband and DTH bills by UPI", category: "technology", text: "Show me how to pay my broadband and DTH bills of ₹[amount] each using UPI. Explain how to save both billers, set a monthly reminder, and check the payment status so my connection is never cut by mistake." },
  { id: "technology-801", title: "Set up a monthly budget in your bank app", category: "technology", text: "Help me set up a simple monthly budget in my bank app. Explain how to divide ₹[amount] between food, travel, bills and savings, and how to check at month end whether I stayed within each limit." },
  { id: "technology-802", title: "Save a small amount every week by UPI", category: "technology", text: "Help me build a habit of saving ₹[amount] every week using UPI. Explain how to move the money to a savings account or a separate wallet, set a weekly reminder, and watch the savings grow over [number] months." },
  { id: "technology-803", title: "Move money between your own accounts", category: "technology", text: "Explain how to move money between my own savings and current accounts using UPI or the bank app. Tell me how to pick the right accounts, check the transfer, and keep a note of why I moved ₹[amount] on [date]." },
  { id: "technology-804", title: "Check if a shop accepts UPI before ordering", category: "technology", text: "Show me how to check if a shop or restaurant in [your city] accepts UPI before I order. Explain what to ask on the phone, why carrying a little cash is still wise, and what to do if the shop's QR code does not work." },
  { id: "technology-805", title: "Pay at a petrol pump with UPI", category: "technology", text: "Explain how to pay at a petrol pump with UPI. Tell me how to check the amount on the machine, scan the code safely, and confirm the payment before leaving. Add a tip for checking that no extra charge was added." },
  { id: "technology-806", title: "Pay for medicines at a pharmacy digitally", category: "technology", text: "Show me how to pay for medicines worth ₹[amount] at a pharmacy using UPI. Explain how to check the bill, verify the payment, and keep the bill safe for insurance or tax records. Mention asking for a printed receipt." },
  { id: "technology-807", title: "Pay a doctor consultation fee online", category: "technology", text: "Explain how to pay a doctor's consultation fee of ₹[amount] online before a video consultation. Cover using the hospital app or UPI, checking the doctor's name, and keeping the payment receipt with the appointment details." },
  { id: "technology-808", title: "Book a cab and pay through the app", category: "technology", text: "Show me how to book a cab from [place] to [place] and pay through the app. Explain how to check the fare before the ride, choose UPI as the payment method, and what to do if the driver asks for cash instead." },
  { id: "technology-809", title: "Pay for food delivery safely online", category: "technology", text: "Explain how to order food from a restaurant in [your city] and pay online safely. Cover checking the total bill, paying through the app only, and what to do if the food never arrives after I paid ₹[amount]." },
  { id: "technology-810", title: "Order groceries online and pay on delivery", category: "technology", text: "Show me how to order groceries online and pay on delivery. Explain how to check the items and total, why paying after delivery is safer for a first order, and how to check the bill before handing over ₹[amount]." },
  { id: "technology-811", title: "Avoid fake customer support on social media", category: "technology", text: "Warn me about fake customer support accounts on social media. Explain how scammers reply to complaints with fake helpline numbers, why I should use only the official website, and what to do if I already shared details with a fake account." },
  { id: "technology-812", title: "Check a company before paying a deposit", category: "technology", text: "Show me how to check a company before paying a deposit of ₹[amount] for [service]. Explain how to look for a real address, reviews and registration, and why a company with no address or website is a warning sign." },
  { id: "technology-813", title: "Understand refund timelines for failed payments", category: "technology", text: "Explain how long refunds take for failed UPI, card and net banking payments. Tell me the usual timeline for each method, where to track the refund, and when to raise a complaint if the money is not back in [number] days." },
  { id: "technology-814", title: "Keep proof of every big payment", category: "technology", text: "Explain why keeping proof of every big payment matters. Tell me what to save, such as screenshots, SMS and receipts, how to organise them in a folder, and how proof helped a buyer get a refund of ₹[amount] after a dispute." },
  { id: "technology-815", title: "Share a payment screenshot safely", category: "technology", text: "Show me how to share a payment screenshot safely with a seller. Explain which details to hide, such as my full account number and UPI PIN, and why cropping the image before sending keeps my account safer." },
  { id: "technology-816", title: "Check your bank balance before a big purchase", category: "technology", text: "Explain why checking my balance before a big purchase of ₹[amount] avoids a failed payment and embarrassment. Tell me the quickest way to check, and what to do if the balance is lower than I expected." },
  { id: "technology-817", title: "Plan EMI payments before buying a phone", category: "technology", text: "Help me plan before buying a phone of ₹[amount] on EMI. Explain how to check the monthly EMI, the total interest, and whether my monthly income can handle it comfortably. This is general information, not financial advice." },
  { id: "technology-818", title: "Compare UPI apps before choosing one", category: "technology", text: "Help me compare two UPI apps in simple words. Explain what to compare, such as ease of use, language support, transaction history and safety features, and how to pick the one that suits a beginner in [your city]." },
  { id: "technology-819", title: "Switch to a new UPI app safely", category: "technology", text: "Explain how to switch to a new UPI app without losing my payment history. Tell me how to set it up, link my bank account, and why I should keep the old app until I am sure the new one works well." },
  { id: "technology-820", title: "Keep your transaction history private", category: "technology", text: "Explain why my transaction history is private and worth protecting. Tell me who can see it if I hand over my unlocked phone, and how to lock the payment app so nobody can browse my payments without my permission." },
  { id: "technology-821", title: "Review linked apps in your bank account", category: "technology", text: "Show me how to review which apps are linked to my bank account. Explain where to find the list, how to remove an app I no longer use, and why removing old links keeps my account safer." },
  { id: "technology-822", title: "Understand why a payment needs approval", category: "technology", text: "Explain why some payments ask for an extra approval step, such as an OTP or a fingerprint. Tell me what the bank is checking, why big payments need more checks, and why I should never approve a payment I do not recognise." },
  { id: "technology-823", title: "Stay calm during a payment fraud call", category: "technology", text: "Give me a calm plan for handling a sudden fraud call that says my account will be blocked. Explain why scammers create panic, what to say, why hanging up is the safest reply, and who to call next for real help." },
  { id: "technology-824", title: "Teach a friend to spot payment scams", category: "technology", text: "Help me teach a friend to spot payment scams in simple words. Give me five warning signs to share, one real example of a common scam, and a short message I can forward to my family group on WhatsApp." },
  { id: "technology-825", title: "Build a monthly money safety checklist", category: "technology", text: "Help me build a simple monthly money safety checklist. Include checking my statement, updating one password, reviewing app permissions, and confirming my alerts are on. Make it a short list I can finish in ten minutes every month." },
  { id: "technology-826", title: "Back up all phone photos safely", category: "technology", text: "Explain how to back up all the photos on my [phone model] so I never lose them. Cover free cloud backup, a computer copy and a pen drive copy. Tell me which order to do them in and how to check the backup worked." },
  { id: "technology-827", title: "Save family photos to the cloud", category: "technology", text: "Show me how to save my family photos from [phone model] to free cloud storage step by step. Explain what happens when the free space fills up, how to choose which albums to back up first, and how to view them later." },
  { id: "technology-828", title: "Copy photos to a laptop easily", category: "technology", text: "Tell me the simplest way to copy [number] photos from my phone to my laptop using a cable. Explain how to find the photos folder, select only the good ones, organise them by date, and confirm nothing was missed." },
  { id: "technology-829", title: "Back up photos before changing phones", category: "technology", text: "I am moving from [old phone] to [new phone] next week. Give me a checklist to back up every photo and video first, then move them safely. Include what to check after the move and what to do if some photos are missing." },
  { id: "technology-830", title: "Set up automatic photo backup daily", category: "technology", text: "Help me set up automatic photo backup on my [phone model] so new photos save themselves every day. Explain Wi-Fi only backup, mobile data settings, and how to pause it when I travel. Keep the steps simple for a beginner." },
  { id: "technology-831", title: "Recover deleted photos from backup", category: "technology", text: "I deleted [describe the photos] by mistake yesterday. Explain where deleted photos go first, how long they stay there, and how to restore them from a cloud backup or a computer copy. Tell me what to avoid doing right now." },
  { id: "technology-832", title: "Organise photos into albums by year", category: "technology", text: "My phone has [number] photos in one big list. Show me how to organise them into albums by year and event, such as [event name]. Explain how to name albums clearly, move photos in bulk, and find an old photo quickly later." },
  { id: "technology-833", title: "Share backed up photos with family", category: "technology", text: "I want to share our [festival] photos with my family in [city] without losing quality. Explain the best way to share a backed up album, how to let others add their photos, and how to stop sharing later if needed." },
  { id: "technology-834", title: "Back up WhatsApp photos and videos", category: "technology", text: "My WhatsApp photos take up a lot of space on my [phone model]. Explain how to back up only the important WhatsApp photos, turn off automatic saving for groups, and delete the rest safely after checking the backup." },
  { id: "technology-835", title: "Save photos on a pen drive", category: "technology", text: "Explain how to save my phone photos onto a [size] pen drive using an adapter cable. Tell me which photos to copy first, how to check the copy is complete, and how to label the pen drive so I can find it next year." },
  { id: "technology-836", title: "Back up photos without mobile data", category: "technology", text: "My mobile data is limited, but I need to back up [number] photos this week. Explain how to back up using home Wi-Fi only, a laptop, or a pen drive, and how to check how much data each method uses before I start." },
  { id: "technology-837", title: "Keep original quality photo backups", category: "technology", text: "I want my photo backups to keep full original quality, not smaller copies. Explain the difference between original and storage saver quality, how much space each one needs, and how to change the setting on my [phone model]." },
  { id: "technology-838", title: "Back up old photos from an old phone", category: "technology", text: "My old [phone model] still has photos from [year] but the battery is weak. Give me a safe plan to copy those photos to my new phone or laptop before the old phone stops working. List what I need and the steps in order." },
  { id: "technology-839", title: "Make a second copy of important photos", category: "technology", text: "Explain why one backup is not enough for wedding and baby photos. Help me make a second copy of my [event] photos in a different place, and show me a simple monthly routine to keep both copies updated without much effort." },
  { id: "technology-840", title: "Find photos that did not back up", category: "technology", text: "Some photos on my [phone model] did not back up last night. Help me find which ones are missing, check why the backup stopped, and fix the setting. Explain how to force a backup now and confirm every photo is safe." },
  { id: "technology-841", title: "Back up photos before a factory reset", category: "technology", text: "I need to reset my [phone model] because it keeps freezing. Give me a step by step checklist to back up photos, videos, contacts and messages first. Tell me how to verify each backup before I press reset." },
  { id: "technology-842", title: "Store photos safely for many years", category: "technology", text: "I want to keep my family photos safe for [number] years. Compare cloud storage, an external hard drive and printed albums for long term storage. Recommend a simple plan for a beginner and explain how often to check the copies." },
  { id: "technology-843", title: "Back up photos from a camera memory card", category: "technology", text: "My camera memory card has photos from our [place] trip. Explain how to copy them to my laptop, organise them by day, back them up to the cloud, and safely clear the card for the next trip without losing any photo." },
  { id: "technology-844", title: "Free space by backing up first", category: "technology", text: "My phone says storage is full, but I do not want to delete photos. Explain how to back up the photos first, check the backup is complete, and then safely remove the phone copies to free [number] GB of space." },
  { id: "technology-845", title: "Back up videos without losing quality", category: "technology", text: "My phone has [number] long videos from [event] that I want to keep. Explain how to back them up in full quality, how much space they need, and the best order to upload them on slow home Wi-Fi without stopping halfway." },
  { id: "technology-846", title: "Choose the best photo backup plan", category: "technology", text: "Compare free and paid photo backup options for someone with [number] GB of photos. Explain the monthly cost in ₹, the storage limit, and what happens if I stop paying. Recommend the simplest option for a beginner in India." },
  { id: "technology-847", title: "Back up photos for two family phones", category: "technology", text: "My phone and my [family member] phone both have family photos. Help me set up one shared family backup so photos from both phones go to the same place. Explain who can see them and how to keep private photos separate." },
  { id: "technology-848", title: "Download all backed up photos at once", category: "technology", text: "I want to download all my backed up photos from the cloud to my laptop in one go. Explain how to request the full download, how long it may take for [number] photos, and how to organise the files once they arrive." },
  { id: "technology-849", title: "Back up photos while travelling abroad", category: "technology", text: "I am travelling to [country] for [number] days and will take many photos. Explain how to back them up using hotel Wi-Fi, what to do when Wi-Fi is slow, and how to keep a second copy safe until I return home." },
  { id: "technology-850", title: "Protect backed up photos with a password", category: "technology", text: "Explain how to keep my backed up photos private on my [phone model] and in the cloud. Cover screen lock, backup account password, two step verification, and what to do if I lose my phone while travelling in [city]." },
  { id: "technology-851", title: "Check how much photo storage I use", category: "technology", text: "Show me how to check how much storage my photos and videos use on my [phone model]. Explain what the numbers mean, which albums use the most space, and how to decide what to back up first this weekend." },
  { id: "technology-852", title: "Back up scanned old family photos", category: "technology", text: "I have [number] old printed family photos to scan and back up. Explain how to scan them clearly with a phone, name the files by year, organise them into folders, and back them up so the whole family can see them." },
  { id: "technology-853", title: "Move photos from phone to hard drive", category: "technology", text: "Explain how to move photos from my [phone model] to an external hard drive step by step. Tell me how to connect the drive, copy photos in small batches, check each batch, and safely remove the drive without corrupting any files." },
  { id: "technology-854", title: "Back up photos after a phone repair", category: "technology", text: "My [phone model] is coming back from repair tomorrow. Give me a plan to check which photos are still on it, restore the missing ones from my backup, and set up automatic backup again so this never happens twice." },
  { id: "technology-855", title: "Save only the best photos from bursts", category: "technology", text: "My phone saved [number] burst photos from [event] and most are duplicates. Explain how to pick the best one from each burst, back up only those, and delete the rest safely. Give me a quick routine I can repeat after every function." },
  { id: "technology-856", title: "Back up photos using home Wi-Fi only", category: "technology", text: "Help me change my photo backup settings so uploads happen only on home Wi-Fi, never on mobile data. Explain where the setting is on my [phone model], how to check it worked, and what to do if backup pauses at night." },
  { id: "technology-857", title: "Create a photo backup routine monthly", category: "technology", text: "Make me a simple monthly photo backup routine that takes less than [number] minutes. Include checking cloud backup, copying new photos to my laptop, deleting blurry duplicates, and noting the date I last checked everything." },
  { id: "technology-858", title: "Back up photos from a full memory card", category: "technology", text: "My phone memory card is almost full with photos from [place]. Explain how to back up the card to my laptop and the cloud, then free space on the card safely. Tell me how to check no photo was missed before deleting." },
  { id: "technology-859", title: "Understand cloud backup status messages", category: "technology", text: "My phone shows messages like backup paused, waiting for Wi-Fi and storage full. Explain in simple words what each message means on my [phone model], what causes it, and the exact step to fix each one without losing photos." },
  { id: "technology-860", title: "Back up photos before selling a phone", category: "technology", text: "I plan to sell my [phone model] next week. Give me a checklist to back up all photos and videos, remove them from the phone, sign out of my backup account, and check the buyer cannot recover my old photos later." },
  { id: "technology-861", title: "Save photos in folders by occasion", category: "technology", text: "Show me how to organise backed up photos into folders by occasion, such as Diwali, birthdays and holidays in [city]. Explain a simple naming system, how to move photos between folders, and how to find any folder in under a minute." },
  { id: "technology-862", title: "Back up photos with low phone battery", category: "technology", text: "My phone battery drains fast and I need to back up [number] photos today. Explain how to back up in small batches while charging, which settings save battery during upload, and how to resume safely if the phone switches off." },
  { id: "technology-863", title: "Compare Google Photos and other backups", category: "technology", text: "Compare three common ways to back up phone photos for a beginner in India: cloud backup, laptop copy and external drive. Explain the cost, ease, and risk of each, then recommend the best mix for [number] GB of family photos." },
  { id: "technology-864", title: "Restore photos on a new phone", category: "technology", text: "I just bought a [new phone] and my old photos are backed up in the cloud. Explain how to sign in, restore the photos, check they all arrived, and set the new phone to back up new photos automatically from today." },
  { id: "technology-865", title: "Back up photos for a school project", category: "technology", text: "My child needs photos from [event] for a school project due on [date]. Explain how to back up the photos, pick the clearest ten, share them to a laptop, and keep a copy safe in case the school computer deletes them." },
  { id: "technology-866", title: "Free phone space without deleting memories", category: "technology", text: "My [phone model] has only [number] GB free and I do not want to delete photos. List safe ways to free space first, such as clearing app cache, removing old downloads and backing up photos, in order from easiest to hardest." },
  { id: "technology-867", title: "Find what is using phone storage", category: "technology", text: "Show me how to check what is using storage on my [phone model]. Explain how to read the storage screen, find the biggest apps, photos and videos, and decide what is safe to remove first without losing anything important." },
  { id: "technology-868", title: "Delete duplicate photos safely", category: "technology", text: "My phone has [number] duplicate photos from WhatsApp and bursts. Explain how to find duplicates safely, keep the clearest copy, and delete the rest in bulk. Tell me how to check the backup before deleting anything." },
  { id: "technology-869", title: "Clear app cache to free space", category: "technology", text: "Explain what app cache is in simple words and how clearing it frees space on my [phone model]. Tell me which apps are safe to clear, how to do it step by step, and what will not be deleted, such as photos and chats." },
  { id: "technology-870", title: "Remove old downloaded files and videos", category: "technology", text: "My downloads folder has old videos, PDFs and songs I no longer need. Show me how to sort downloads by size, check each file quickly, keep the useful ones, and delete the rest to free [number] GB on my phone." },
  { id: "technology-871", title: "Delete old WhatsApp media in bulk", category: "technology", text: "WhatsApp groups have filled my [phone model] with old photos and videos. Explain how to see which chats use the most space, back up the important media first, and delete the rest in bulk without losing personal chats." },
  { id: "technology-872", title: "Uninstall unused apps to save space", category: "technology", text: "Help me find apps on my [phone model] that I have not used in [number] months. Explain how to check last used dates, uninstall safely, keep the data if I reinstall later, and free space without affecting my photos or contacts." },
  { id: "technology-873", title: "Move apps and photos to memory card", category: "technology", text: "My phone has a memory card slot but I have never used it. Explain how to move photos and some apps to the memory card on my [phone model], what cannot be moved, and how to check the move worked before deleting the originals." },
  { id: "technology-874", title: "Manage storage when phone is full", category: "technology", text: "My phone shows storage full and I cannot take a new photo at [event]. Give me five quick fixes I can do in ten minutes, in order, to free enough space for photos today without deleting anything I will regret later." },
  { id: "technology-875", title: "Free space by removing offline videos", category: "technology", text: "I downloaded many videos for a train journey to [city] and now my phone is full. Explain how to find downloaded videos in each app, delete the ones I have watched, and keep the unwatched ones until after the trip." },
  { id: "technology-876", title: "Clean junk files from my phone", category: "technology", text: "Explain what junk files are and how to clean them safely on my [phone model] without a cleaner app. Cover temporary files, old thumbnails and leftover app data. Tell me what never to delete and how often to do this cleaning." },
  { id: "technology-877", title: "Reduce photo size before sharing", category: "technology", text: "My photos are too large to send on WhatsApp to my family in [city]. Explain how to reduce photo size on my [phone model] without making them blurry, keep an original backup first, and send the smaller copy quickly." },
  { id: "technology-878", title: "Free space after a system update", category: "technology", text: "After the latest update my [phone model] lost [number] GB of free space. Explain why updates use space, what temporary update files I can safely remove, and how to check my storage again after cleaning up today." },
  { id: "technology-879", title: "Organise files to find space hogs", category: "technology", text: "Show me how to organise my phone files by size on my [phone model]. Explain how to sort by largest first, spot old videos and large PDFs, move useful files to the cloud, and delete the ones I no longer need." },
  { id: "technology-880", title: "Delete old voice notes and recordings", category: "technology", text: "My phone has [number] old voice notes and call recordings taking up space. Explain how to listen quickly, save the important ones to my laptop, and delete the rest in bulk to free space on my [phone model]." },
  { id: "technology-881", title: "Manage storage for a 64 GB phone", category: "technology", text: "My phone has only 64 GB storage and it fills up every month. Give me a practical weekly plan for a [phone model] user: what to back up, what to delete, and what settings to change so the phone stays usable all month." },
  { id: "technology-882", title: "Clear browser data to save space", category: "technology", text: "Explain how clearing browser data frees space on my [phone model]. Tell me what gets deleted, what stays saved, such as passwords, and how to clear only the heavy files while keeping my saved logins safe." },
  { id: "technology-883", title: "Remove large games I no longer play", category: "technology", text: "Two large games use [number] GB on my phone but I have not played them in months. Explain how to check their size, save my game progress if possible, uninstall them safely, and reinstall later without losing my account." },
  { id: "technology-884", title: "Free space using cloud storage smartly", category: "technology", text: "Explain how to use cloud storage to free space on my [phone model] without losing access to my files. Cover uploading photos, removing phone copies after checking, and downloading a file again when I need it in [city]." },
  { id: "technology-885", title: "Stop apps from filling phone storage", category: "technology", text: "Some apps keep downloading photos and videos without asking me. Show me how to stop automatic downloads on my [phone model] for WhatsApp, social apps and browsers, and set a monthly check so storage stays under control." },
  { id: "technology-886", title: "Delete old screenshots in one go", category: "technology", text: "I have [number] old screenshots from train tickets, payments and chats. Explain how to sort screenshots by date, save the few I still need, and delete the rest in bulk to free space quickly on my [phone model]." },
  { id: "technology-887", title: "Check storage before a long trip", category: "technology", text: "I am travelling to [place] for [number] days and need space for photos and offline maps. Give me a checklist to check storage, back up old photos, delete watched videos, and leave at least [number] GB free before I leave." },
  { id: "technology-888", title: "Free space on a phone for kids", category: "technology", text: "My child uses my old [phone model] for games and videos, and storage is always full. Explain how to find the biggest files, remove old game data safely, and set simple rules so the phone does not fill up again next week." },
  { id: "technology-889", title: "Compress videos to save phone space", category: "technology", text: "My phone has long videos from [event] using too much space. Explain how to compress a copy of each video to a smaller size, keep the original backed up on my laptop, and check the smaller copy still looks clear." },
  { id: "technology-890", title: "Remove duplicate files from downloads", category: "technology", text: "I keep downloading the same PDFs and photos twice on my [phone model]. Show me how to find duplicate files, keep the newest copy, delete the older copies safely, and avoid downloading the same file again in future." },
  { id: "technology-891", title: "Use storage analyser to find big files", category: "technology", text: "Explain how to use the built in storage analyser on my [phone model] to find big files. Tell me how to read the chart, open the largest folders, and decide what to move, back up or delete first today." },
  { id: "technology-892", title: "Free space without deleting WhatsApp chats", category: "technology", text: "I need space on my [phone model] but I do not want to lose WhatsApp chats. Explain how to back up chats, delete only the media inside chats, and keep the messages safe. Tell me how to check the backup worked first." },
  { id: "technology-893", title: "Manage photos after a festival week", category: "technology", text: "After Diwali I have [number] new photos and videos and my phone is nearly full. Give me a one hour plan to back up the best photos, delete blurry and duplicate shots, and free at least [number] GB without rushing." },
  { id: "technology-894", title: "Delete old email attachments safely", category: "technology", text: "My email app has downloaded many large attachments on my [phone model]. Explain how to find the biggest attachments, save the important ones to my laptop, and delete the rest from the phone without deleting the emails themselves." },
  { id: "technology-895", title: "Set storage alerts before phone fills up", category: "technology", text: "Help me set up a simple routine so my [phone model] never fills up without warning. Explain how to check storage every Sunday, what number should trigger a cleanup, and which three tasks to do first each time." },
  { id: "technology-896", title: "Move files between phone and laptop", category: "technology", text: "Explain how to move large files, photos and videos between my [phone model] and my laptop without the internet. Cover cable transfer, nearby sharing and a pen drive, and tell me how to check every file arrived safely." },
  { id: "technology-897", title: "Free space by clearing map downloads", category: "technology", text: "I downloaded offline maps for [city] and [place] but no longer need them. Show me how to find offline maps on my [phone model], delete the old ones, keep the one I still use, and free space for photos." },
  { id: "technology-898", title: "Clean up after uninstalling an app", category: "technology", text: "I uninstalled a large app but my [phone model] still shows little free space. Explain why leftover files remain, how to find and remove them safely, and how to check my storage before and after cleaning." },
  { id: "technology-899", title: "Keep only recent photos on phone", category: "technology", text: "Explain how to keep only the last [number] months of photos on my [phone model] while older photos stay backed up in the cloud. Tell me how to view an old photo when needed and how to avoid deleting the cloud copy by mistake." },
  { id: "technology-900", title: "Free space for a new app update", category: "technology", text: "An important app needs [number] GB to update but my phone is full. Give me quick safe steps to free that space in fifteen minutes, without deleting photos, contacts or chats, and then update the app successfully." },
  { id: "technology-901", title: "Sort files by type to free space", category: "technology", text: "Show me how to sort my phone files by type, such as videos, photos, audio and documents, on my [phone model]. Explain which type usually uses the most space and the safest way to reduce each type without losing important files." },
  { id: "technology-902", title: "Delete old podcast episodes and music", category: "technology", text: "My phone is full of old podcast episodes and downloaded songs I have already heard. Explain how to find downloaded audio, delete finished episodes in bulk, and keep only my favourite songs on my [phone model]." },
  { id: "technology-903", title: "Free space on a phone with no card slot", category: "technology", text: "My [phone model] has no memory card slot and storage is full. Explain my best options: cloud backup, laptop transfer, deleting large files, and choosing what to keep. Give me a step by step plan for this weekend." },
  { id: "technology-904", title: "Check which photos use most space", category: "technology", text: "Show me how to find which photos and videos use the most space on my [phone model]. Explain how to sort by size, back up the largest ones first, and decide whether to keep a smaller copy on the phone." },
  { id: "technology-905", title: "Make a storage cleanup checklist", category: "technology", text: "Make me a simple storage cleanup checklist for my [phone model] that I can follow every month. Include backing up photos, clearing cache, deleting downloads, checking WhatsApp media, and noting how much space I freed each time." },
  { id: "technology-906", title: "Free space on a slow phone", category: "technology", text: "My [phone model] is slow because the storage is almost full. Teach me to free space safely: find big videos and old downloads, move photos to [a memory card or cloud backup], and delete apps I never use. Tell me how much space to keep free." },
  { id: "technology-907", title: "Speed up an old Android phone", category: "technology", text: "My [number] year old phone is slow when I open WhatsApp and the camera. Explain safe ways to speed it up, such as removing unused apps, reducing animations and clearing storage, without a factory reset or spending money." },
  { id: "technology-908", title: "Stop phone lagging while typing", category: "technology", text: "My keyboard lags when I type messages on my [phone model]. Help me find the cause, such as a full keyboard cache, too many apps running, or low storage. Give me step by step fixes from easiest to hardest." },
  { id: "technology-909", title: "Fix slow app opening times", category: "technology", text: "Apps on my [phone model] take [number] seconds to open. Explain how to check if the problem is storage, RAM, or an old app version. Give me clear steps to fix each cause and test whether the app opens faster." },
  { id: "technology-910", title: "Restart phone safely to fix slowness", category: "technology", text: "Explain when restarting my [phone model] helps and when it does not. Tell me the safe way to restart, what to close first, how often to restart each week, and what to check after the phone switches back on." },
  { id: "technology-911", title: "Close background apps that slow phone", category: "technology", text: "Show me how to see which apps are running in the background on my [phone model] and slowing it down. Explain which ones are safe to close, which ones to leave alone, and how to stop an app from restarting itself." },
  { id: "technology-912", title: "Reduce animations to speed up phone", category: "technology", text: "Explain how reducing screen animations can make my old [phone model] feel faster. Tell me where to find the setting safely, what to change, what will look different, and how to turn it back if I do not like it." },
  { id: "technology-913", title: "Fix a phone that freezes often", category: "technology", text: "My [phone model] freezes for a few seconds several times a day. Help me find the likely cause, such as low storage, a faulty app or overheating. Give me safe checks to try at home before visiting a repair shop." },
  { id: "technology-914", title: "Speed up phone after software update", category: "technology", text: "My phone became slow after the latest software update on my [phone model]. Explain why this can happen, what safe steps to try first, such as clearing cache and restarting, and when to wait a few days before worrying." },
  { id: "technology-915", title: "Fix slow camera opening on phone", category: "technology", text: "My camera takes [number] seconds to open and I miss photos at family functions. Help me fix the slow camera on my [phone model] by clearing camera cache, freeing storage and checking settings, without deleting any photos." },
  { id: "technology-916", title: "Stop phone heating and slowing down", category: "technology", text: "My [phone model] gets hot and slow when I use maps in [city] in summer. Explain why heat slows a phone, how to cool it safely, what to avoid doing, and which settings reduce heat during long journeys." },
  { id: "technology-917", title: "Fix lag during video calls", category: "technology", text: "Video calls on my [phone model] lag and the voice breaks up. Help me check if the cause is slow internet, low storage or too many apps running. Give me step by step fixes I can try before my next call at [time]." },
  { id: "technology-918", title: "Speed up phone by updating apps", category: "technology", text: "Explain how old app versions can slow down my [phone model]. Show me how to check for updates, update only the important apps on Wi-Fi, and check if the phone feels faster after updating each one." },
  { id: "technology-919", title: "Fix slow scrolling in social apps", category: "technology", text: "Scrolling through photos and videos feels jerky on my [phone model]. Help me fix it by clearing the app cache, checking storage, and reducing video quality settings. Tell me how to test if scrolling is smooth again." },
  { id: "technology-920", title: "Manage RAM on a budget phone", category: "technology", text: "My budget phone has only [number] GB RAM and apps keep closing by themselves. Explain in simple words what RAM means, how to see which apps use the most, and how to keep only essential apps running each day." },
  { id: "technology-921", title: "Fix a phone slow after installing apps", category: "technology", text: "My phone slowed down after I installed [number] new apps last week. Help me find which new app is causing the problem, test by removing one at a time, and keep the useful apps without slowing the phone again." },
  { id: "technology-922", title: "Speed up phone for elderly parents", category: "technology", text: "My parents find their [phone model] very slow and confusing. Give me a simple setup to speed it up: remove extra apps, increase text size, turn off animations, and keep only WhatsApp, calls and photos on the home screen." },
  { id: "technology-923", title: "Fix slow charging and slow phone", category: "technology", text: "My [phone model] charges slowly and also runs slowly. Help me check if the charger, cable, charging port or too many background apps are the cause. Give me safe home checks before I buy a new charger in [city]." },
  { id: "technology-924", title: "Clear cache to fix a slow app", category: "technology", text: "One app on my [phone model] is very slow but other apps are fine. Explain how to clear only that app cache, what will happen to my login and saved data, and how to check if the app runs faster afterwards." },
  { id: "technology-925", title: "Decide when to reset a slow phone", category: "technology", text: "I have tried restarting and clearing space, but my [phone model] is still slow. Explain when a factory reset is worth trying, what to back up first, the exact steps, and what to set up again after the reset." },
  { id: "technology-926", title: "Fix phone freezing during games", category: "technology", text: "My phone freezes when I play games on my [phone model]. Help me check storage, close background apps, lower game graphics, and cool the phone safely. Tell me when freezing means I should stop playing and let it rest." },
  { id: "technology-927", title: "Speed up phone without deleting apps", category: "technology", text: "I do not want to delete any apps, but my [phone model] is slow. Give me other ways to speed it up, such as clearing cache, removing old files, updating software and restarting regularly. List them from easiest to hardest." },
  { id: "technology-928", title: "Fix slow fingerprint unlock on phone", category: "technology", text: "My fingerprint unlock is slow and often fails on my [phone model]. Explain how to clean the sensor, re-add my fingerprint, and check if a screen guard is causing the problem. Tell me when to use a PIN instead." },
  { id: "technology-929", title: "Improve phone speed on low battery", category: "technology", text: "My phone slows down a lot when battery saver turns on. Explain why battery saver limits speed, which settings I can adjust safely, and how to balance battery life with usable speed on my [phone model] during a long day." },
  { id: "technology-930", title: "Fix a phone that restarts by itself", category: "technology", text: "My [phone model] restarts by itself two or three times a day. Help me check for a faulty app, low storage, overheating or a software problem. Give me safe home checks and tell me when to visit a repair shop in [city]." },
  { id: "technology-931", title: "Speed up WhatsApp on a slow phone", category: "technology", text: "WhatsApp is very slow to open and send photos on my [phone model]. Explain how to clear WhatsApp cache, manage media storage, update the app, and check my internet speed, without deleting any chats or important photos." },
  { id: "technology-932", title: "Fix slow internet on a fast phone", category: "technology", text: "My phone is new but the internet feels slow in my home in [city]. Help me check Wi-Fi signal, mobile data, background downloads and browser cache. Give me step by step tests to find whether the phone or the network is slow." },
  { id: "technology-933", title: "Reduce widgets to speed up phone", category: "technology", text: "My home screen has many widgets and my [phone model] feels slow. Explain what widgets do, how they use battery and memory, which ones to remove first, and how to keep only the useful ones for weather and calendar." },
  { id: "technology-934", title: "Fix a phone slow in the morning", category: "technology", text: "My [phone model] is very slow for the first ten minutes every morning. Help me find the cause, such as overnight updates, backup running, or too many alarms and apps starting together. Give me simple fixes to try tonight." },
  { id: "technology-935", title: "Speed up an old phone for school", category: "technology", text: "My child uses an old [phone model] for school work and it is too slow for video classes. Give me a safe plan to speed it up, keep only school apps, free storage, and make video calls work better on home Wi-Fi." },
  { id: "technology-936", title: "Check phone health before blaming apps", category: "technology", text: "Before I blame my apps, help me check the overall health of my [phone model]. Explain how to check storage, battery health, software version and temperature in simple words, and what each number means for speed." },
  { id: "technology-937", title: "Fix slow photo gallery loading", category: "technology", text: "My photo gallery takes [number] seconds to load on my [phone model]. Help me fix it by checking how many photos I have, clearing gallery cache, and turning off cloud sync preview if needed, without deleting any photo." },
  { id: "technology-938", title: "Stop auto updates slowing my phone", category: "technology", text: "Apps update by themselves and slow my [phone model] at the wrong time. Show me how to change update settings to Wi-Fi only and night time, update apps manually when I choose, and keep important apps like WhatsApp always updated." },
  { id: "technology-939", title: "Fix lag when switching between apps", category: "technology", text: "Switching between WhatsApp, camera and maps is very slow on my [phone model]. Help me check RAM, close heavy apps, and change settings so switching feels faster. Tell me how to test the fix with three apps I use daily." },
  { id: "technology-940", title: "Speed up phone by removing live wallpaper", category: "technology", text: "I use a live wallpaper and my [phone model] feels slow and the battery drains fast. Explain how live wallpapers affect speed, how to change to a simple still wallpaper, and how to check if the phone feels faster afterwards." },
  { id: "technology-941", title: "Fix a phone that hangs on startup", category: "technology", text: "My [phone model] hangs on the logo screen for a long time when I switch it on. Explain what may cause this, safe steps to try such as charging fully and restarting, and when I must take it to a repair shop." },
  { id: "technology-942", title: "Improve speed by organising home screen", category: "technology", text: "My home screen is full of apps and folders and my [phone model] feels slow. Show me how to organise apps into a few folders, remove shortcuts I never use, and keep the home screen simple so the phone opens apps faster." },
  { id: "technology-943", title: "Fix slow notifications on my phone", category: "technology", text: "Notifications arrive late on my [phone model], especially WhatsApp messages. Help me check battery saver settings, background data, and app notification settings step by step so important messages from [person] arrive on time." },
  { id: "technology-944", title: "Speed up phone after dropping it", category: "technology", text: "I dropped my [phone model] yesterday and now it feels slow, though the screen looks fine. Explain what to check at home, such as storage, apps and overheating, and what signs mean I should get it checked by a technician soon." },
  { id: "technology-945", title: "Make a slow phone usable for a month", category: "technology", text: "I cannot buy a new phone for a month, but my [phone model] is very slow. Give me a practical plan to keep it usable: essential apps only, daily restart, weekly cleanup, and settings that save battery and speed until I replace it." },
  { id: "technology-946", title: "Fix app keeps crashing on phone", category: "technology", text: "My [app name] app crashes every time I open it on my [phone model]. Give me fixes in order: restart the phone, clear cache, update the app, and reinstall it safely. Tell me how to save my data before reinstalling." },
  { id: "technology-947", title: "Fix Wi-Fi connected but no internet", category: "technology", text: "My [phone model] shows Wi-Fi connected but the internet does not work at home in [city]. Help me check the router, forget and reconnect to Wi-Fi, restart both devices, and test with another phone to find the real cause." },
  { id: "technology-948", title: "Fix mobile data not working error", category: "technology", text: "Mobile data is on but nothing loads on my [phone model]. Explain how to check data balance, APN settings, aeroplane mode, and SIM card seating in simple steps. Tell me when to call my mobile company for help." },
  { id: "technology-949", title: "Fix phone cannot download apps error", category: "technology", text: "I cannot download a new app on my [phone model] and I see an error message. Help me check storage, internet, app store account and pending downloads. Give me step by step fixes and tell me what the error code means." },
  { id: "technology-950", title: "Fix WhatsApp messages not sending", category: "technology", text: "My WhatsApp messages stay on one tick on my [phone model]. Explain what one tick means, how to check internet, restart the app, and check if the other person blocked me or has no internet. Give me the checks in order." },
  { id: "technology-951", title: "Fix phone storage full warning error", category: "technology", text: "My [phone model] keeps showing a storage full warning even after I deleted photos. Explain why the warning stays, where hidden files hide, and how to check real free space and free more space safely today." },
  { id: "technology-952", title: "Fix camera app not opening error", category: "technology", text: "My camera app will not open on my [phone model] and shows an error. Help me try restarting the phone, clearing camera cache, freeing storage, and checking if another app is using the camera. Tell me when it needs repair." },
  { id: "technology-953", title: "Fix Bluetooth not connecting to earphones", category: "technology", text: "My Bluetooth earphones will not connect to my [phone model]. Explain how to turn Bluetooth off and on, forget the device, pair it again, check battery, and test with another phone to find if the earphones or phone is faulty." },
  { id: "technology-954", title: "Fix phone not charging properly", category: "technology", text: "My [phone model] charges very slowly or stops at [number] percent. Help me check the cable, charger, charging port for dust, and battery settings. Tell me what is safe to clean at home and when to replace the cable." },
  { id: "technology-955", title: "Fix SIM card not detected error", category: "technology", text: "My phone shows no SIM card on my [phone model]. Explain how to restart the phone, remove and reinsert the SIM tray safely, clean the SIM gently, and test the SIM in another phone before visiting the shop in [city]." },
  { id: "technology-956", title: "Fix phone screen touch not responding", category: "technology", text: "Part of my phone screen does not respond to touch on my [phone model]. Help me check if a screen guard, water, or a software freeze is the cause. Give me safe home tests and tell me when the screen needs professional repair." },
  { id: "technology-957", title: "Fix no sound on phone calls", category: "technology", text: "I cannot hear the other person on calls on my [phone model], but speaker mode works. Explain how to check volume, earpiece dust, Bluetooth connections and call settings step by step, and when the earpiece may need cleaning or repair." },
  { id: "technology-958", title: "Fix app update stuck on pending", category: "technology", text: "An app update is stuck on pending for [number] hours on my [phone model]. Help me check Wi-Fi, storage, paused downloads and app store settings. Give me clear steps to restart the update without losing the app data." },
  { id: "technology-959", title: "Fix phone cannot send SMS messages", category: "technology", text: "I cannot send SMS messages from my [phone model], though calls work. Explain how to check message centre settings, balance, network signal and blocked numbers in simple steps. Tell me when to contact my mobile company in [city]." },
  { id: "technology-960", title: "Fix gallery photos not showing up", category: "technology", text: "Some photos I took yesterday do not show in my gallery on my [phone model]. Help me check the correct folder, hidden albums, cloud backup and memory card. Explain how to find the missing photos without deleting anything." },
  { id: "technology-961", title: "Fix phone overheating warning message", category: "technology", text: "My [phone model] shows an overheating warning and switches off apps. Explain why phones overheat in Indian summer, how to cool it safely, what to avoid, such as putting it in a fridge, and when overheating means a battery problem." },
  { id: "technology-962", title: "Fix video not playing on phone", category: "technology", text: "A video sent on WhatsApp will not play on my [phone model]. Help me check if the file downloaded fully, the app needs an update, or storage is full. Give me step by step fixes and a way to watch it on my laptop instead." },
  { id: "technology-963", title: "Fix phone cannot connect to laptop", category: "technology", text: "My laptop does not recognise my [phone model] when I connect it with a cable. Explain how to check the cable, USB mode, drivers and phone permissions step by step, and how to transfer photos another way if it still fails." },
  { id: "technology-964", title: "Fix forgotten phone lock pattern", category: "technology", text: "I forgot my phone lock pattern on my [phone model] and cannot open it. Explain the safe recovery options, what data I might lose, and how to avoid losing photos by using my backup account. Warn me about fake unlock apps." },
  { id: "technology-965", title: "Fix email app not syncing messages", category: "technology", text: "My email app has not received new messages since [date] on my [phone model]. Help me check internet, sync settings, storage and account password step by step, and test by sending myself a test email from another account." },
  { id: "technology-966", title: "Fix phone battery draining overnight", category: "technology", text: "My [phone model] loses [number] percent battery overnight without use. Help me find which app is draining battery, check background settings, and turn off the culprit safely. Tell me how to test the fix for one night." },
  { id: "technology-967", title: "Fix GPS location not working accurately", category: "technology", text: "Maps shows my location wrong by [number] metres in [city]. Explain how to turn on high accuracy location, check permissions, restart location services, and test outdoors. Tell me when a weak signal is normal in a building." },
  { id: "technology-968", title: "Fix phone calls dropping frequently", category: "technology", text: "My calls drop after a few minutes on my [phone model] in [area]. Help me check signal strength, SIM seating, network settings and whether others face the same problem. Tell me when to report it to my mobile company." },
  { id: "technology-969", title: "Fix file cannot open on phone", category: "technology", text: "I received a [file type] file on WhatsApp but my [phone model] says it cannot open it. Explain what the file type means, which free app can open it safely, and how to check the file is not fake or harmful before opening." },
  { id: "technology-970", title: "Fix phone time and date wrong", category: "technology", text: "My [phone model] shows the wrong time and date, and WhatsApp messages look out of order. Explain how to set automatic time, check time zone for India, restart the phone, and confirm the time is correct afterwards." },
  { id: "technology-971", title: "Fix microphone not working on calls", category: "technology", text: "People cannot hear me on calls on my [phone model], but I can hear them. Help me check microphone permissions, dust in the microphone hole, Bluetooth earphones and a voice recording test to find the cause safely at home." },
  { id: "technology-972", title: "Fix app asking for storage permission repeatedly", category: "technology", text: "One app keeps asking for storage permission every time I open it on my [phone model]. Explain why this happens, how to set the permission correctly, and when refusing permission is safer for my photos and files." },
  { id: "technology-973", title: "Fix phone cannot install a software update", category: "technology", text: "A software update fails to install on my [phone model] with an error. Help me check storage, battery level, Wi-Fi and update size. Give me safe steps to retry the update and tell me when to skip it for now." },
  { id: "technology-974", title: "Fix contacts missing after phone update", category: "technology", text: "After updating my [phone model], some contacts are missing. Explain where contacts may have moved, how to check cloud sync, SIM contacts and other accounts, and how to restore them from a backup without creating duplicates." },
  { id: "technology-975", title: "Understand common phone error messages", category: "technology", text: "Explain ten common phone error messages in simple words for a beginner using a [phone model] in India. For each one, say what it means, whether it is serious, and the first safe step to try before worrying or visiting a shop." },
  { id: "technology-976", title: "Fix a phone that will not switch on", category: "technology", text: "My [phone model] will not switch on after the battery died. Give me safe steps in order: charge with the original charger, wait [number] minutes, try a forced restart, and check for signs of life. Tell me when to seek repair help." },
  { id: "technology-977", title: "Fix a phone stuck in a boot loop", category: "technology", text: "My [phone model] keeps restarting and never reaches the home screen. Explain what a boot loop means in simple words, safe home checks to try, what data I might lose, and when I must take it to a technician in [city]." },
  { id: "technology-978", title: "Fix SD card not recognised by phone", category: "technology", text: "My phone no longer recognises my memory card with [number] photos on it. Help me check the card in another phone, back up the photos first if possible, and decide whether to format the card or replace it safely." },
  { id: "technology-979", title: "Fix a cracked screen that still works", category: "technology", text: "My [phone model] screen cracked after a fall in [city] but touch still works. Explain what to do now, how to back up photos first, whether a screen guard helps, and how to decide between repair now or later." },
  { id: "technology-980", title: "Fix water damaged phone safely", category: "technology", text: "My [phone model] fell in water today. Give me urgent safe steps: switch it off, do not charge it, dry the outside gently, and remove the SIM tray. Tell me what never to do and when to take it to a repair shop." },
  { id: "technology-981", title: "Decide when to repair a phone screen", category: "technology", text: "My phone screen has a small crack but works fine. Help me decide whether to repair it now or wait. Compare repair cost in ₹, risk of further damage, and how long I plan to keep my [phone model] for [number] more months." },
  { id: "technology-982", title: "Decide when to replace a phone battery", category: "technology", text: "My [number] year old phone battery drains in half a day. Explain the signs that a battery needs replacing, how to check battery health, the usual cost in ₹ in India, and whether replacing it is better than buying a new phone." },
  { id: "technology-983", title: "Choose a trustworthy phone repair shop", category: "technology", text: "Help me choose a trustworthy phone repair shop in [city] for my [phone model]. Explain what to ask before handing over the phone, how to check prices, what a bill should show, and how to protect my photos and passwords first." },
  { id: "technology-984", title: "Prepare a phone before giving for repair", category: "technology", text: "I am giving my [phone model] for repair tomorrow. Give me a checklist to back up photos and contacts, remove passwords and bank apps, note the phone condition, and take a photo of the phone before handing it over." },
  { id: "technology-985", title: "Check phone after repair at shop", category: "technology", text: "I just got my [phone model] back from repair. Give me a checklist to check before I leave the shop: screen touch, camera, calls, charging, speakers and my photos. Tell me what to do if something still does not work." },
  { id: "technology-986", title: "Decide repair or buy a new phone", category: "technology", text: "My [phone model] needs a repair costing ₹[amount]. Help me decide whether to repair it or buy a new phone. Compare repair cost, phone age, battery health, and what I use the phone for daily, then give a clear recommendation." },
  { id: "technology-987", title: "Understand phone warranty before repair", category: "technology", text: "Explain phone warranty in simple words for my [phone model] bought in [month]. Tell me what warranty covers, what it does not cover, such as screen cracks and water damage, and how to check if my phone is still under warranty." },
  { id: "technology-988", title: "Fix a swollen phone battery safely", category: "technology", text: "The back of my [phone model] looks slightly swollen and the battery may be damaged. Explain why this is urgent, what never to do, such as charging or pressing it, and how to take it safely to a repair shop in [city] today." },
  { id: "technology-989", title: "Repair a phone charging port problem", category: "technology", text: "My [phone model] only charges when I hold the cable at an angle. Explain what may be wrong with the charging port, safe home checks such as trying another cable, what never to poke inside, and the usual repair cost in ₹." },
  { id: "technology-990", title: "Fix a phone speaker with low sound", category: "technology", text: "My phone speaker sounds very low on my [phone model]. Help me check volume settings, dust in the speaker, Bluetooth connections and a test call. Tell me when cleaning helps and when the speaker needs professional repair." },
  { id: "technology-991", title: "Decide when a slow phone needs repair", category: "technology", text: "My [phone model] is slow even after cleanup and reset. Help me decide if it needs a hardware repair, a battery change, or just replacement. List the warning signs for each case and the questions to ask a technician in [city]." },
  { id: "technology-992", title: "Get a repair estimate before agreeing", category: "technology", text: "Explain how to get a clear repair estimate for my [phone model] in [city] before agreeing to any work. Tell me what the estimate should include, how to compare two shops, and what to do if the final bill is higher than quoted." },
  { id: "technology-993", title: "Fix a phone with a faulty power button", category: "technology", text: "The power button on my [phone model] does not work properly. Explain temporary ways to switch the phone on and off, such as scheduled power and double tap, and how to decide if the button repair is worth the cost in ₹." },
  { id: "technology-994", title: "Protect data when phone is repaired", category: "technology", text: "Explain how to protect my photos, chats and bank details before a stranger repairs my [phone model]. Cover backup, signing out, removing SIM and memory card, and what to check when I get the phone back in [city]." },
  { id: "technology-995", title: "Fix a phone camera with blurry photos", category: "technology", text: "My phone camera takes blurry photos on my [phone model] even in daylight. Help me check lens dirt, focus settings, a faulty screen guard and software updates step by step, and tell me when the camera needs repair." },
  { id: "technology-996", title: "Decide original or duplicate phone parts", category: "technology", text: "A repair shop offered original and duplicate parts for my [phone model] screen at different prices in ₹. Explain the difference in simple words, the risks of duplicate parts, and how to decide which one suits my budget and usage." },
  { id: "technology-997", title: "Fix a phone that overheats during charging", category: "technology", text: "My [phone model] gets very hot while charging. Explain what is normal warmth and what is dangerous heat, safe steps such as using the original charger and removing the case, and when to stop charging and visit a repair shop." },
  { id: "technology-998", title: "Check a second hand phone before buying", category: "technology", text: "I want to buy a second hand [phone model] in [city] for ₹[amount]. Give me a checklist to test before paying: screen, touch, camera, battery, calls, charging, storage and whether the phone is stolen or still locked to someone else." },
  { id: "technology-999", title: "Fix a phone with no network signal", category: "technology", text: "My [phone model] shows no network signal at home, but my family phones work fine. Help me check aeroplane mode, SIM seating, network settings and software updates step by step, and tell me when the phone antenna may need repair." },
  { id: "technology-1000", title: "Repair a phone after a software failure", category: "technology", text: "After a failed update my [phone model] shows only an error screen. Explain what may have happened, safe steps to try at home, what data I might lose, and when to take it to an authorised service centre in [city]." },
  { id: "technology-1001", title: "Fix a phone volume button not working", category: "technology", text: "The volume buttons on my [phone model] do not work. Explain how to control volume from the screen settings instead, test if it is a software or hardware problem, and decide whether a button repair is worth doing now." },
  { id: "technology-1002", title: "Decide when to visit authorised service centre", category: "technology", text: "Explain when I should visit an authorised service centre instead of a local shop for my [phone model]. Compare warranty, genuine parts, cost in ₹, and waiting time, and help me decide for a [problem] repair in [city]." },
  { id: "technology-1003", title: "Fix a phone with a loose SIM tray", category: "technology", text: "My SIM tray feels loose and the network keeps dropping on my [phone model]. Explain how to check the tray and SIM seating safely, what never to force, and when a loose tray needs a simple replacement at a repair shop." },
  { id: "technology-1004", title: "Keep a repair bill and warranty safe", category: "technology", text: "Explain why I should keep the repair bill and warranty slip for my [phone model] after a repair in [city]. Tell me what details the bill must show, how long the repair warranty usually lasts, and how to store a photo copy safely." },
  { id: "technology-1005", title: "Fix a phone that drains battery after repair", category: "technology", text: "After a screen repair my [phone model] battery drains much faster than before. Help me check if the new screen, a loose battery connection or a background app is the cause, and what to ask the repair shop to check again." },
  { id: "technology-1006", title: "Decide to repair an old phone for parents", category: "technology", text: "My parents use a [number] year old [phone model] and it needs a ₹[amount] repair. Help me decide if repairing it is sensible for their simple use, such as calls, WhatsApp and photos, or if a basic new phone is better value." },
  { id: "technology-1007", title: "Fix a phone headphone jack not working", category: "technology", text: "My wired earphones do not work in my [phone model] headphone jack. Help me check the earphones on another device, clean dust safely from the jack, test Bluetooth earphones instead, and decide when the jack needs repair." },
  { id: "technology-1008", title: "Understand phone repair costs in India", category: "technology", text: "Explain typical phone repair costs in India in ₹ for common problems: cracked screen, battery, charging port and speaker on a [phone model]. Tell me what affects the price and how to avoid paying too much in [city]." },
  { id: "technology-1009", title: "Fix a phone that vibrates but shows nothing", category: "technology", text: "My [phone model] vibrates when I press the power button but the screen stays black. Explain what this may mean, safe steps such as charging for [number] minutes and a forced restart, and when the screen or battery needs repair." },
  { id: "technology-1010", title: "Back up a phone with a broken screen", category: "technology", text: "My [phone model] screen is broken and I cannot tap anything, but I need my photos. Explain how to back up using a computer, a USB adapter with a mouse, or a repair shop backup service, without losing photos or contacts." },
  { id: "technology-1011", title: "Fix a phone that charges only wirelessly", category: "technology", text: "My [phone model] charges wirelessly but not with a cable. Help me check the cable, charger and port for dust or damage, test another cable, and decide whether the charging port repair is urgent or can wait a week." },
  { id: "technology-1012", title: "Decide when a phone is beyond repair", category: "technology", text: "My [phone model] has a cracked screen, weak battery and slow speed together. Help me work out when the total repair cost in ₹ is more than the phone is worth, and what to do with the old phone safely afterwards." },
  { id: "technology-1013", title: "Fix a phone fingerprint sensor after repair", category: "technology", text: "After a screen repair my fingerprint sensor stopped working on my [phone model]. Explain why this can happen, how to re-add fingerprints, check settings, and what to ask the repair shop to fix under their repair warranty." },
  { id: "technology-1014", title: "Ask the right questions at repair shop", category: "technology", text: "Give me ten questions to ask a repair shop in [city] before I leave my [phone model] for a [problem] repair. Cover price, time, genuine parts, warranty, data safety and what happens if the repair does not fix the problem." },
  { id: "technology-1015", title: "Fix a phone with ghost touch problem", category: "technology", text: "My [phone model] screen taps by itself and opens apps I did not touch. Explain what ghost touch means, safe checks such as removing the screen guard and restarting, and when the screen needs replacement at a repair shop." },
  { id: "technology-1016", title: "Repair a phone damaged by rain", category: "technology", text: "My [phone model] got wet in the rain in [city] and the speaker sounds muffled. Give me safe steps to dry it, test the speaker and charging, and decide when to visit a repair shop before the damage gets worse." },
  { id: "technology-1017", title: "Fix a phone that only works on speaker", category: "technology", text: "I can only hear calls on speaker mode on my [phone model]. Help me check earpiece settings, dust, Bluetooth and a test call to find the cause. Tell me the likely repair cost in ₹ and whether it is worth fixing." },
  { id: "technology-1018", title: "Decide repair cost versus phone value", category: "technology", text: "A shop quoted ₹[amount] to repair my [phone model], which I bought for ₹[amount] two years ago. Help me compare repair cost, remaining life, battery health and new phone prices to decide if repairing is good value or not." },
  { id: "technology-1019", title: "Fix a phone with a damaged back panel", category: "technology", text: "The back panel of my [phone model] cracked after a fall, but everything works. Explain whether I must repair it now, the risks of dust and water entering, the usual cost in ₹, and how a good case can protect it meanwhile." },
  { id: "technology-1020", title: "Get phone data back after a repair", category: "technology", text: "My [phone model] came back from repair with all data erased. Explain how to restore photos, contacts and WhatsApp chats from my cloud backup step by step, check what is missing, and set up automatic backup again today." },
  { id: "technology-1021", title: "Fix a phone that keeps showing ads", category: "technology", text: "My [phone model] shows pop up ads even on the home screen. Help me find which app is causing the ads, remove it safely, check permissions, and protect the phone from installing such apps again in future." },
  { id: "technology-1022", title: "Decide when to replace a phone charger", category: "technology", text: "My charger cable is frayed and my [phone model] charges slowly. Explain how to tell if the cable or charger is faulty, what to look for when buying a safe replacement in [city], and why a very cheap charger can damage the phone." },
  { id: "technology-1023", title: "Fix a phone with a stuck update screen", category: "technology", text: "My [phone model] is stuck on the updating screen for [number] hours. Explain what to do first, such as waiting and charging, when a forced restart is safe, and when I must take it to an authorised service centre in [city]." },
  { id: "technology-1024", title: "Prepare an old phone for exchange", category: "technology", text: "I want to exchange my old [phone model] for a new phone in [city]. Give me a checklist to back up photos, erase all data, remove accounts and SIM, check the phone condition, and get the best exchange value in ₹." },
  { id: "technology-1025", title: "Create a phone care routine monthly", category: "technology", text: "Make me a simple monthly phone care routine for my [phone model] to avoid repairs. Include backing up photos, clearing storage, checking battery health, cleaning the charging port gently, updating apps, and noting any new problem early." },
];
